self.CRG_QUIZ = {"version":"1.0.0","source":{"en":"Léger, M.-A. (2026). Introduction to Cybersecurity Governance for Business Technology Management (3rd ed., v2.51b). Review questions and the public answer key. CC BY-NC 4.0.","fr":"Léger, M.-A. (2026). Introduction à la gouvernance de la cybersécurité pour la gestion des technologies d’affaires (3e éd., v2.51b). Questions de révision et corrigé public. CC BY-NC 4.0."},"chapters":[{"n":1,"title":{"en":"Chapter 1: Basic Concepts of Cybersecurity","fr":"Chapitre 1 : Notions de base de la cybersécurité"},"questions":[{"n":1,"answer":"B","section":{"en":"Clarifying the cybersecurity domain","fr":"Délimiter le domaine de la cybersécurité"},"q":{"en":"Which definition of security does Chapter 1 adopt as the most useful for managers?","fr":"Quelle définition de la sécurité le chapitre 1 retient-il comme la plus utile pour les gestionnaires?"},"options":{"en":["The complete elimination of all known technical vulnerabilities","The absence of unacceptable risk","Full conformity with every applicable security standard","A period of at least one year without reported incidents"],"fr":["L’élimination complète de toutes les vulnérabilités techniques connues","L’absence de risque inacceptable","La conformité totale à chaque norme de sécurité applicable","Une période d’au moins un an sans incident signalé"]}},{"n":2,"answer":"D","section":{"en":"The CIA triad: defining security objectives in business terms","fr":"La triade CID : définir les objectifs de sécurité en termes d’affaires"},"q":{"en":"Why does the chapter suggest that integrity failures can be more dangerous than confidentiality breaches?","fr":"Pourquoi le chapitre laisse-t-il entendre que les défaillances d’intégrité peuvent être plus dangereuses que les atteintes à la confidentialité?"},"options":{"en":["They always become public and damage reputation immediately","They can only be caused by sophisticated state-sponsored actors","They mainly affect backup systems rather than live operations","They can remain undetected while decisions continue to rely on corrupted data"],"fr":["Elles deviennent toujours publiques et nuisent immédiatement à la réputation","Elles ne peuvent être causées que par des acteurs sophistiqués parrainés par un État","Elles touchent surtout les systèmes de sauvegarde plutôt que les opérations courantes","Elles peuvent passer inaperçues alors que les décisions continuent de reposer sur des données corrompues"]}},{"n":3,"answer":"A","section":{"en":"Data classification: translating business value into protection requirements","fr":"Résumé du chapitre"},"q":{"en":"A customer platform encrypts personal data and restricts access tightly, but collects far more data than its stated purpose requires. What does this illustrate?","fr":"Une plateforme destinée aux clients chiffre les données personnelles et en restreint étroitement l’accès, mais recueille bien plus de données que ne l’exige sa finalité déclarée. Qu’est-ce que cela illustre?"},"options":{"en":["Privacy can be violated even when confidentiality is maintained","Confidentiality failures are the main source of privacy harm","Encryption fully satisfies the organization's privacy obligations","Data minimization is a purely technical access-control matter"],"fr":["La vie privée peut être violée même lorsque la confidentialité est maintenue","Les défaillances de confidentialité sont la principale source d’atteinte à la vie privée","Le chiffrement satisfait entièrement aux obligations de l’organisation en matière de vie privée","La minimisation des données est une question purement technique de contrôle d’accès"]}},{"n":4,"answer":"C","section":{"en":"Data classification: translating business value into protection requirements","fr":"Classification des données : traduire la valeur d’affaires en exigences de protection"},"q":{"en":"According to the chapter, who should normally determine the classification of a significant information asset?","fr":"Selon le chapitre, qui devrait normalement déterminer la classification d’un actif informationnel important?"},"options":{"en":["The system administrator who maintains the hosting platform","The CISO, because classification is a security function","The business information owner who understands its purpose","The external auditor who reviews the classification scheme"],"fr":["L’administrateur de système qui maintient la plateforme d’hébergement","Le CSI, parce que la classification est une fonction de sécurité","Le responsable métier de l’information, qui en comprend la finalité","L’auditeur externe qui examine le schéma de classification"]}},{"n":5,"answer":"C","section":{"en":"Data classification: translating business value into protection requirements","fr":"Classification des données : traduire la valeur d’affaires en exigences de protection"},"q":{"en":"An employee list containing names, employee numbers, work locations, and schedules is labelled Internal because each field seems harmless alone. Which classification principle has been overlooked?","fr":"Une liste d’employés contenant les noms, les numéros d’employé, les lieux de travail et les horaires est étiquetée Interne parce que chaque champ semble inoffensif pris isolément. Quel principe de classification a été négligé?"},"options":{"en":["Labels must be consistent across cloud and physical records","Classification should begin with technology, not business activities","Combining data elements can make information more sensitive","Classification schemes should use more than four levels"],"fr":["Les étiquettes doivent être cohérentes entre les dossiers infonuagiques et physiques","La classification devrait partir de la technologie, et non des activités d’affaires","La combinaison d’éléments de données peut rendre l’information plus sensible","Les schémas de classification devraient comporter plus de quatre niveaux"]}},{"n":6,"answer":"A","section":{"en":"The fraud triangle: explaining why insiders misbehave","fr":"Le triangle de la fraude : expliquer pourquoi des initiés commettent des actes répréhensibles"},"q":{"en":"Which three elements make up the fraud triangle?","fr":"Quels sont les trois éléments du triangle de la fraude?"},"options":{"en":["Opportunity, pressure (or need), and rationalization","Threat, vulnerability, and exposure to harm","Confidentiality, integrity, and availability of data","Motive, means, and detection of the wrongdoing"],"fr":["L’occasion, la pression (ou le besoin) et la rationalisation","La menace, la vulnérabilité et l’exposition au préjudice","La confidentialité, l’intégrité et la disponibilité des données","Le mobile, les moyens et la détection de l’acte répréhensible"]}},{"n":7,"answer":"D","section":{"en":"The human factor: usable policies, continuous awareness, and the zero-trust mindset","fr":"Le facteur humain : des politiques applicables au quotidien, une sensibilisation continue et le réflexe de vérification systématique"},"q":{"en":"Which element of the fraud triangle can governance influence most directly through design choices?","fr":"Sur quel élément du triangle de la fraude la gouvernance peut-elle agir le plus directement par ses choix de conception?"},"options":{"en":["Pressure, by monitoring employees' personal finances closely","Rationalization, by requiring annual ethics declarations","Pressure and rationalization, through stricter discipline alone","Opportunity, through least privilege, segregation of duties, and monitoring"],"fr":["La pression, en surveillant de près les finances personnelles des employés","La rationalisation, en exigeant des déclarations éthiques annuelles","La pression et la rationalisation, par une discipline plus stricte seulement","L’occasion, par le principe du moindre privilège, la séparation des tâches et la surveillance"]}},{"n":8,"answer":"B","section":{"en":"The fraud triangle: explaining why insiders misbehave","fr":"Classification des données : traduire la valeur d’affaires en exigences de protection"},"q":{"en":"An employee who copies client files before leaving says, “They owe me after all my unpaid overtime.” Which fraud triangle element does this statement represent?","fr":"Un employé qui copie des dossiers de clients avant de partir déclare : « Ils me doivent bien ça après toutes mes heures supplémentaires non payées. » Quel élément du triangle de la fraude cette déclaration représente-t-elle?"},"options":{"en":["Opportunity created by weak controls","Rationalization of the wrongdoing","Pressure from financial distress","Exposure of the organization"],"fr":["L’occasion créée par des contrôles déficients","La rationalisation de l’acte répréhensible","La pression causée par des difficultés financières","L’exposition de l’organisation"]}},{"n":9,"answer":"A","section":{"en":"The risk triangle: how cyber risk emerges","fr":"Le triangle du risque : comment naît le cyberrisque"},"q":{"en":"In the risk triangle, how should missing backups and weak change approvals be classified?","fr":"Dans le triangle du risque, comment faut-il classer l’absence de sauvegardes et la faiblesse des approbations de changements?"},"options":{"en":["As procedural vulnerabilities","As threat events","As exposure","As residual risks"],"fr":["Comme des vulnérabilités procédurales","Comme des événements de menace","Comme de l’exposition","Comme des risques résiduels"]}},{"n":10,"answer":"C","section":{"en":"The risk triangle: how cyber risk emerges","fr":"Le triangle du risque : comment naît le cyberrisque"},"q":{"en":"A firm invests in regularly tested backups, system redundancy, and crisis communications capability. Which risk lever is it mainly using?","fr":"Une entreprise investit dans des sauvegardes testées régulièrement, la redondance des systèmes et une capacité de communication de crise. Quel levier de risque utilise-t-elle principalement?"},"options":{"en":["Reducing likelihood by increasing deterrence","Transferring risk to an external party","Reducing impact by strengthening resilience","Avoiding risk by stopping the activity"],"fr":["Réduire la vraisemblance en augmentant la dissuasion","Transférer le risque à une partie externe","Réduire l’impact en renforçant la résilience","Éviter le risque en cessant l’activité"]}},{"n":11,"answer":"B","section":{"en":"Chapter summary","fr":"Le triangle du risque : comment naît le cyberrisque"},"q":{"en":"What does the chapter mean by defence in depth?","fr":"Qu’entend le chapitre par défense en profondeur?"},"options":{"en":["Concentrating the budget on the single strongest preventive control","Layering preventive, detective, and recovery controls so one failure is not fatal","Requiring every user to pass several authentication steps for each system","Placing the most sensitive systems physically deep within the data centre"],"fr":["Concentrer le budget sur le contrôle préventif le plus robuste","Superposer des contrôles préventifs, de détection et de reprise pour qu’une défaillance ne soit pas fatale","Exiger de chaque utilisateur plusieurs étapes d’authentification pour chaque système","Placer physiquement les systèmes les plus sensibles au cœur du centre de données"]}},{"n":12,"answer":"D","section":{"en":"Data classification: translating business value into protection requirements","fr":"Classification des données : traduire la valeur d’affaires en exigences de protection"},"q":{"en":"A company stops offering a service in a market where it cannot meet data protection expectations, so the risk no longer exists. Which treatment option is this?","fr":"Une entreprise cesse d’offrir un service dans un marché où elle ne peut pas répondre aux attentes en matière de protection des données, de sorte que le risque n’existe plus. De quelle option de traitement s’agit-il?"},"options":{"en":["Accepting the risk within appetite","Transferring the risk through insurance","Mitigating the risk with new controls","Avoiding the risk by changing the activity"],"fr":["Accepter le risque dans les limites de l’appétence","Transférer le risque au moyen d’une assurance","Atténuer le risque par de nouveaux contrôles","Éviter le risque en modifiant l’activité"]}},{"n":13,"answer":"D","section":{"en":"Risk treatment: accept, avoid, transfer, mitigate, and manage residual risk","fr":"Classification des données : traduire la valeur d’affaires en exigences de protection"},"q":{"en":"How does mature governance handle residual risk after controls are implemented?","fr":"Comment une gouvernance mature traite-t-elle le risque résiduel une fois les contrôles mis en œuvre?"},"options":{"en":["It assumes residual risk is negligible once controls are tested","It delegates residual risk decisions to the security operations team","It records residual risk only when an incident has occurred","It documents it, has risk owners approve it, and reviews it periodically"],"fr":["Elle suppose que le risque résiduel est négligeable une fois les contrôles testés","Elle délègue les décisions sur le risque résiduel à l’équipe des opérations de sécurité","Elle consigne le risque résiduel seulement lorsqu’un incident s’est produit","Elle le documente, le fait approuver par les responsables du risque et le revoit périodiquement"]}},{"n":14,"answer":"B","section":{"en":"Governance assurance: the Three Lines Model, audit, and continuous improvement","fr":"Assurance en matière de gouvernance : le modèle des trois lignes, l’audit et l’amélioration continue"},"q":{"en":"In the Three Lines Model as presented in the chapter, what is the distinctive role of internal audit?","fr":"Dans le modèle des trois lignes tel que présenté dans le chapitre, quel est le rôle distinctif de l’audit interne?"},"options":{"en":["Deploying and maintaining security controls in daily operations","Providing independent, objective assurance directly to the board","Formulating security policies and monitoring first-line controls","Allocating the resources needed for cyber risk management"],"fr":["Déployer et maintenir les contrôles de sécurité dans les opérations quotidiennes","Fournir une assurance indépendante et objective directement au conseil d’administration","Formuler les politiques de sécurité et surveiller les contrôles de la première ligne","Affecter les ressources nécessaires à la gestion du cyberrisque"]}},{"n":15,"answer":"C","section":{"en":"Security is the absence of unacceptable risk","fr":"La sécurité est l’absence de risque inacceptable"},"q":{"en":"A team argues that a long-standing exposure is acceptable because nothing has gone wrong in years. Which bias does the chapter associate with this reasoning?","fr":"Une équipe soutient qu’une exposition qui dure depuis longtemps est acceptable parce que rien de fâcheux ne s’est produit depuis des années. À quel biais le chapitre associe-t-il ce raisonnement?"},"options":{"en":["Availability bias, overweighting vivid recent events","Authority bias, deferring to senior stakeholders","Normalization of deviance, underestimating familiar exposures","Confirmation bias, seeking evidence for an initial view"],"fr":["Le biais de disponibilité, qui accorde trop de poids aux événements récents et marquants","Le biais d’autorité, qui pousse à s’en remettre aux parties prenantes de haut rang","La normalisation de la déviance, qui sous-estime les expositions familières","Le biais de confirmation, qui pousse à chercher des preuves appuyant une opinion initiale"]}},{"n":16,"answer":"A","section":{"en":"Cybersecurity maturity: from ad hoc practices to embedded capability","fr":"Maturité en cybersécurité : des pratiques ponctuelles à une capacité intégrée"},"q":{"en":"Staff perform security tasks in similar ways, but nothing is documented, standardized, or taught, so results depend on individuals. Which maturity level is this?","fr":"Le personnel exécute les tâches de sécurité de façon semblable, mais rien n’est documenté, normalisé ni enseigné, de sorte que les résultats dépendent des individus. De quel niveau de maturité s’agit-il?"},"options":{"en":["Level 2, repeatable but intuitive","Level 1, initial or ad hoc","Level 3, defined process","Level 4, managed and measurable"],"fr":["Niveau 2, reproductible mais intuitif","Niveau 1, initial ou ponctuel","Niveau 3, processus défini","Niveau 4, géré et mesurable"]}},{"n":17,"answer":"C","section":{"en":"Cybersecurity maturity: from ad hoc practices to embedded capability","fr":"Maturité en cybersécurité : des pratiques ponctuelles à une capacité intégrée"},"q":{"en":"A small organization with modest exposure is setting maturity targets. Which approach is most consistent with the chapter?","fr":"Une petite organisation modestement exposée fixe ses cibles de maturité. Quelle approche est la plus conforme au chapitre?"},"options":{"en":["Target level 5 everywhere to demonstrate leadership commitment","Set no targets until a serious incident reveals the main gaps","Target defined, repeatable levels broadly and higher levels for critical services","Copy the targets of the largest firm in its industry"],"fr":["Viser le niveau 5 partout pour démontrer l’engagement de la direction","Ne fixer aucune cible tant qu’un incident grave n’a pas révélé les principales lacunes","Viser en général les niveaux « défini » et « reproductible », et des niveaux plus élevés pour les services critiques","Copier les cibles de la plus grande entreprise de son secteur"]}},{"n":18,"answer":"D","section":{"en":"The human factor: usable policies, continuous awareness, and the zero-trust mindset","fr":"Le facteur humain : des politiques applicables au quotidien, une sensibilisation continue et le réflexe de vérification systématique"},"q":{"en":"How does the chapter describe the zero-trust mindset that leaders should internalize?","fr":"Comment le chapitre décrit-il le réflexe de vérification systématique que les dirigeants devraient intérioriser?"},"options":{"en":["Trusted employees should receive broader access to reduce friction","Trust is earned once at hiring through thorough background checks","Zero trust applies only to external partners and remote users","Trust is not a control, so access is managed as if compromise is possible"],"fr":["Les employés de confiance devraient recevoir des accès plus étendus pour réduire les frictions","La confiance s’acquiert une fois pour toutes à l’embauche, au moyen de vérifications approfondies des antécédents","La vérification systématique s’applique seulement aux partenaires externes et aux utilisateurs à distance","La confiance n’est pas un contrôle; l’accès est donc géré comme si une compromission était possible"]}},{"n":19,"answer":"A","section":{"en":"Governance assurance: the Three Lines Model, audit, and continuous improvement","fr":"Assurance en matière de gouvernance : le modèle des trois lignes, l’audit et l’amélioration continue"},"q":{"en":"Which statement best captures the chapter's distinction between audit and risk assessment?","fr":"Quel énoncé rend le mieux la distinction que fait le chapitre entre l’audit et l’évaluation des risques?"},"options":{"en":["Audit is retrospective and evidence-based; risk assessment is forward-looking","Audit estimates future threats; risk assessment verifies past compliance","Audit and risk assessment are interchangeable terms for the same activity","Risk assessment replaces audit once an organization reaches maturity level 4"],"fr":["L’audit est rétrospectif et fondé sur des preuves; l’évaluation des risques est prospective","L’audit estime les menaces futures; l’évaluation des risques vérifie la conformité passée","L’audit et l’évaluation des risques sont des termes interchangeables pour la même activité","L’évaluation des risques remplace l’audit lorsqu’une organisation atteint le niveau de maturité 4"]}},{"n":20,"answer":"B","section":{"en":"Case study integration: why governance failures amplify cyber incidents","fr":"Intégration des études de cas : pourquoi les défaillances de gouvernance amplifient les cyberincidents"},"q":{"en":"Which governance lesson does the chapter draw from the 2013 Target breach?","fr":"Quelle leçon de gouvernance le chapitre tire-t-il de la violation de données subie par Target en 2013?"},"options":{"en":["Retain customer data only for inactive accounts to reduce exposure","Treat suppliers as first-class risks, constrain their access, and enforce segmentation","Rely on monitoring tools as passive records for later investigation","Prioritize confidentiality controls over all third-party contracts"],"fr":["Conserver les données des clients seulement pour les comptes inactifs afin de réduire l’exposition","Traiter les fournisseurs comme des risques de premier plan, restreindre leur accès et imposer la segmentation","S’appuyer sur les outils de surveillance comme des registres passifs pour les enquêtes ultérieures","Faire passer les contrôles de confidentialité avant tous les contrats avec des tiers"]}}]},{"n":2,"title":{"en":"Chapter 2: Cybersecurity Governance","fr":"Chapitre 2 : Gouvernance de la cybersécurité"},"questions":[{"n":1,"answer":"A","section":{"en":"Governance as direction, control, and accountability","fr":"Des mesures de gouvernance SMART : rendre la mesure crédible"},"q":{"en":"According to COBIT 2019 and ISO/IEC 38500, which cycle describes how governance exercises its role?","fr":"Selon COBIT 2019 et l’ISO/IEC 38500, quel cycle décrit la façon dont la gouvernance exerce son rôle?"},"options":{"en":["Evaluate, Direct, Monitor","Plan, Do, Check, Act","Plan, Build, Run, Monitor","Identify, Protect, Detect"],"fr":["Évaluer, Diriger, Surveiller","Planifier, Réaliser, Vérifier, Agir","Planifier, Bâtir, Exécuter, Surveiller","Identifier, Protéger, Détecter"]}},{"n":2,"answer":"C","section":{"en":"Governance as direction, control, and accountability","fr":"La gouvernance comme orientation, contrôle et imputabilité"},"q":{"en":"Which activity best reflects management rather than governance in the chapter's distinction?","fr":"Quelle activité relève le mieux de la gestion plutôt que de la gouvernance, selon la distinction du chapitre?"},"options":{"en":["Approving the organization's cybersecurity risk appetite","Directing policies and strategies for cyber risk","Planning, building, and operating systems day to day","Evaluating stakeholder needs and strategic risks"],"fr":["Approuver l’appétence pour le risque de cybersécurité de l’organisation","Diriger les politiques et les stratégies relatives au cyberrisque","Planifier, bâtir et exploiter les systèmes au quotidien","Évaluer les besoins des parties prenantes et les risques stratégiques"]}},{"n":3,"answer":"B","section":{"en":"Governance as direction, control, and accountability","fr":"La gouvernance comme orientation, contrôle et imputabilité"},"q":{"en":"What does the chapter say typically happens when senior leadership treats cybersecurity as a purely technical matter for IT?","fr":"Selon le chapitre, que se passe-t-il généralement lorsque la haute direction traite la cybersécurité comme une question purement technique relevant des TI?"},"options":{"en":["Technical controls become too expensive to operate","Strategic questions about appetite, resources, and trade-offs remain unanswered","The board becomes overly involved in operational decisions","Compliance reporting becomes more frequent and detailed"],"fr":["Les contrôles techniques deviennent trop coûteux à exploiter","Les questions stratégiques sur l’appétence, les ressources et les compromis restent sans réponse","Le conseil d’administration s’ingère trop dans les décisions opérationnelles","La reddition de comptes sur la conformité devient plus fréquente et plus détaillée"]}},{"n":4,"answer":"D","section":{"en":"Governance as direction, control, and accountability","fr":"Des mesures de gouvernance SMART : rendre la mesure crédible"},"q":{"en":"Which statement best describes the governance principle of participation?","fr":"Quel énoncé décrit le mieux le principe de gouvernance de la participation?"},"options":{"en":["Stakeholders can see what is being done and why decisions are made","Decisions have identified owners whose results are monitored","The organization adapts quickly as threats and incidents evolve","Relevant cross-functional expertise is included in decision-making"],"fr":["Les parties prenantes peuvent voir ce qui est fait et pourquoi les décisions sont prises","Les décisions ont des responsables désignés dont les résultats sont surveillés","L’organisation s’adapte rapidement à l’évolution des menaces et des incidents","L’expertise interfonctionnelle pertinente est intégrée à la prise de décision"]}},{"n":5,"answer":"B","section":{"en":"Applied ethics and why governance exists","fr":"L’éthique appliquée et la raison d’être de la gouvernance"},"q":{"en":"Why does the chapter argue that ethical norms alone are not sufficient for cybersecurity governance?","fr":"Pourquoi le chapitre soutient-il que les normes éthiques seules ne suffisent pas à la gouvernance de la cybersécurité?"},"options":{"en":["Most employees are assumed to act maliciously when unobserved","Complex systems create opportunities for misuse and incentives can drift","Ethical norms never change and therefore become outdated","Laws already cover every cybersecurity situation that can arise"],"fr":["On présume que la plupart des employés agissent avec malveillance lorsqu’ils ne sont pas observés","Les systèmes complexes créent des occasions d’abus et les incitatifs peuvent dériver","Les normes éthiques ne changent jamais et deviennent donc désuètes","Les lois couvrent déjà toutes les situations de cybersécurité possibles"]}},{"n":6,"answer":"A","section":{"en":"A hierarchy of governance: enterprise, IT, and cybersecurity","fr":"Résumé du chapitre"},"q":{"en":"How does the chapter position cybersecurity governance relative to enterprise and IT governance?","fr":"Comment le chapitre situe-t-il la gouvernance de la cybersécurité par rapport à la gouvernance d’entreprise et à la gouvernance des TI?"},"options":{"en":["Derived from enterprise governance and intersecting with, but not identical to, IT governance","Independent of enterprise governance and identical to IT governance","A subset of IT governance with no links to legal or human resources","A replacement for enterprise governance in digital organizations"],"fr":["Elle découle de la gouvernance d’entreprise et recoupe la gouvernance des TI sans s’y confondre","Elle est indépendante de la gouvernance d’entreprise et identique à la gouvernance des TI","Elle est un sous-ensemble de la gouvernance des TI sans lien avec les services juridiques ou les ressources humaines","Elle remplace la gouvernance d’entreprise dans les organisations numériques"]}},{"n":7,"answer":"D","section":{"en":"A hierarchy of governance: enterprise, IT, and cybersecurity","fr":"Résumé du chapitre"},"q":{"en":"Which function did NIST add to the Cybersecurity Framework in version 2.0, released in February 2024?","fr":"Quelle fonction le NIST a-t-il ajoutée au Cadre de cybersécurité dans la version 2.0, publiée en février 2024?"},"options":{"en":["Recover","Respond","Identify","Govern"],"fr":["Rétablir","Répondre","Identifier","Gouverner"]}},{"n":8,"answer":"C","section":{"en":"What cybersecurity governance must achieve","fr":"Ce que la gouvernance de la cybersécurité doit accomplir"},"q":{"en":"A board requires every cybersecurity investment to be linked to risk reduction, resilience requirements, or legal obligations rather than vendor pressure. Which governance outcome does this serve?","fr":"Un conseil d’administration exige que chaque investissement en cybersécurité soit lié à une réduction du risque, à des exigences de résilience ou à des obligations légales plutôt qu’à la pression des fournisseurs. Quel résultat de gouvernance cela sert-il?"},"options":{"en":["Setting strategic direction","Ensuring compliance and defensibility","Ensuring rational resource allocation","Establishing decision rights"],"fr":["Fixer l’orientation stratégique","Assurer la conformité et le caractère défendable","Assurer une affectation rationnelle des ressources","Établir les droits décisionnels"]}},{"n":9,"answer":"C","section":{"en":"What cybersecurity governance must achieve","fr":"Ce que la gouvernance de la cybersécurité doit accomplir"},"q":{"en":"What does the EU NIS2 Directive require of the management bodies of essential and important entities, as described in the chapter?","fr":"Selon le chapitre, qu’exige la directive NIS2 de l’Union européenne des organes de direction des entités essentielles et importantes?"},"options":{"en":["Annual disclosure of board oversight under Regulation S-K Item 106","Delegating cybersecurity oversight entirely to the CISO","Approving and overseeing risk-management measures, following training, and potential liability","Reporting technology risk accountability to OSFI each quarter"],"fr":["La communication annuelle de la surveillance exercée par le conseil en vertu de l’Item 106 du Regulation S-K","La délégation entière de la surveillance de la cybersécurité au CSI","L’approbation et la surveillance des mesures de gestion des risques, le suivi d’une formation et une responsabilité possible","Une reddition de comptes trimestrielle au BSIF sur l’imputabilité en matière de risque technologique"]}},{"n":10,"answer":"B","section":{"en":"What cybersecurity governance must achieve","fr":"Ce que la gouvernance de la cybersécurité doit accomplir"},"q":{"en":"Under Québec's Law 25, who is responsible by default for the protection of personal information in an enterprise?","fr":"En vertu de la Loi 25 du Québec, qui est responsable par défaut de la protection des renseignements personnels dans une entreprise?"},"options":{"en":["The chief information security officer","The person exercising the highest authority","The general counsel or legal department","The chair of the board's audit committee"],"fr":["Le chef de la sécurité de l’information","La personne ayant la plus haute autorité","Le chef du contentieux ou le service juridique","La présidence du comité d’audit du conseil d’administration"]}},{"n":11,"answer":"A","section":{"en":"What cybersecurity governance must achieve","fr":"Des mesures de gouvernance SMART : rendre la mesure crédible"},"q":{"en":"Of the four elements that enable governance, which one does the chapter describe as shaping behaviour when no one is watching?","fr":"Parmi les quatre éléments qui rendent la gouvernance possible, lequel, selon le chapitre, façonne le comportement quand personne ne regarde?"},"options":{"en":["Culture","Leadership","Processes","Mechanisms"],"fr":["La culture","Le leadership","Les processus","Les mécanismes"]}},{"n":12,"answer":"D","section":{"en":"Change management as a governance requirement","fr":"La gestion du changement, une exigence de gouvernance"},"q":{"en":"Business units push back on a new approval step, arguing it delays urgent orders. How does the chapter advise governance to respond?","fr":"Des unités d’affaires s’opposent à une nouvelle étape d’approbation en faisant valoir qu’elle retarde les commandes urgentes. Comment le chapitre conseille-t-il à la gouvernance de réagir?"},"options":{"en":["Enforce the control strictly, since discipline produces lasting outcomes","Withdraw the control, since resistance shows it is unnecessary","Delegate the decision to IT, since controls are a technical matter","Determine whether this is normal resistance or a legitimate critique of the control's design"],"fr":["Appliquer le contrôle strictement, puisque la discipline produit des résultats durables","Retirer le contrôle, puisque la résistance montre qu’il est inutile","Déléguer la décision aux TI, puisque les contrôles sont une question technique","Déterminer s’il s’agit d’une résistance normale ou d’une critique légitime de la conception du contrôle"]}},{"n":13,"answer":"A","section":{"en":"Implementing a governance framework","fr":"Mettre en œuvre un cadre de gouvernance"},"q":{"en":"With which standard does ISO/IEC 38500:2024 align, adopting its broader set of eleven principles?","fr":"Sur quelle norme l’ISO/IEC 38500:2024 s’aligne-t-elle, en adoptant son ensemble élargi de onze principes?"},"options":{"en":["ISO 37000:2021, Governance of organizations","ISO/IEC 27001:2022, information security management","ISO 37301:2021, compliance management systems","ITIL 4, the service management framework"],"fr":["ISO 37000:2021, gouvernance des organisations","ISO/IEC 27001:2022, gestion de la sécurité de l’information","ISO 37301:2021, systèmes de gestion de la conformité","ITIL 4, le cadre de gestion des services"]}},{"n":14,"answer":"C","section":{"en":"SMART governance metrics: making measurement credible","fr":"Des mesures de gouvernance SMART : rendre la mesure crédible"},"q":{"en":"A manager is held answerable for cybersecurity outcomes in her division but receives no authority or budget to change anything. Which governance failure does this illustrate?","fr":"Une gestionnaire doit répondre des résultats de cybersécurité de sa division, mais ne reçoit ni l’autorité ni le budget pour changer quoi que ce soit. Quelle défaillance de gouvernance cela illustre-t-il?"},"options":{"en":["Strategy that is not aligned with business objectives","Acquisition decisions lacking lifecycle evaluation","Accountability assigned without authority and resources","Conformance treated as a checklist exercise"],"fr":["Une stratégie qui n’est pas alignée sur les objectifs d’affaires","Des décisions d’acquisition sans évaluation du cycle de vie","Une imputabilité attribuée sans autorité ni ressources","Une conformité traitée comme une liste de vérification"]}},{"n":15,"answer":"D","section":{"en":"Implementing a governance framework","fr":"Mettre en œuvre un cadre de gouvernance"},"q":{"en":"What does the chapter's discussion of the conformance principle imply about compliance and security?","fr":"Qu’implique la discussion du chapitre sur le principe de conformité quant aux rapports entre conformité et sécurité?"},"options":{"en":["Compliance with standards guarantees an acceptable security posture","Compliance is optional when risk management is mature","Compliance belongs to legal teams rather than to governance","An organization can be compliant and still insecure if compliance is a checklist"],"fr":["La conformité aux normes garantit une posture de sécurité acceptable","La conformité devient facultative lorsque la gestion des risques est mature","La conformité relève des équipes juridiques plutôt que de la gouvernance","Une organisation peut être conforme et demeurer peu sûre si la conformité n’est qu’une liste de vérification"]}},{"n":16,"answer":"B","section":{"en":"Chapter summary","fr":"Résumé du chapitre"},"q":{"en":"Which of the following is a leading indicator in a balanced cybersecurity scorecard?","fr":"Lequel des éléments suivants est un indicateur avancé dans un tableau de bord équilibré de la cybersécurité?"},"options":{"en":["Number of incidents in the quarter","Backup restoration testing success rate","Mean time to recover from incidents","Total magnitude of losses from incidents"],"fr":["Le nombre d’incidents au cours du trimestre","Le taux de réussite des tests de restauration des sauvegardes","Le délai moyen de rétablissement après un incident","L’ampleur totale des pertes causées par les incidents"]}},{"n":17,"answer":"D","section":{"en":"The balanced cybersecurity scorecard as a governance tool","fr":"Le tableau de bord équilibré de la cybersécurité, un outil de gouvernance"},"q":{"en":"In the balanced cybersecurity scorecard, which perspective covers vulnerability management, identity and access management, and incident detection and response?","fr":"Dans le tableau de bord équilibré de la cybersécurité, quelle perspective couvre la gestion des vulnérabilités, la gestion des identités et des accès, ainsi que la détection des incidents et l’intervention?"},"options":{"en":["Financial perspective","Customer or stakeholder perspective","Learning and growth perspective","Internal process perspective"],"fr":["La perspective financière","La perspective clients ou parties prenantes","La perspective apprentissage et croissance","La perspective processus internes"]}},{"n":18,"answer":"A","section":{"en":"SMART governance metrics: making measurement credible","fr":"Des mesures de gouvernance SMART : rendre la mesure crédible"},"q":{"en":"A proposed board metric reads “Improve security awareness.” Which SMART criteria does it most clearly fail?","fr":"Une mesure proposée au conseil d’administration se lit ainsi : « Améliorer la sensibilisation à la sécurité ». À quels critères SMART échoue-t-elle le plus clairement?"},"options":{"en":["Specific, measurable, and time-bound","Achievable and relevant only","Relevant and time-bound only","Achievable and measurable only"],"fr":["Spécifique, mesurable et temporellement définie","Atteignable et pertinente seulement","Pertinente et temporellement définie seulement","Atteignable et mesurable seulement"]}},{"n":19,"answer":"B","section":{"en":"SMART governance metrics: making measurement credible","fr":"Des mesures de gouvernance SMART : rendre la mesure crédible"},"q":{"en":"In the Matériaux Kamouraska scenario, what role does the new CISO play in risk acceptance decisions?","fr":"Dans la mise en situation de Matériaux Kamouraska, quel rôle joue le nouveau CSI dans les décisions d’acceptation du risque?"},"options":{"en":["Accepts all residual risks on behalf of plant vice-presidents","Advises on decisions but does not accept business risk for others","Approves only those risks that fall outside board appetite","Has no role, since risk decisions belong to the executive committee"],"fr":["Il accepte tous les risques résiduels au nom des vice-présidents d’usine","Il conseille sur les décisions, mais n’accepte pas le risque d’affaires au nom d’autrui","Il approuve seulement les risques qui dépassent l’appétence du conseil","Il n’a aucun rôle, puisque les décisions sur le risque appartiennent au comité de direction"]}},{"n":20,"answer":"C","section":{"en":"SMART governance metrics: making measurement credible","fr":"Des mesures de gouvernance SMART : rendre la mesure crédible"},"q":{"en":"The first report under Kamouraska's new scorecard showed two failed restoration tests and six expired exceptions. How does the chapter interpret this?","fr":"Le premier rapport produit avec le nouveau tableau de bord de Kamouraska faisait état de deux tests de restauration échoués et de six exceptions expirées. Comment le chapitre interprète-t-il ce résultat?"},"options":{"en":["As evidence that the scorecard metrics were poorly designed","As a reason to return to the previous technical dashboard","As governance working, prompting a funded remediation plan","As a failure of the CISO that required a change of reporting line"],"fr":["Comme la preuve que les mesures du tableau de bord étaient mal conçues","Comme une raison de revenir à l’ancien tableau de bord technique","Comme le signe d’une gouvernance qui fonctionne, menant à un plan de mesures correctives financé","Comme un échec du CSI exigeant un changement de lien hiérarchique"]}}]},{"n":3,"title":{"en":"Chapter 3: Cybersecurity Compliance","fr":"Chapitre 3 : Conformité en cybersécurité"},"questions":[{"n":1,"answer":"C","section":{"en":"Chapter summary","fr":"Résumé du chapitre"},"q":{"en":"Which earlier standard did ISO 37301:2021 replace?","fr":"Quelle norme antérieure l’ISO 37301:2021 a-t-elle remplacée?"},"options":{"en":["ISO/IEC 27001:2013 on information security","ISO 37000:2021 on governance of organizations","ISO 19600:2014, a guidance standard","ISO 37002:2021 on whistleblowing management"],"fr":["L’ISO/IEC 27001:2013 sur la sécurité de l’information","L’ISO 37000:2021 sur la gouvernance des organisations","L’ISO 19600:2014, une norme de lignes directrices","L’ISO 37002:2021 sur la gestion des alertes"]}},{"n":2,"answer":"A","section":{"en":"Chapter summary","fr":"Mettre en œuvre un système de gestion de la conformité en cybersécurité aligné sur le cycle PDCA"},"q":{"en":"What does the fact that ISO 37301 is a requirements standard, rather than guidance only, make possible?","fr":"Que rend possible le fait que l’ISO 37301 soit une norme d’exigences, et non une simple norme de lignes directrices?"},"options":{"en":["Certification of the compliance management system","Exemption from legal and regulatory obligations","Replacement of internal audit by external audit","Automatic recognition by all Canadian regulators"],"fr":["La certification du système de gestion de la conformité","L’exemption des obligations légales et réglementaires","Le remplacement de l’audit interne par l’audit externe","La reconnaissance automatique par tous les organismes de réglementation canadiens"]}},{"n":3,"answer":"D","section":{"en":"Implementing a PDCA-aligned compliance management system for cybersecurity","fr":"Mettre en œuvre un système de gestion de la conformité en cybersécurité aligné sur le cycle PDCA"},"q":{"en":"A major customer's contract requires breach notification within a specific timeframe and grants audit rights. Which family of compliance obligations does this belong to?","fr":"Le contrat d’un client important exige un avis de violation dans un délai précis et accorde des droits d’audit. À quelle famille d’obligations de conformité cela appartient-il?"},"options":{"en":["Legal and regulatory obligations","Adopted standards and frameworks","Internal policies and procedures","Contractual obligations"],"fr":["Obligations légales et réglementaires","Normes et cadres adoptés","Politiques et procédures internes","Obligations contractuelles"]}},{"n":4,"answer":"B","section":{"en":"Chapter summary","fr":"Résumé du chapitre"},"q":{"en":"Which statement best reflects the chapter's description of compliance as a living capability?","fr":"Quel énoncé reflète le mieux la description de la conformité comme capacité vivante faite par le chapitre?"},"options":{"en":["Achieving perfect conformity once and certifying it annually","Continuously knowing what applies, doing it, verifying it, and correcting findings","Completing a checklist whenever an external audit is scheduled","Writing a policy for each obligation and filing it securely"],"fr":["Atteindre une conformité parfaite une fois, puis la faire certifier chaque année","Savoir en continu ce qui s’applique, le faire, le vérifier et corriger les constatations","Remplir une liste de vérification chaque fois qu’un audit externe est prévu","Rédiger une politique pour chaque obligation et la classer en lieu sûr"]}},{"n":5,"answer":"A","section":{"en":"Compliance as a management system","fr":"La conformité en tant que système de gestion"},"q":{"en":"Which question is part of defining the scope of a cybersecurity compliance management system?","fr":"Quelle question fait partie de la définition de la portée d’un système de gestion de la conformité en cybersécurité?"},"options":{"en":["Which third parties, cloud providers, or processors sit inside the compliance boundary?","Which security vendor offers the lowest licensing cost?","Which employees have the most years of service?","Which competitors have obtained ISO certification?"],"fr":["Quels tiers, fournisseurs infonuagiques ou sous-traitants se trouvent à l’intérieur du périmètre de conformité?","Quel fournisseur de sécurité offre le coût de licence le plus bas?","Quels employés ont le plus d’années de service?","Quels concurrents ont obtenu une certification ISO?"]}},{"n":6,"answer":"D","section":{"en":"Compliance as a management system","fr":"La conformité en tant que système de gestion"},"q":{"en":"Why does ISO 37301 require the CMS to reflect organizational values, objectives, strategy, and compliance risks?","fr":"Pourquoi l’ISO 37301 exige-t-elle que le SGC reflète les valeurs, les objectifs, la stratégie et les risques de conformité de l’organisation?"},"options":{"en":["To allow the organization to skip compliance risk assessment","To make certification less expensive and faster","To ensure that compliance is managed by the IT department","To avoid controls that are technically sound but misaligned or culturally rejected"],"fr":["Pour permettre à l’organisation de se passer de l’évaluation des risques de conformité","Pour rendre la certification moins coûteuse et plus rapide","Pour que la conformité soit gérée par le service des TI","Pour éviter des contrôles techniquement solides, mais mal alignés ou rejetés par la culture"]}},{"n":7,"answer":"C","section":{"en":"Why compliance fails in practice: culture, leadership, and governance","fr":"Pourquoi la conformité échoue en pratique : culture, leadership et gouvernance"},"q":{"en":"According to the chapter, what does forcing compliance mainly through rules, surveillance, and punishment tend to produce over time?","fr":"Selon le chapitre, qu’est-ce qu’imposer la conformité principalement par des règles, de la surveillance et des sanctions tend à produire avec le temps?"},"options":{"en":["A durable culture of compliance at all levels","Lower audit costs and fewer external findings","Workarounds, resentment, quiet noncompliance, and superficial reporting","Greater independence for the compliance function"],"fr":["Une culture de conformité durable à tous les niveaux","Des coûts d’audit moindres et moins de constatations externes","Des contournements, du ressentiment, une non-conformité silencieuse et des rapports superficiels","Une plus grande indépendance de la fonction conformité"]}},{"n":8,"answer":"B","section":{"en":"Why compliance fails in practice: culture, leadership, and governance","fr":"Pourquoi la conformité échoue en pratique : culture, leadership et gouvernance"},"q":{"en":"Why does ISO 37301 call for the compliance function to be independent and to have direct access to the governing body?","fr":"Pourquoi l’ISO 37301 exige-t-elle que la fonction conformité soit indépendante et ait un accès direct à l’organe de gouvernance?"},"options":{"en":["So that it can approve all business investments directly","So that findings revealing underfunding or risky trade-offs are not suppressed","So that it can replace internal audit in the three lines","So that it reports only to the chief information officer"],"fr":["Pour qu’elle puisse approuver directement tous les investissements d’affaires","Pour que les constatations révélant un sous-financement ou des compromis risqués ne soient pas étouffées","Pour qu’elle puisse remplacer l’audit interne dans les trois lignes","Pour qu’elle ne relève que du dirigeant principal de l’information"]}},{"n":9,"answer":"D","section":{"en":"Compliance obligations in cybersecurity: mapping the landscape","fr":"Résumé du chapitre"},"q":{"en":"Why do many organizations maintain a single mapped set of controls across their obligations?","fr":"Pourquoi bien des organisations tiennent-elles un ensemble unique de contrôles harmonisé pour l’ensemble de leurs obligations?"},"options":{"en":["Because regulators prohibit separate control sets","Because it eliminates the need for evidence","Because each obligation then needs its own audit","Because one well-evidenced control can be tested once and reported against several requirements"],"fr":["Parce que les organismes de réglementation interdisent les ensembles de contrôles distincts","Parce que cela élimine le besoin d’éléments probants","Parce que chaque obligation exige alors son propre audit","Parce qu’un contrôle bien documenté peut être testé une seule fois et faire l’objet de rapports au regard de plusieurs exigences"]}},{"n":10,"answer":"A","section":{"en":"Compliance obligations in cybersecurity: mapping the landscape","fr":"Les obligations de conformité en cybersécurité : cartographier le paysage"},"q":{"en":"Since November 2018, what has PIPEDA required organizations to report?","fr":"Depuis novembre 2018, que la LPRPDE exige-t-elle des organisations qu’elles déclarent?"},"options":{"en":["Breaches of security safeguards that create a real risk of significant harm","Every cybersecurity incident, whatever the harm, as soon as it is detected","Confidentiality incidents to the Commission d'accès à l'information","Annual descriptions of board cybersecurity oversight to investors"],"fr":["Les atteintes aux mesures de sécurité qui créent un risque réel de préjudice grave","Chaque incident de cybersécurité, quel que soit le préjudice, dès sa détection","Les incidents de confidentialité à la Commission d’accès à l’information","La description annuelle, à l’intention des investisseurs, de la surveillance de la cybersécurité exercée par le conseil"]}},{"n":11,"answer":"C","section":{"en":"Compliance obligations in cybersecurity: mapping the landscape","fr":"Les obligations de conformité en cybersécurité : cartographier le paysage"},"q":{"en":"What does OSFI Guideline B-10 address for federally regulated financial institutions?","fr":"Sur quoi porte la ligne directrice B-10 du BSIF pour les institutions financières fédérales?"},"options":{"en":["Technology and cyber risk management","Payment card data security for merchants","Third-party risk management","Protection of personal information in Québec"],"fr":["La gestion du risque lié aux technologies et du cyberrisque","La sécurité des données de cartes de paiement pour les commerçants","La gestion du risque lié aux tiers","La protection des renseignements personnels au Québec"]}},{"n":12,"answer":"B","section":{"en":"Compliance obligations in cybersecurity: mapping the landscape","fr":"Les obligations de conformité en cybersécurité : cartographier le paysage"},"q":{"en":"What is the essential methodological point the chapter makes about the Canadian compliance landscape?","fr":"Quel est le point méthodologique essentiel que soulève le chapitre au sujet du paysage canadien de la conformité?"},"options":{"en":["Students should memorize every applicable law and its current version","The goal is a repeatable process that identifies what applies and keeps it current","Only federal statutes are relevant to cybersecurity compliance","International regimes can be ignored by Canadian organizations"],"fr":["Les étudiants devraient mémoriser chaque loi applicable et sa version en vigueur","Le but est un processus reproductible qui détermine ce qui s’applique et le tient à jour","Seules les lois fédérales sont pertinentes pour la conformité en cybersécurité","Les organisations canadiennes peuvent ignorer les régimes internationaux"]}},{"n":13,"answer":"B","section":{"en":"Chapter summary","fr":"Résumé du chapitre"},"q":{"en":"Which situation best illustrates compliance theatre?","fr":"Quelle situation illustre le mieux la conformité de façade?"},"options":{"en":["A control is tested once and reported against several obligations","Polished documents and passed audits while the underlying risk is unchanged","An exception is approved with compensating controls and an expiry date","An employee reports a near miss through the speak-up channel"],"fr":["Un contrôle est testé une seule fois et fait l’objet de rapports au regard de plusieurs obligations","Des documents soignés et des audits réussis alors que le risque sous-jacent est inchangé","Une exception est approuvée avec des contrôles compensatoires et une date d’échéance","Un employé signale un quasi-incident au moyen du dispositif de signalement"]}},{"n":14,"answer":"D","section":{"en":"Compliance risk assessment: where obligations meet operations","fr":"L’évaluation des risques de conformité : là où les obligations rencontrent les opérations"},"q":{"en":"When must compliance risks be reassessed, according to ISO 37301 as described in the chapter?","fr":"Selon l’ISO 37301, telle que décrite dans le chapitre, quand faut-il réévaluer les risques de conformité?"},"options":{"en":["Only when a regulator announces an examination","Only after a confirmed security incident has occurred","Once at implementation, then only at recertification","Periodically, including outsourced processes, and when material changes occur"],"fr":["Seulement lorsqu’un organisme de réglementation annonce un examen","Seulement après un incident de sécurité confirmé","Une fois lors de la mise en œuvre, puis seulement lors du renouvellement de la certification","Périodiquement, y compris pour les processus impartis, et lors de changements importants"]}},{"n":15,"answer":"A","section":{"en":"Compliance assessment approaches in cybersecurity","fr":"Les approches d’évaluation de la conformité en cybersécurité"},"q":{"en":"What does the chapter say about penetration testing and vulnerability assessments as compliance assessment approaches?","fr":"Que dit le chapitre des tests d’intrusion et des évaluations des vulnérabilités en tant qu’approches d’évaluation de la conformité?"},"options":{"en":["They can expose gaps against plausible attack paths but do not, by themselves, prove legal compliance","They replace the need for internal audit and management review","They prove legal compliance whenever no critical findings are reported","They are relevant only to organizations seeking ISO 37301 certification"],"fr":["Ils peuvent révéler des lacunes au regard de chemins d’attaque plausibles, mais ne prouvent pas à eux seuls la conformité légale","Ils éliminent le besoin d’un audit interne et d’une revue de direction","Ils prouvent la conformité légale chaque fois qu’aucune constatation critique n’est signalée","Ils ne sont pertinents que pour les organisations qui cherchent à obtenir la certification ISO 37301"]}},{"n":16,"answer":"C","section":{"en":"Implementing a PDCA-aligned compliance management system for cybersecurity","fr":"Mettre en œuvre un système de gestion de la conformité en cybersécurité aligné sur le cycle PDCA"},"q":{"en":"In the PDCA-aligned approach, what happens in the Check phase?","fr":"Dans l’approche alignée sur le cycle PDCA, que se passe-t-il à la phase Vérifier?"},"options":{"en":["Scope, context, and obligations are defined and assessed","Controls and procedures are implemented with training and resources","Performance is monitored, audits conducted, and results evaluated with objective indicators","Nonconformities are corrected and documentation is updated"],"fr":["La portée, le contexte et les obligations sont définis et évalués","Les contrôles et les procédures sont mis en œuvre avec la formation et les ressources nécessaires","La performance est surveillée, des audits sont menés et les résultats sont évalués à l’aide d’indicateurs objectifs","Les non-conformités sont corrigées et la documentation est mise à jour"]}},{"n":17,"answer":"A","section":{"en":"Implementing a PDCA-aligned compliance management system for cybersecurity","fr":"Mettre en œuvre un système de gestion de la conformité en cybersécurité aligné sur le cycle PDCA"},"q":{"en":"Why did Pontvert's compliance director recommend deferring formal ISO 37301 certification?","fr":"Pourquoi la directrice de la conformité de Pontvert a-t-elle recommandé de reporter la certification ISO 37301 officielle?"},"options":{"en":["No customer or regulator required it, and the money was better spent making the system work","ISO 37301 cannot be certified for software-as-a-service providers","The company's ISO/IEC 27001 certificate already covered compliance management","Certification would have required abandoning the SOC 2 report"],"fr":["Aucun client ni organisme de réglementation ne l’exigeait, et l’argent serait mieux employé à faire fonctionner le système","L’ISO 37301 ne peut pas être certifiée pour les fournisseurs de logiciel-service","Le certificat ISO/IEC 27001 de l’entreprise couvrait déjà la gestion de la conformité","La certification aurait exigé l’abandon du rapport SOC 2"]}},{"n":18,"answer":"D","section":{"en":"Implementing a PDCA-aligned compliance management system for cybersecurity","fr":"Mettre en œuvre un système de gestion de la conformité en cybersécurité aligné sur le cycle PDCA"},"q":{"en":"In the Pontvert scenario, what does a SOC 2 Type II report provide?","fr":"Dans la mise en situation de Pontvert, que fournit un rapport SOC 2 de type II?"},"options":{"en":["A supervisor's examination of a regulated financial institution","A certification body's judgment that an ISMS conforms to a standard","A self-assessment of compliance with internal policies","An auditor's opinion on whether controls were suitably designed and operated effectively over a period"],"fr":["L’examen d’une institution financière réglementée par une autorité de surveillance","Le jugement d’un organisme de certification selon lequel un SGSI est conforme à une norme","Une autoévaluation de la conformité aux politiques internes","L’opinion d’un auditeur sur la question de savoir si les contrôles étaient conçus de façon appropriée et ont fonctionné efficacement pendant une période donnée"]}},{"n":19,"answer":"C","section":{"en":"Implementing a PDCA-aligned compliance management system for cybersecurity","fr":"Mettre en œuvre un système de gestion de la conformité en cybersécurité aligné sur le cycle PDCA"},"q":{"en":"Pontvert's legacy reporting server could not support multi-factor authentication. How did the organization handle this conflict with its policy and a contract?","fr":"Le serveur de rapports patrimonial de Pontvert ne pouvait pas prendre en charge l’authentification multifacteur. Comment l’organisation a-t-elle géré ce conflit avec sa politique et un contrat?"},"options":{"en":["It marked the server compliant because few users accessed it","It shut down the server immediately, ending service to two clients","The risk owner approved a formal exception with compensating controls, a 90-day expiry, and a migration plan","It renewed the exception automatically each quarter"],"fr":["Elle a déclaré le serveur conforme parce que peu d’utilisateurs y accédaient","Elle a arrêté le serveur immédiatement, interrompant le service à deux clients","La vice-présidence des produits, responsable du risque, a approuvé une exception officielle avec des contrôles compensatoires, une échéance de 90 jours et un plan de migration","Elle a renouvelé l’exception automatiquement chaque trimestre"]}},{"n":20,"answer":"B","section":{"en":"Implementing a PDCA-aligned compliance management system for cybersecurity","fr":"Mettre en œuvre un système de gestion de la conformité en cybersécurité aligné sur le cycle PDCA"},"q":{"en":"What was the main lesson of the customer-file exports reported through Pontvert's speak-up channel?","fr":"Quelle a été la principale leçon des exportations de fichiers de clients signalées au moyen du dispositif de signalement de Pontvert?"},"options":{"en":["Speak-up reports mostly raise low-value complaints that audits already cover","Audits passed because support tooling was out of scope; the fix brought it in and tracked behaviour","A newly signed policy is the most effective way to close such a finding","SOC 2 reports automatically extend to every internal support tool in use"],"fr":["Les signalements soulèvent surtout des plaintes de faible valeur que les audits couvrent déjà","Les audits étaient réussis parce que les outils de soutien étaient hors de la portée; la correction les y a intégrés et a suivi les comportements","Une nouvelle politique signée est le moyen le plus efficace de clore une telle constatation","Les rapports SOC 2 s’étendent automatiquement à tous les outils de soutien internes utilisés"]}}]},{"n":4,"title":{"en":"Chapter 4: Cybersecurity Risk Management","fr":"Chapitre 4 : Gestion des risques de cybersécurité"},"questions":[{"n":1,"answer":"B","section":{"en":"The fundamentals of risk","fr":"Les fondements du risque"},"q":{"en":"In the risk triangle used in Chapter 4, risk emerges at the intersection of which three components?","fr":"Dans le triangle du risque utilisé au chapitre 4, le risque apparaît à l’intersection de quelles trois composantes?"},"options":{"en":["Assets, controls, and residual risk","Threats, vulnerabilities, and exposure","Likelihood, detectability, and velocity","Governance, risk management, and compliance"],"fr":["Les actifs, les contrôles et le risque résiduel","Les menaces, les vulnérabilités et l’exposition","La vraisemblance, la détectabilité et la vélocité","La gouvernance, la gestion des risques et la conformité"]}},{"n":2,"answer":"D","section":{"en":"What risk management is (and is not)","fr":"Ce qu’est la gestion des risques (et ce qu’elle n’est pas)"},"q":{"en":"Unmanaged endpoints will inevitably be infected. According to the chapter, how should endpoint protection be treated in that situation?","fr":"Les terminaux non gérés seront inévitablement infectés. Selon le chapitre, comment faut-il traiter la protection des terminaux dans cette situation?"},"options":{"en":["As a manageable risk to be scored and prioritized each year","As deep uncertainty best handled through continuity planning alone","As a residual risk that management may formally accept","As a baseline operational requirement rather than a matter for debate"],"fr":["Comme un risque gérable à coter et à prioriser chaque année","Comme une incertitude profonde qu’on gère mieux par la seule planification de la continuité","Comme un risque résiduel que la direction peut accepter formellement","Comme une exigence opérationnelle de base plutôt qu’un sujet de débat"]}},{"n":3,"answer":"A","section":{"en":"Scenario-based risk assessment: the bridge from technical to business","fr":"Évaluation des risques fondée sur des scénarios : le pont entre le technique et les affaires"},"q":{"en":"A security team presents the board with a register of 200 undifferentiated risks. Which element of the IPM cycle is missing in substance?","fr":"Une équipe de sécurité présente au conseil d’administration un registre de 200 risques non différenciés. Quel élément du cycle IPM manque sur le fond?"},"options":{"en":["Prioritization, because there is no defensible ordering or record of decisions","Identification, because more threats must be listed before ranking","Mobilization, because funds have not yet been allocated to controls","Identification, because a register of 200 items covers too few assets"],"fr":["La Priorisation, parce qu’il n’y a ni ordre défendable ni trace des décisions","L’Identification, parce qu’il faut énumérer davantage de menaces avant de classer","La Mobilisation, parce que les fonds n’ont pas encore été affectés aux contrôles","L’Identification, parce qu’un registre de 200 éléments couvre trop peu d’actifs"]}},{"n":4,"answer":"C","section":{"en":"Risk management and ISO-aligned management systems","fr":"La gestion des risques et les systèmes de gestion alignés sur les normes ISO"},"q":{"en":"Why does the chapter insist that risk decisions be traceable under an ISO-aligned management system approach?","fr":"Pourquoi le chapitre exige-t-il que les décisions relatives aux risques soient traçables dans une approche de système de gestion alignée sur l’ISO?"},"options":{"en":["Because auditors require every risk to be quantified in dollars","Because annual assessments become sufficient once decisions are documented","So the organization can show risk is managed within tolerance and learn from incidents","Because traceability replaces management reviews and corrective actions"],"fr":["Parce que les auditeurs exigent que chaque risque soit quantifié en dollars","Parce que les évaluations annuelles deviennent suffisantes une fois les décisions documentées","Pour que l’organisation puisse montrer que le risque est géré dans les limites de la tolérance et tirer des leçons des incidents","Parce que la traçabilité remplace les revues de direction et les actions correctives"]}},{"n":5,"answer":"A","section":{"en":"Scenario-based risk assessment: the bridge from technical to business","fr":"Résumé du chapitre"},"q":{"en":"A manager proposes to accept, on her own authority and with no end date, a residual risk that is above tolerance. Which practice from the chapter does this most directly violate?","fr":"Une gestionnaire propose d’accepter, de sa propre autorité et sans date de fin, un risque résiduel au-dessus de la tolérance. Quelle pratique du chapitre cette proposition enfreint-elle le plus directement?"},"options":{"en":["Acceptance authority proportionate to the risk level, with an expiry date","Transfer paired with due diligence on third-party controls","Escalation of avoidance decisions because they affect strategy","Mitigation packages that act on both probability and impact"],"fr":["Une autorité d’acceptation proportionnée au niveau de risque, avec une date d’échéance","Un transfert accompagné d’une vérification diligente des contrôles des tiers","La remontée des décisions d’évitement parce qu’elles touchent la stratégie","Des ensembles de mesures d’atténuation qui agissent à la fois sur la probabilité et sur l’impact"]}},{"n":6,"answer":"C","section":{"en":"Scenario-based risk assessment: the bridge from technical to business","fr":"Évaluation des risques fondée sur des scénarios : le pont entre le technique et les affaires"},"q":{"en":"At Groupe Valmont Polymères, the CEO rejected a customer portal hosted on the plant network and had it redesigned as a separate cloud service. Which strategy does this illustrate?","fr":"Chez Groupe Valmont Polymères, le chef de la direction a rejeté un portail client hébergé sur le réseau de l’usine et l’a fait reconcevoir comme un service infonuagique distinct. Quelle stratégie cela illustre-t-il?"},"options":{"en":["Risk acceptance with monitoring and an expiry date","Risk transfer through contractual clauses with customers","Risk avoidance of a design whose exposure could not be reasonably mitigated","Risk mitigation through segmentation of the existing plant network"],"fr":["L’acceptation du risque, avec surveillance et date d’échéance","Le transfert du risque au moyen de clauses contractuelles avec les clients","L’évitement du risque lié à une conception dont l’exposition ne pouvait être raisonnablement atténuée","L’atténuation du risque par la segmentation du réseau existant de l’usine"]}},{"n":7,"answer":"D","section":{"en":"Decisions about risk: the main treatment strategies","fr":"Les décisions relatives au risque : les principales stratégies de traitement"},"q":{"en":"According to the chapter, how is risk transfer recorded in the quantitative method of Chapter 6?","fr":"Selon le chapitre, comment le transfert du risque est-il consigné dans la méthode quantitative du chapitre 6?"},"options":{"en":["As a mitigation measure that lowers calculated risk by the insured share","As an impact reduction equal to the share of loss the policy covers","As a reason to remove the scenario from the risk register","As a treatment decision recording the share covered and who approved it"],"fr":["Comme une mesure d’atténuation qui réduit le risque calculé de la part assurée","Comme une réduction de l’impact égale à la part des pertes couverte par la police","Comme une raison de retirer le scénario du registre des risques","Comme une décision de traitement qui consigne la part couverte et la personne qui l’a approuvée"]}},{"n":8,"answer":"B","section":{"en":"Decisions about risk: the main treatment strategies","fr":"Les décisions relatives au risque : les principales stratégies de traitement"},"q":{"en":"In Chapter 6's method, a treatment package is described by the share of probability and the share of impact it removes, and the two are multiplied. What follows from this convention?","fr":"Dans la méthode du chapitre 6, un ensemble de mesures est décrit par la part de probabilité et la part d’impact qu’il élimine, et les deux sont multipliées. Qu’est-ce qui découle de cette convention?"},"options":{"en":["A package acting only on impact still halves the calculated risk","A package reduces calculated risk only if it acts on both levers","Adding more controls always pushes the shares beyond one","Prevention alone is sufficient because probability dominates the product"],"fr":["Un ensemble de mesures qui n’agit que sur l’impact réduit tout de même de moitié le risque calculé","Un ensemble de mesures ne réduit le risque calculé que s’il agit sur les deux leviers","L’ajout de contrôles pousse toujours les parts au-delà de un","La prévention seule suffit, car la probabilité domine le produit"]}},{"n":9,"answer":"C","section":{"en":"Risk appetite and risk tolerance: turning governance into decision criteria","fr":"L’appétence pour le risque et la tolérance au risque : transformer la gouvernance en critères de décision"},"q":{"en":"Using the chapter's best-practice benchmark with linear interpolation, what cybersecurity share of the total IT budget, including salaries, corresponds to a risk appetite of 0.40?","fr":"Selon le repère de pratique exemplaire du chapitre, avec interpolation linéaire, quelle part du budget total des TI, salaires compris, la cybersécurité devrait-elle représenter pour une appétence pour le risque de 0,40?"},"options":{"en":["About 4.0%","About 7.8%","About 9.9%","About 12.0%"],"fr":["Environ 4,0 %","Environ 7,8 %","Environ 9,9 %","Environ 12,0 %"]}},{"n":10,"answer":"A","section":{"en":"Chapter summary","fr":"Résumé du chapitre"},"q":{"en":"A scenario's residual risk divided by its tolerated risk gives a ratio of 1.05. How does the chapter read this result?","fr":"Le risque résiduel d’un scénario divisé par son risque toléré donne un ratio de 1,05. Comment le chapitre interprète-t-il ce résultat?"},"options":{"en":["Approximately at tolerance, within the 0.90 to 1.10 band","Below tolerance, because the ratio is close to 1","Above tolerance, since any ratio over 1.00 is unacceptable","Undefined until the ratio is recalculated to more decimals"],"fr":["Approximativement à la tolérance, dans la plage de 0,90 à 1,10","Sous la tolérance, parce que le ratio est proche de 1","Au-dessus de la tolérance, puisque tout ratio supérieur à 1,00 est inacceptable","Indéterminé tant que le ratio n’est pas recalculé avec plus de décimales"]}},{"n":11,"answer":"D","section":{"en":"Biases and human factors that distort decisions about risk","fr":"Les biais et les facteurs humains qui faussent les décisions relatives au risque"},"q":{"en":"After a widely reported ransomware attack on a competitor, a committee shifts its whole budget to ransomware while ignoring a growing patch backlog. Which bias is most evident?","fr":"Après une attaque par rançongiciel très médiatisée contre un concurrent, un comité consacre tout son budget au rançongiciel en ignorant un arriéré croissant de correctifs. Quel biais est le plus manifeste?"},"options":{"en":["Anchoring bias, where early assumptions dominate later analysis","Status quo bias, where inertia persists despite a changed environment","Optimism bias, where harm seems less likely to affect us than peers","Availability bias, where recent dramatic incidents overshadow likelier threats"],"fr":["Le biais d’ancrage, où les premières hypothèses dominent l’analyse ultérieure","Le biais du statu quo, où l’inertie persiste malgré un environnement changé","Le biais d’optimisme, où le préjudice semble moins susceptible de nous toucher que nos pairs","Le biais de disponibilité, où les incidents récents et spectaculaires éclipsent des menaces plus probables"]}},{"n":12,"answer":"B","section":{"en":"Biases and human factors that distort decisions about risk","fr":"Les biais et les facteurs humains qui faussent les décisions relatives au risque"},"q":{"en":"Which mechanism does the chapter recommend to counter groupthink in major risk decisions?","fr":"Quel mécanisme le chapitre recommande-t-il pour contrer la pensée de groupe dans les décisions importantes relatives aux risques?"},"options":{"en":["Requiring unanimous committee approval before any risk is accepted","Requiring a documented dissenting view for major risk decisions","Limiting risk workshops to senior executives to speed consensus","Replacing qualitative discussion with a single numeric risk score"],"fr":["Exiger l’approbation unanime du comité avant l’acceptation de tout risque","Exiger une opinion dissidente documentée pour les décisions importantes relatives aux risques","Limiter les ateliers sur les risques à la haute direction pour accélérer le consensus","Remplacer la discussion qualitative par un score de risque numérique unique"]}},{"n":13,"answer":"B","section":{"en":"Metrics and key risk indicators: making risk observable","fr":"Résumé du chapitre"},"q":{"en":"Which statement best distinguishes a key risk indicator (KRI) from a key performance indicator (KPI)?","fr":"Quel énoncé distingue le mieux un indicateur clé de risque (ICR) d’un indicateur clé de performance?"},"options":{"en":["KRIs measure achievement of objectives; KPIs signal rising exposure","KRIs give early warning of rising exposure; KPIs measure achievement of objectives","KRIs are calculated risk indices; KPIs are measured monitoring values","KRIs are purely financial measures; KPIs cover operational areas"],"fr":["Les ICR mesurent l’atteinte des objectifs; les indicateurs clés de performance signalent une exposition croissante","Les ICR donnent une alerte précoce d’une exposition croissante; les indicateurs clés de performance mesurent l’atteinte des objectifs","Les ICR sont des indices de risque calculés; les indicateurs clés de performance sont des valeurs de surveillance mesurées","Les ICR sont des mesures purement financières; les indicateurs clés de performance couvrent les domaines opérationnels"]}},{"n":14,"answer":"A","section":{"en":"Threat identification: internal and external agents","fr":"L’identification des menaces : agents internes et externes"},"q":{"en":"In the Cyber Centre framing presented in the chapter, which motivation is associated with hacktivists?","fr":"Dans le cadre du Centre pour la cybersécurité présenté au chapitre, quelle motivation est associée aux hacktivistes?"},"options":{"en":["Ideology","Profit","Geopolitical objectives","Satisfaction"],"fr":["L’idéologie","Le profit","Des objectifs géopolitiques","La satisfaction"]}},{"n":15,"answer":"C","section":{"en":"Threat identification: internal and external agents","fr":"L’identification des menaces : agents internes et externes"},"q":{"en":"How does the chapter, citing the Cyber Centre, characterize advanced persistent threats (APTs)?","fr":"Comment le chapitre, citant le Centre pour la cybersécurité, caractérise-t-il les menaces persistantes avancées (APT)?"},"options":{"en":["As a threat category defined by ransomware used for profit","As low-skill opportunists who buy tools in online markets","As a capability marker for top-tier actors running protracted campaigns","As insiders who abuse legitimate access to bypass the perimeter"],"fr":["Comme une catégorie de menace définie par l’utilisation d’un rançongiciel à des fins lucratives","Comme des opportunistes peu qualifiés qui achètent des outils dans des marchés en ligne","Comme un marqueur de capacité propre aux acteurs de premier rang qui mènent des campagnes prolongées","Comme des initiés qui abusent d’un accès légitime pour contourner le périmètre"]}},{"n":16,"answer":"D","section":{"en":"Vulnerability identification","fr":"L’identification des vulnérabilités"},"q":{"en":"Which statement correctly describes the roles of CVE, CWE, and CVSS?","fr":"Quel énoncé décrit correctement le rôle des CVE, des CWE et du CVSS?"},"options":{"en":["CVE classifies weakness types; CWE names disclosed vulnerabilities; CVSS ranks business risk","CVE scores severity; CWE tracks exploited vulnerabilities; CVSS names specific issues","CVE ranks remediation; CWE predicts exploitation; CVSS lists application risk categories","CVE names specific issues; CWE describes the weakness class; CVSS supports first-pass severity triage"],"fr":["Les CVE classent les types de faiblesses; les CWE désignent les vulnérabilités divulguées; le CVSS classe le risque d’affaires","Les CVE cotent la gravité; les CWE suivent les vulnérabilités exploitées; le CVSS désigne des problèmes précis","Les CVE classent les corrections; les CWE prédisent l’exploitation; le CVSS énumère des catégories de risques applicatifs","Les CVE désignent des problèmes précis; les CWE décrivent la classe de faiblesse; le CVSS soutient le triage initial de la gravité"]}},{"n":17,"answer":"A","section":{"en":"Vulnerability identification","fr":"L’identification des vulnérabilités"},"q":{"en":"How is the CVSS v4.0 base score of a scenario's weakness used in the risk assessment method of Chapters 5 and 6?","fr":"Comment le score de base CVSS v4.0 de la faiblesse d’un scénario est-il utilisé dans la méthode d’évaluation des risques des chapitres 5 et 6?"},"options":{"en":["As a mandatory multiplier in the risk index, never used alone to rank scenarios","As the primary criterion for selecting which scenarios to assess","As a replacement for probability estimates when evidence is weak","As an optional input used only when the weakness is technical"],"fr":["Comme un multiplicateur obligatoire de l’indice de risque, jamais utilisé seul pour classer les scénarios","Comme le principal critère de sélection des scénarios à évaluer","Comme un substitut aux estimations de probabilité lorsque les éléments probants sont faibles","Comme une donnée facultative, utilisée seulement lorsque la faiblesse est technique"]}},{"n":18,"answer":"C","section":{"en":"Cybersecurity exploits: how threats operationalize vulnerabilities","fr":"Les codes d’exploitation en cybersécurité : comment les menaces tirent parti des vulnérabilités"},"q":{"en":"Deploying email filtering and sender authentication (SPF, DKIM, DMARC) primarily defends which phase of the Cyber Kill Chain?","fr":"Le déploiement du filtrage des courriels et de l’authentification de l’expéditeur (SPF, DKIM, DMARC) protège principalement quelle phase de la chaîne de frappe?"},"options":{"en":["Reconnaissance","Weaponization","Delivery","Command and control"],"fr":["La reconnaissance","L’armement","La livraison","La commande et le contrôle"]}},{"n":19,"answer":"D","section":{"en":"Cybersecurity exploits: how threats operationalize vulnerabilities","fr":"Les codes d’exploitation en cybersécurité : comment les menaces tirent parti des vulnérabilités"},"q":{"en":"Which four core features does the Diamond Model of Intrusion Analysis use to frame malicious activity?","fr":"Quels sont les quatre éléments fondamentaux qu’utilise le modèle du diamant d’analyse des intrusions pour décrire une activité malveillante?"},"options":{"en":["Reconnaissance, delivery, exploitation, and actions on objectives","Tactics, techniques, procedures, and indicators","Threat, vulnerability, exposure, and impact","Adversary, victim, capability, and infrastructure"],"fr":["La reconnaissance, la livraison, l’exploitation et les actions sur les objectifs","Les tactiques, les techniques, les procédures et les indicateurs","La menace, la vulnérabilité, l’exposition et l’impact","L’adversaire, la victime, la capacité et l’infrastructure"]}},{"n":20,"answer":"B","section":{"en":"Cybersecurity exploits: how threats operationalize vulnerabilities","fr":"Les codes d’exploitation en cybersécurité : comment les menaces tirent parti des vulnérabilités"},"q":{"en":"A critical vulnerability sits on an internal server that cannot be reached under realistic conditions, while a moderate one sits on an Internet-facing service. What does the chapter's reasoning about exposure suggest?","fr":"Une vulnérabilité critique se trouve sur un serveur interne qui ne peut être atteint dans des conditions réalistes, tandis qu’une vulnérabilité moyenne se trouve sur un service exposé à Internet. Que suggère le raisonnement du chapitre sur l’exposition?"},"options":{"en":["The critical one is always higher risk because severity drives risk","The reachable one may be higher risk, since exposure combines weakness and reachability","Both carry equal risk because each has a CVE identifier and score","Neither matters until a working exploit is published for each"],"fr":["La vulnérabilité critique présente toujours un risque plus élevé, car la gravité détermine le risque","La vulnérabilité accessible peut présenter un risque plus élevé, car l’exposition combine faiblesse et accessibilité","Les deux présentent un risque égal, car chacune a un identifiant CVE et un score","Aucune n’importe tant qu’un code d’exploitation fonctionnel n’est pas publié pour chacune"]}}]},{"n":5,"title":{"en":"Chapter 5: Creating Cybersecurity Risk Scenarios","fr":"Chapitre 5 : Élaboration de scénarios de risque de cybersécurité"},"questions":[{"n":1,"answer":"C","section":{"en":"The scenario standard: causal chains, not threat names","fr":"La norme de scénario : des chaînes causales, pas des noms de menaces"},"q":{"en":"Which of the following statements meets CRG's standard for a scenario rather than a threat label?","fr":"Lequel des énoncés suivants respecte la norme de CRG pour un scénario plutôt que pour une étiquette de menace?"},"options":{"en":["Ransomware attacks against clinical systems, which could cause serious disruption to operations at all sites","Phishing campaigns by financially motivated actors targeting staff across the organization during the next year","A ransomware affiliate uses stolen VPN credentials and absent MFA to encrypt scheduling servers, halting appointments for days","A data breach involving patient information, with regulatory and reputational consequences for the organization"],"fr":["Des attaques par rançongiciel contre les systèmes cliniques, qui pourraient perturber gravement les activités de tous les sites","Des campagnes d’hameçonnage menées par des acteurs à motivation financière visant le personnel de toute l’organisation au cours de la prochaine année","Un affilié d’un groupe de rançongiciel utilise des identifiants de RPV volés et l’absence d’AMF pour chiffrer les serveurs de prise de rendez-vous, ce qui interrompt les rendez-vous pendant des jours","Une violation de données touchant des renseignements sur les patients, avec des conséquences réglementaires et réputationnelles pour l’organisation"]}},{"n":2,"answer":"A","section":{"en":"The scenario standard: causal chains, not threat names","fr":"La norme de scénario : des chaînes causales, pas des noms de menaces"},"q":{"en":"Which sequence correctly states the five links of CRG's causal chain?","fr":"Quelle séquence énonce correctement les cinq maillons de la chaîne causale de CRG?"},"options":{"en":["Threat source or event, vulnerability or predisposing condition, affected asset or process, cybersecurity event, business consequence","Asset, threat actor, existing control, likelihood of occurrence, and expected financial impact","Vulnerability, threat source, cybersecurity event, compensating control, and residual risk after treatment","Business objective, crown jewel, threat name, CVSS score, and recommended treatment package"],"fr":["Source ou événement de menace, vulnérabilité ou condition prédisposante, actif ou processus touché, événement de cybersécurité, conséquence organisationnelle","Actif, acteur de menace, contrôle existant, vraisemblance d’occurrence et impact financier attendu","Vulnérabilité, source de menace, événement de cybersécurité, contrôle compensatoire et risque résiduel après traitement","Objectif d’affaires, joyau de la couronne, nom de menace, score CVSS et ensemble de mesures recommandé"]}},{"n":3,"answer":"D","section":{"en":"Standards compatibility","fr":"Compatibilité avec les normes"},"q":{"en":"Which ISO/IEC 27005:2022 approach does CRG's bottom-up generation strategy implement?","fr":"Quelle approche de l’ISO/IEC 27005:2022 la stratégie de génération ascendante de CRG met-elle en œuvre?"},"options":{"en":["The event-based approach, reasoning from risk sources at a strategic level","A quantitative approach, reasoning from historical loss data and frequencies","A threat-based approach, reasoning from adversary techniques catalogued in ATT&CK","The asset-based approach, reasoning from assets, their threats, and their vulnerabilities"],"fr":["L’approche fondée sur les événements, qui raisonne à partir des sources de risque à un niveau stratégique","Une approche quantitative, qui raisonne à partir de données historiques de pertes et de fréquences","Une approche fondée sur la menace, qui raisonne à partir des techniques d’adversaires répertoriées dans ATT&CK","L’approche fondée sur les actifs, qui raisonne à partir des actifs, de leurs menaces et de leurs vulnérabilités"]}},{"n":4,"answer":"B","section":{"en":"Standards compatibility","fr":"Compatibilité avec les normes"},"q":{"en":"Why does CRG use the phrase 'vulnerability or predisposing condition', borrowed from NIST SP 800-30 Rev. 1?","fr":"Pourquoi CRG emploie-t-il l’expression « vulnérabilité ou condition prédisposante », empruntée à la publication NIST SP 800-30 Rev. 1?"},"options":{"en":["Because only flaws with CVE identifiers can be scored and must be separated","Because many material weaknesses, such as a flat network, are not software flaws","Because predisposing conditions remove the need for an evidence register","Because NIST requires every weakness to be recorded as a condition"],"fr":["Parce que seules les failles ayant un identifiant CVE peuvent être cotées et doivent être distinguées","Parce que bien des faiblesses importantes, comme un réseau à plat, ne sont pas des failles logicielles","Parce que les conditions prédisposantes rendent le registre des éléments probants inutile","Parce que le NIST exige que chaque faiblesse soit consignée comme une condition"]}},{"n":5,"answer":"B","section":{"en":"The CyberRiskGuardian approach to scenario creation","fr":"Le contexte d’abord : éléments probants, joyaux de la couronne et portée"},"q":{"en":"What is CRG's default assessment horizon, and why must the same horizon apply to every scenario?","fr":"Quel est l’horizon d’évaluation par défaut de CRG, et pourquoi le même horizon doit-il s’appliquer à chaque scénario?"},"options":{"en":["Five years, because cyber risks evolve slowly and need long-range planning","12 months, because probabilities estimated over different horizons cannot be compared","Three years, to match the certification cycle of an ISO/IEC 27001 management system","12 months, because cyber insurance policies are renewed on an annual basis"],"fr":["Cinq ans, parce que les cyberrisques évoluent lentement et exigent une planification à long terme","12 mois, parce que des probabilités estimées sur des horizons différents ne peuvent être comparées","Trois ans, pour correspondre au cycle de certification d’un système de gestion ISO/IEC 27001","12 mois, parce que les polices de cyberassurance sont renouvelées chaque année"]}},{"n":6,"answer":"D","section":{"en":"Context first: evidence, crown jewels, and scope","fr":"Le contexte d’abord : éléments probants, joyaux de la couronne et portée"},"q":{"en":"Which statement about crown jewels is consistent with the chapter?","fr":"Quel énoncé sur les joyaux de la couronne est conforme au chapitre?"},"options":{"en":["Crown jewels are always the systems that store the most sensitive data","Crown jewels are identified after the scenario portfolio has been selected","Identity systems are excluded because they store little business information","Identity and remote access are typically crown jewels because other crown jewels depend on them"],"fr":["Les joyaux de la couronne sont toujours les systèmes qui stockent les données les plus sensibles","Les joyaux de la couronne sont déterminés après la sélection du portefeuille de scénarios","Les systèmes d’identité sont exclus parce qu’ils stockent peu d’information d’affaires","L’identité et l’accès à distance sont généralement des joyaux de la couronne parce que les autres joyaux en dépendent"]}},{"n":7,"answer":"A","section":{"en":"Context first: evidence, crown jewels, and scope","fr":"Le contexte d’abord : éléments probants, joyaux de la couronne et portée"},"q":{"en":"A healthcare organization has no approved risk appetite and asks the analyst to propose one. Which response follows CRG guidance?","fr":"Un organisme de santé n’a pas d’appétence pour le risque approuvée et demande à l’analyste d’en proposer une. Quelle réponse suit les consignes de CRG?"},"options":{"en":["Propose about 0.30 or less, marked as an analytical estimate and a management decision","Use 0.50 as a neutral default without labels, since none was supplied","Propose 0.70, because healthcare faces sustained high threat activity","Leave appetite blank and define materiality later, after scenarios are selected"],"fr":["Proposer environ 0,30 ou moins, avec les mentions d’estimation analytique et de décision de la direction","Utiliser 0,50 comme valeur neutre par défaut sans mention, puisqu’aucune valeur n’a été fournie","Proposer 0,70, parce que le secteur de la santé fait face à une activité de menace élevée et soutenue","Laisser l’appétence en blanc et définir l’importance relative plus tard, après la sélection des scénarios"]}},{"n":8,"answer":"C","section":{"en":"Generating candidate scenarios","fr":"Générer les scénarios candidats"},"q":{"en":"How many candidate scenarios do CRG's scenario-selection instructions call for when building a final portfolio of ten?","fr":"Combien de scénarios candidats les consignes de sélection des scénarios de CRG exigent-elles pour bâtir un portefeuille final de dix?"},"options":{"en":["Exactly ten, one candidate for each final scenario","About 12 to 15, allowing a few spares","About 25 to 40, and never fewer than 20","At least 100, covering every ATT&CK technique"],"fr":["Exactement dix, un candidat par scénario final","Environ 12 à 15, ce qui laisse quelques réserves","Environ 25 à 40, et jamais moins de 20","Au moins 100, couvrant chaque technique ATT&CK"]}},{"n":9,"answer":"A","section":{"en":"Generating candidate scenarios","fr":"Générer les scénarios candidats"},"q":{"en":"Which generation strategy is most likely to surface supplier, cloud, telecommunications, and shared-infrastructure scenarios that neither the business nor the security team would think of first?","fr":"Quelle stratégie de génération est la plus susceptible de faire ressortir des scénarios liés aux fournisseurs, au nuage, aux télécommunications et aux infrastructures partagées auxquels ni l’entreprise ni l’équipe de sécurité ne penseraient d’emblée?"},"options":{"en":["Dependency-driven generation","Top-down generation","Localized generic generation","Threat-driven generation"],"fr":["La génération axée sur les dépendances","La génération descendante","La génération générique localisée","La génération axée sur la menace"]}},{"n":10,"answer":"C","section":{"en":"Screening, consolidating, and selecting","fr":"Filtrer, regrouper et sélectionner"},"q":{"en":"In CRG's screening, why does the 'control uncertainty' criterion give high scores to scenarios where nobody knows whether existing controls work?","fr":"Dans le filtrage de CRG, pourquoi le critère « incertitude sur les contrôles » attribue-t-il des cotes élevées aux scénarios pour lesquels personne ne sait si les contrôles existants fonctionnent?"},"options":{"en":["Because uncertain controls are presumed to have already failed","Because such scenarios automatically receive mandatory escalation flags","Because analysis can clarify exactly those uncertain scenarios","Because uncertainty serves as a proxy for high threat probability"],"fr":["Parce que les contrôles incertains sont présumés avoir déjà échoué","Parce que ces scénarios reçoivent automatiquement des indicateurs de remontée obligatoires","Parce que l’analyse peut justement clarifier ces scénarios incertains","Parce que l’incertitude sert d’indicateur indirect d’une probabilité de menace élevée"]}},{"n":11,"answer":"D","section":{"en":"Screening, consolidating, and selecting","fr":"Filtrer, regrouper et sélectionner"},"q":{"en":"A candidate scenario could cause simultaneous failure of primary and recovery environments, but its probability appears low. What does CRG require?","fr":"Un scénario candidat pourrait causer la défaillance simultanée des environnements principal et de reprise, mais sa probabilité semble faible. Qu’exige CRG?"},"options":{"en":["Exclude it, because its total screening score falls outside the top ten","Merge it automatically into the highest-scoring ransomware family","Select it only if its representative weakness has a critical CVSS score","Keep it visible; excluding it needs explicit review and a management decision"],"fr":["L’exclure, parce que son total de filtrage ne figure pas parmi les dix premiers","Le fusionner automatiquement avec la famille du rançongiciel la mieux cotée","Le retenir seulement si sa faiblesse représentative a un score CVSS critique","Le garder visible; son exclusion exige une revue explicite et une décision de la direction"]}},{"n":12,"answer":"B","section":{"en":"Illustrative scenario: building MediBec's portfolio","fr":"Mise en situation : la constitution du portefeuille de MediBec"},"q":{"en":"In the MediBec example, candidates C01 (phishing of clinic administrators) and C20 (MFA push-fatigue bypass) both scored 52 out of 60. Why were they consolidated into one family?","fr":"Dans l’exemple de MediBec, les candidats C01 (hameçonnage des administrateurs des cliniques) et C20 (contournement de l’AMF par fatigue des notifications) ont tous deux obtenu 52 sur 60. Pourquoi ont-ils été regroupés en une seule famille?"},"options":{"en":["Because CRG requires consolidating any candidates with identical totals","Because they describe the same exposure, share a treatment, and have one owner","Because C20 carried fewer escalation flags than C01 in the workbook","Because consolidation always keeps the candidate with the highest CVSS"],"fr":["Parce que CRG exige de regrouper tous les candidats dont les totaux sont identiques","Parce qu’ils décrivent la même exposition, partagent un traitement et ont un seul responsable","Parce que C20 portait moins d’indicateurs de remontée que C01 dans le classeur","Parce que le regroupement conserve toujours le candidat dont le CVSS est le plus élevé"]}},{"n":13,"answer":"D","section":{"en":"Using generative AI responsibly to draft scenarios","fr":"Utiliser l’IA générative de façon responsable pour rédiger des scénarios"},"q":{"en":"What is the main purpose of scoring scenario families under equal, impact-led, evidence-led, and decision-led weighting schemes?","fr":"Quel est le but principal de la cotation des familles de scénarios selon des schémas de pondération égale, axée sur l’impact, axée sur les éléments probants et axée sur la décision?"},"options":{"en":["To produce a final ranking that replaces the analyst's judgment","To compute the CVSS multiplier that each family will need","To add the scores of all variants within each family","To flag selections resting on judgment and unselected candidates needing review"],"fr":["Produire un classement final qui remplace le jugement de l’analyste","Calculer le multiplicateur CVSS dont chaque famille aura besoin","Additionner les cotes de toutes les variantes de chaque famille","Signaler les sélections fondées sur le jugement et les candidats non retenus qui exigent une revue"]}},{"n":14,"answer":"A","section":{"en":"Illustrative scenario: building MediBec's portfolio","fr":"Mise en situation : la constitution du portefeuille de MediBec"},"q":{"en":"In the MediBec example, P10 (staff disclosure of patient information through unapproved AI tools) did not rank in the top ten under every scheme. Why was it selected?","fr":"Dans l’exemple de MediBec, P10 (divulgation de renseignements sur les patients par le personnel au moyen d’outils d’IA non approuvés) ne figurait pas parmi les dix premiers selon tous les schémas. Pourquoi a-t-il été retenu?"},"options":{"en":["For coverage and decision usefulness, since no other scenario addressed negligent insiders or AI","Because it had the highest total score in the entire candidate population","Because its representative weakness had a critical CVSS score requiring selection","Because generic scenario libraries list AI misuse as a mandatory scenario family"],"fr":["Pour la couverture et l’utilité pour la décision, puisqu’aucun autre scénario ne traitait des initiés négligents ou de l’IA","Parce qu’il avait le total le plus élevé de toute la population de candidats","Parce que sa faiblesse représentative avait un score CVSS critique exigeant sa sélection","Parce que les bibliothèques de scénarios génériques classent le mauvais usage de l’IA comme famille de scénarios obligatoire"]}},{"n":15,"answer":"C","section":{"en":"Illustrative scenario: building MediBec's portfolio","fr":"Mise en situation : la constitution du portefeuille de MediBec"},"q":{"en":"Why was C31, sabotage by a malicious or departing IT administrator, placed on the watch list instead of being selected?","fr":"Pourquoi C31, le sabotage par un administrateur des TI malveillant ou sur le départ, a-t-il été placé dans la liste de surveillance au lieu d’être retenu?"},"options":{"en":["Its total score was too low for any further consideration","It carried no escalation flags in the MediBec selection workbook","Its treatments come through P01 and P02, a reliance marked for management decision","CRG excludes insider scenarios from portfolios by default"],"fr":["Son total était trop faible pour un examen plus poussé","Il ne portait aucun indicateur de remontée dans le classeur de sélection de MediBec","Ses traitements passent par P01 et P02, une dépendance qui exige une décision de la direction","CRG exclut par défaut les scénarios de menace interne des portefeuilles"]}},{"n":16,"answer":"B","section":{"en":"Standards compatibility","fr":"Compatibilité avec les normes"},"q":{"en":"Which three assessment methods from NIST SP 800-53A Rev. 5 should scenario documentation make possible?","fr":"Quelles sont les trois méthodes d’évaluation de la publication NIST SP 800-53A Rev. 5 que la documentation des scénarios devrait rendre possibles?"},"options":{"en":["Plan, do, check, and act","Examine, interview, and test","Identify, protect, and detect","Scan, patch, and verify"],"fr":["Planifier, réaliser, vérifier et agir","Examiner, interroger et tester","Identifier, protéger et détecter","Analyser, corriger et vérifier"]}},{"n":17,"answer":"A","section":{"en":"Who to include in scenario creation","fr":"Qui faire participer à l’élaboration des scénarios"},"q":{"en":"During scenario creation, the CIO states that backups are isolated, but the infrastructure team is unsure. How should the analyst handle this?","fr":"Pendant l’élaboration des scénarios, le DPI affirme que les sauvegardes sont isolées, mais l’équipe d’infrastructure n’en est pas certaine. Comment l’analyste devrait-il gérer cette situation?"},"options":{"en":["Record the disagreement as a finding and add it to the evidence-collection plan","Accept the CIO's view, since the CIO holds the most senior authority","Average the opinions and record the backups as partially isolated","Remove ransomware scenarios until both teams reach unanimous agreement"],"fr":["Consigner le désaccord comme une constatation et l’ajouter au plan de collecte des éléments probants","Retenir l’avis du DPI, puisqu’il détient l’autorité la plus élevée","Faire la moyenne des avis et consigner les sauvegardes comme partiellement isolées","Retirer les scénarios de rançongiciel jusqu’à ce que les deux équipes s’entendent à l’unanimité"]}},{"n":18,"answer":"D","section":{"en":"Using generative AI responsibly to draft scenarios","fr":"Utiliser l’IA générative de façon responsable pour rédiger des scénarios"},"q":{"en":"A team wants to paste real architecture diagrams and audit findings into a public AI chatbot to draft scenarios. What does the chapter advise?","fr":"Une équipe veut coller de véritables schémas d’architecture et constatations d’audit dans un robot conversationnel d’IA public pour rédiger des scénarios. Que recommande le chapitre?"},"options":{"en":["Proceed, because scenario drafting does not involve personal information","Proceed, provided each AI-generated scenario carries an estimate marker","Remove the organization's name, then use any available AI service","Do not, unless authorized in writing and lawful; prefer a local or contracted service"],"fr":["Aller de l’avant, car la rédaction de scénarios ne porte pas sur des renseignements personnels","Aller de l’avant, pourvu que chaque scénario généré par l’IA porte une mention d’estimation","Retirer le nom de l’organisation, puis utiliser n’importe quel service d’IA disponible","Ne pas le faire, sauf autorisation écrite et traitement licite; préférer un service local ou sous contrat"]}},{"n":19,"answer":"C","section":{"en":"Using generative AI responsibly to draft scenarios","fr":"Utiliser l’IA générative de façon responsable pour rédiger des scénarios"},"q":{"en":"Under the rules in CRG's education package, which of the following may an AI tool do?","fr":"Selon les règles de la trousse pédagogique de CRG, laquelle des actions suivantes un outil d’IA peut-il accomplir?"},"options":{"en":["State organizational facts that the evidence register does not contain","Produce final risk numbers without recomputation by a verified engine","Propose parameter values with rationales for analysts to critique","Supply control identifiers and legal obligations without verification"],"fr":["Énoncer des faits sur l’organisation que le registre des éléments probants ne contient pas","Produire des chiffres de risque définitifs sans recalcul par un moteur vérifié","Proposer des valeurs de paramètres justifiées que les analystes critiqueront","Fournir des identifiants de contrôles et des obligations légales sans vérification"]}},{"n":20,"answer":"B","section":{"en":"From scenarios to quantification: preparing Chapter 6","fr":"Des scénarios à la quantification : préparer le chapitre 6"},"q":{"en":"Which Chapter 6 parameter answers the question 'if the threat acts, will it succeed against this weakness given existing controls?'","fr":"Quel paramètre du chapitre 6 répond à la question « si la menace agit, réussira-t-elle contre cette faiblesse, compte tenu des contrôles existants? »"},"options":{"en":["Pb(A), the probability that the threat is present","Pb(ψ,A), the probability of exploitation","δe, the expected damage if the scenario occurs","μ(E), the organizational criticality of the process"],"fr":["Pb(A), la probabilité de présence de la menace","Pb(ψ,A), la probabilité d’exploitation","δe, le dommage estimé si le scénario se produit","μ(E), la criticité organisationnelle du processus"]}}]},{"n":6,"title":{"en":"Chapter 6: Performing a Cybersecurity Risk Assessment","fr":"Chapitre 6 : Réalisation d’une évaluation des risques de cybersécurité"},"questions":[{"n":1,"answer":"A","section":{"en":"Inputs and the CyberRiskGuardian workflow","fr":"L’indice de risque et les formules sous-jacentes"},"q":{"en":"According to the chapter, what is the most common way a CRG assessment loses its credibility during the workflow?","fr":"Selon le chapitre, de quelle façon une évaluation CRG perd-elle le plus souvent sa crédibilité au cours de la démarche?"},"options":{"en":["Setting the risk appetite after the numbers are already known","Using a 12-month horizon instead of a multi-year horizon","Generating more than twenty candidate scenarios for ten","Recording evidence identifiers for every organizational fact"],"fr":["En fixant l’appétence pour le risque une fois les chiffres déjà connus","En utilisant un horizon de 12 mois plutôt qu’un horizon pluriannuel","En générant plus de vingt scénarios candidats pour dix scénarios","En consignant des identifiants d’éléments probants pour chaque fait sur l’organisation"]}},{"n":2,"answer":"C","section":{"en":"From concepts to practice: purpose and standards alignment","fr":"Des concepts à la pratique : objet et alignement sur les normes"},"q":{"en":"In the NIST Risk Management Framework (SP 800-37 Rev. 2), which activity does a CRG risk assessment correspond to?","fr":"Dans le cadre de gestion des risques (RMF) du NIST (SP 800-37 Rev. 2), à quelle activité une évaluation des risques CRG correspond-elle?"},"options":{"en":["The Assess step, which verifies that selected controls operate as intended","The Authorize step, which accepts residual risk for a system","The risk assessment tasks of the Prepare step, at organization and system levels","The Monitor step, which tracks controls and risk on an ongoing basis"],"fr":["À l’étape Assess, qui vérifie que les contrôles choisis fonctionnent comme prévu","À l’étape Authorize, qui accepte le risque résiduel d’un système","Aux tâches d’évaluation des risques de l’étape Prepare, aux niveaux de l’organisation et du système","À l’étape Monitor, qui suit les contrôles et le risque de façon continue"]}},{"n":3,"answer":"B","section":{"en":"The risk index and underlying formulas","fr":"L’indice de risque et les formules sous-jacentes"},"q":{"en":"Why does CRG require Pb(A) and Pb(ψ,A) to be estimated separately rather than as a single likelihood?","fr":"Pourquoi CRG exige-t-il que Pb(A) et Pb(ψ,A) soient estimées séparément plutôt que sous forme d’une vraisemblance unique?"},"options":{"en":["Because CVSS already contains the threat probability for each weakness","Because merging them counts the same uncertainty twice","Because Pb(A) applies only to insiders and Pb(ψ,A) to outsiders","Because the workbook cannot store a combined likelihood value"],"fr":["Parce que le CVSS contient déjà la probabilité de menace de chaque faiblesse","Parce que les fusionner compte deux fois la même incertitude","Parce que Pb(A) ne s’applique qu’aux initiés et Pb(ψ,A) qu’aux acteurs externes","Parce que le classeur ne peut pas stocker une valeur de vraisemblance combinée"]}},{"n":4,"answer":"D","section":{"en":"Step-by-step procedure in the spreadsheet and the application","fr":"Procédure pas à pas dans le tableur et dans l’application"},"q":{"en":"A quality reviewer finds that a student memo reports a residual risk of 1,940 while the recalculated workbook shows 1,937.18. How does the chapter treat this?","fr":"Une personne réviseure constate qu’une note de service d’un étudiant indique un risque résiduel de 1 940, alors que le classeur recalculé affiche 1 937,18. Comment le chapitre traite-t-il cette situation?"},"options":{"en":["As acceptable rounding, since indices are dimensionless and approximate","As a minor style issue that the instructor may ignore","As evidence that the multiplication factor was changed mid-assessment","As the most common finding, since the memo must agree with the workbook to the unit"],"fr":["Comme un arrondi acceptable, puisque les indices sont sans dimension et approximatifs","Comme une question de style mineure que l’enseignant peut ignorer","Comme la preuve que le facteur de multiplication a été modifié en cours d’évaluation","Comme la constatation la plus courante, puisque la note doit concorder avec le classeur à l’unité près"]}},{"n":5,"answer":"B","section":{"en":"The risk index and underlying formulas","fr":"L’indice de risque et les formules sous-jacentes"},"q":{"en":"A scenario has Pb(A) = 0.50, Pb(ψ,A) = 0.40, CVSS = 8.0, δe = 0.40, δm = 0.60, μ(E) = 0.80, θ = 0.50, and a factor of 1,000. What is its estimated risk (Re)?","fr":"Un scénario a Pb(A) = 0,50, Pb(ψ,A) = 0,40, CVSS = 8,0, δe = 0,40, δm = 0,60, μ(E) = 0,80, θ = 0,50 et un facteur de 1 000. Quel est son risque estimé (Re)?"},"options":{"en":["640","1,280","1,536","320"],"fr":["640","1 280","1 536","320"]}},{"n":6,"answer":"A","section":{"en":"Step-by-step procedure in the spreadsheet and the application","fr":"L’indice de risque et les formules sous-jacentes"},"q":{"en":"Before treatment, a scenario has δe = 0.50 and δm = 0.70, and the organization's appetite is 0.40. Using the cancellation property, what is its pre-treatment ratio?","fr":"Avant traitement, un scénario a δe = 0,50 et δm = 0,70, et l’appétence de l’organisation est de 0,40. À l’aide de la propriété d’annulation, quel est son ratio avant traitement?"},"options":{"en":["1.50","0.67","1.75","1.25"],"fr":["1,50","0,67","1,75","1,25"]}},{"n":7,"answer":"C","section":{"en":"The risk index and underlying formulas","fr":"L’indice de risque et les formules sous-jacentes"},"q":{"en":"A scenario's estimated risk is 2,000. Its treatment package has a probability reduction (rp) of 0.80 and an impact reduction (ri) of 0.50. What are the mitigated and residual risk?","fr":"Le risque estimé d’un scénario est de 2 000. Son ensemble de mesures a une réduction de la probabilité (rp) de 0,80 et une réduction de l’impact (ri) de 0,50. Quels sont le risque atténué et le risque résiduel?"},"options":{"en":["Mitigated 1,300; residual 700","Mitigated 1,000; residual 1,000","Mitigated 800; residual 1,200","Mitigated 1,200; residual 800"],"fr":["Atténué 1 300; résiduel 700","Atténué 1 000; résiduel 1 000","Atténué 800; résiduel 1 200","Atténué 1 200; résiduel 800"]}},{"n":8,"answer":"B","section":{"en":"The risk index and underlying formulas","fr":"L’indice de risque et les formules sous-jacentes"},"q":{"en":"A scenario has δe = 0.50, δm = 0.70, appetite 0.40, and a package with rp = 0.60 and ri = 0.50. What is the post-treatment risk-to-tolerance ratio, and how is it read?","fr":"Un scénario a δe = 0,50, δm = 0,70, une appétence de 0,40 et un ensemble de mesures avec rp = 0,60 et ri = 0,50. Quel est le ratio de tolérance après traitement, et comment se lit-il?"},"options":{"en":["0.30, below tolerance","1.05, approximately at tolerance","1.50, above tolerance","1.20, above tolerance"],"fr":["0,30, sous la tolérance","1,05, approximativement à la tolérance","1,50, au-dessus de la tolérance","1,20, au-dessus de la tolérance"]}},{"n":9,"answer":"D","section":{"en":"The risk index and underlying formulas","fr":"L’indice de risque et les formules sous-jacentes"},"q":{"en":"A treatment package costing $40,000 lowers a scenario's risk from an estimated 2,000 to a residual of 1,200. What is its cost-effectiveness under CRG's formula?","fr":"Un ensemble de mesures qui coûte 40 000 $ fait passer le risque d’un scénario d’un risque estimé de 2 000 à un risque résiduel de 1 200. Quel est son coût-efficacité selon la formule de CRG?"},"options":{"en":["0.02 risk units per $1,000","30.0 risk units per $1,000","50.0 risk units per $1,000","20.0 risk units per $1,000"],"fr":["0,02 unité de risque par tranche de 1 000 $","30,0 unités de risque par tranche de 1 000 $","50,0 unités de risque par tranche de 1 000 $","20,0 unités de risque par tranche de 1 000 $"]}},{"n":10,"answer":"A","section":{"en":"The risk index and underlying formulas","fr":"L’indice de risque et les formules sous-jacentes"},"q":{"en":"A scenario has an average damage ((δe + δm) ÷ 2) of 0.60, and the appetite is 0.30. Using the design rule, what minimum value must rp × ri reach for the residual to be no greater than tolerated risk?","fr":"Un scénario a un dommage moyen ((δe + δm) ÷ 2) de 0,60, et l’appétence est de 0,30. Selon la règle de conception, quelle valeur minimale rp × ri doit-il atteindre pour que le risque résiduel ne dépasse pas le risque toléré?"},"options":{"en":["0.50","0.55","0.30","0.70"],"fr":["0,50","0,55","0,30","0,70"]}},{"n":11,"answer":"C","section":{"en":"Prioritization, portfolio, and budget calibration","fr":"Priorisation, portefeuille et calibrage du budget"},"q":{"en":"An organization with an appetite of 0.60 has a total IT budget, including salaries, of $20 million. What appetite-consistent cybersecurity budget target does CRG's best-practice benchmark give?","fr":"Une organisation dont l’appétence est de 0,60 a un budget total des TI, salaires compris, de 20 millions de dollars. Quelle cible de budget de cybersécurité alignée sur l’appétence le repère de pratique exemplaire de CRG donne-t-il?"},"options":{"en":["7.8%, or $1.56 million","5.7%, or $1.14 million","5.9%, or $1.18 million","4.0%, or $0.80 million"],"fr":["7,8 %, soit 1,56 M$","5,7 %, soit 1,14 M$","5,9 %, soit 1,18 M$","4,0 %, soit 0,80 M$"]}},{"n":12,"answer":"D","section":{"en":"Role of IM, BCP, and DRP in dealing with residual risk","fr":"Rôle de la gestion des incidents, du PCA et du PRS dans le traitement du risque résiduel"},"q":{"en":"How does the chapter link incident management, business continuity, and disaster recovery to the CRG formulas?","fr":"Comment le chapitre relie-t-il la gestion des incidents, la continuité des activités et la reprise après sinistre aux formules de CRG?"},"options":{"en":["They are recorded as transfer lines that lower the impact reduction","They replace the need to accept residual risk formally","They are scored as the representative weakness for CVSS","Tested recovery and practised response justify higher θ and lower indices"],"fr":["Ils sont consignés comme des lignes de transfert qui diminuent la réduction de l’impact","Ils dispensent d’accepter formellement le risque résiduel","Ils sont cotés comme la faiblesse représentative pour le CVSS","Une reprise testée et une intervention exercée justifient un θ plus élevé et des indices plus faibles"]}},{"n":13,"answer":"B","section":{"en":"The risk index and underlying formulas","fr":"L’indice de risque et les formules sous-jacentes"},"q":{"en":"A scenario with Re = 1,500 is treated only by cyber insurance, entered with rp = 0 and ri = 0.90. Under CRG's convention, what happens?","fr":"Un scénario dont Re = 1 500 n’est traité que par une cyberassurance, saisie avec rp = 0 et ri = 0,90. Selon la convention de CRG, que se passe-t-il?"},"options":{"en":["Mitigated 1,350 and residual 150, so the scenario falls below tolerance","Mitigated 0 and residual 1,500; transfer is recorded as a costed decision","Mitigated 750 and residual 750, as insurance halves the exposure","Mitigated 1,500 and residual 0, because the loss is fully transferred"],"fr":["Atténué 1 350 et résiduel 150; le scénario passe donc sous la tolérance","Atténué 0 et résiduel 1 500; le transfert est consigné comme une décision chiffrée","Atténué 750 et résiduel 750, puisque l’assurance réduit l’exposition de moitié","Atténué 1 500 et résiduel 0, parce que la perte est entièrement transférée"]}},{"n":14,"answer":"A","section":{"en":"The risk index and underlying formulas","fr":"L’indice de risque et les formules sous-jacentes"},"q":{"en":"An analyst credits twenty controls with a probability reduction of 0.06 each. How does CyberRiskGuardian combine them into the package's probability reduction?","fr":"Un analyste attribue à vingt contrôles une réduction de la probabilité de 0,06 chacun. Comment CyberRiskGuardian les combine-t-il pour obtenir la réduction de la probabilité de l’ensemble de mesures?"},"options":{"en":["With the product rule, 1 − ∏(1 − rᵢ), giving about 0.71 and never more than 1","By adding them, giving 1.20, which the workbook then caps at 1","By averaging them, so the package keeps a reduction of 0.06","By keeping only the strongest control, so the package reduction is 0.06"],"fr":["Selon la règle du produit, 1 − ∏(1 − rᵢ), ce qui donne environ 0,71 et jamais plus de 1","En les additionnant, ce qui donne 1,20, que le classeur plafonne ensuite à 1","En faisant leur moyenne, de sorte que l’ensemble conserve une réduction de 0,06","En ne retenant que le contrôle le plus fort, de sorte que la réduction de l’ensemble est de 0,06"]}},{"n":15,"answer":"C","section":{"en":"The risk index and underlying formulas","fr":"L’indice de risque et les formules sous-jacentes"},"q":{"en":"Two scenarios share the same δe, δm, appetite, and treatment package, but one has Pb(A) = 0.20 and the other Pb(A) = 0.80, all else equal. What does the cancellation property imply?","fr":"Deux scénarios ont les mêmes δe, δm, appétence et ensemble de mesures, mais l’un a Pb(A) = 0,20 et l’autre Pb(A) = 0,80, toutes choses égales par ailleurs. Qu’implique la propriété d’annulation?"},"options":{"en":["The likelier scenario has a ratio four times higher","The rarer scenario is automatically below tolerance","Both get the same verdict, but the likelier one has four times the Re","Neither ratio can be computed until CVSS scores differ"],"fr":["Le scénario le plus probable a un ratio quatre fois plus élevé","Le scénario le plus rare est automatiquement sous la tolérance","Les deux obtiennent le même verdict, mais le plus probable a un Re quatre fois plus élevé","Aucun ratio ne peut être calculé tant que les scores CVSS ne diffèrent pas"]}},{"n":16,"answer":"D","section":{"en":"Inputs and the CyberRiskGuardian workflow","fr":"Vulnérabilités non techniques : la cotation par équivalence"},"q":{"en":"Which of the following is deliberately absent from CRG's step 16 prioritization criteria?","fr":"Lequel des éléments suivants est délibérément absent des critères de priorisation de l’étape 16 de CRG?"},"options":{"en":["Maximum consequence and safety","Risk velocity and threat activity","Shared benefits of foundational controls","The CVSS score of the representative weakness"],"fr":["La conséquence maximale et la sécurité des personnes","La vélocité du risque et l’activité des menaces","Les bénéfices partagés des contrôles fondamentaux","Le score CVSS de la faiblesse représentative"]}},{"n":17,"answer":"B","section":{"en":"Scoring vulnerabilities with CVSS v4.0","fr":"Cotation des vulnérabilités avec le CVSS v4.0"},"q":{"en":"A representative weakness is a macro-enabled document that executes code when a user opens it after receiving it by e-mail. Which CVSS v4.0 Attack Vector value applies?","fr":"Une faiblesse représentative est un document contenant des macros qui exécute du code lorsqu’un utilisateur l’ouvre après l’avoir reçu par courriel. Quelle valeur du vecteur d’attaque du CVSS v4.0 s’applique?"},"options":{"en":["Network, because the document arrived by e-mail","Local, because the document is opened on the workstation","Adjacent, because the user is on the internal network","Physical, because the user must handle the device"],"fr":["Réseau, parce que le document est arrivé par courriel","Local, parce que le document est ouvert sur le poste de travail","Adjacent, parce que l’utilisateur se trouve sur le réseau interne","Physique, parce que l’utilisateur doit manipuler l’appareil"]}},{"n":18,"answer":"C","section":{"en":"Non-technical vulnerabilities by equivalency","fr":"Vulnérabilités non techniques : la cotation par équivalence"},"q":{"en":"When a non-technical weakness is scored with CVSS v4.0 by equivalency, which three things does CRG require?","fr":"Lorsqu’une faiblesse non technique est cotée avec le CVSS v4.0 par équivalence, quels sont les trois éléments qu’exige CRG?"},"options":{"en":["A vendor advisory, a CVE identifier, and a Threat metric","A Supplemental Safety metric, an Environmental score, and a penetration test","A justification per metric, the label limited applicability, and the estimate marker","A CVSS-BTE score, a severity band of High, and board approval"],"fr":["Un avis de fournisseur, un identifiant CVE et une métrique de menace","Une métrique supplémentaire de sécurité des personnes, un score environnemental et un test d’intrusion","Une justification par métrique, la mention d’applicabilité limitée et la mention d’estimation","Un score CVSS-BTE, une plage de gravité Élevée et l’approbation du conseil d’administration"]}},{"n":19,"answer":"A","section":{"en":"The risk index and underlying formulas","fr":"L’indice de risque et les formules sous-jacentes"},"q":{"en":"Phishing-resistant MFA reduces three scenarios in a portfolio. How does CRG treat this shared control?","fr":"Une AMF résistante à l’hameçonnage réduit trois scénarios d’un portefeuille. Comment CRG traite-t-il ce contrôle partagé?"},"options":{"en":["Its effect is credited in each package, but its cost is counted once in the portfolio","Its cost is counted in full in each of the three scenarios' packages","It is credited to only one scenario to avoid double-counting its effect","It is excluded from packages because existing controls cannot be recommended"],"fr":["Son effet est porté au crédit de chaque ensemble de mesures, mais son coût est compté une seule fois dans le portefeuille","Son coût est compté en entier dans l’ensemble de mesures de chacun des trois scénarios","Il n’est porté au crédit que d’un seul scénario pour éviter de compter son effet deux fois","Il est exclu des ensembles de mesures parce que les contrôles existants ne peuvent être recommandés"]}},{"n":20,"answer":"D","section":{"en":"Key risk indicators for monitoring","fr":"L’indice de risque et les formules sous-jacentes"},"q":{"en":"Which statement correctly distinguishes a key risk indicator (KRI) from CRG's calculated risk indices?","fr":"Quel énoncé distingue correctement un indicateur clé de risque (ICR) des indices de risque calculés de CRG?"},"options":{"en":["KRIs are Re and Rt values recalculated monthly by the workbook","KRIs are risk indices expressed in dollars rather than units","KRIs are the residual risks that exceed the 1.10 band","KRIs are measured values from a named source compared with thresholds"],"fr":["Les ICR sont les valeurs Re et Rt recalculées chaque mois par le classeur","Les ICR sont des indices de risque exprimés en dollars plutôt qu’en unités","Les ICR sont les risques résiduels qui dépassent la plage de 1,10","Les ICR sont des valeurs mesurées à partir d’une source désignée et comparées à des seuils"]}}]},{"n":7,"title":{"en":"Chapter 7: Cybersecurity Operations","fr":"Chapitre 7 : Opérations de cybersécurité"},"questions":[{"n":1,"answer":"B","section":{"en":"Cybersecurity operations and the risk-centric logic of governance","fr":"Les opérations de cybersécurité et la logique de gouvernance axée sur le risque"},"q":{"en":"According to the chapter, what is the most straightforward way for managers to understand cybersecurity operations?","fr":"Selon le chapitre, quelle est la façon la plus simple pour les gestionnaires de comprendre les opérations de cybersécurité?"},"options":{"en":["As the purchase and configuration of security products","As carrying out and maintaining risk management decisions","As the technical work of the IT department alone","As a compliance activity performed before external audits"],"fr":["Comme l’achat et la configuration de produits de sécurité","Comme l’exécution et le maintien des décisions de gestion des risques","Comme le travail technique du seul service des TI","Comme une activité de conformité réalisée avant les audits externes"]}},{"n":2,"answer":"D","section":{"en":"Operational challenges: people, process, and complexity","fr":"Défis opérationnels : personnes, processus et complexité"},"q":{"en":"Which element is NOT listed among the minimum components a sound cybersecurity operating model should define?","fr":"Quel élément ne figure PAS parmi les composantes minimales qu’un modèle opérationnel de cybersécurité solide devrait définir?"},"options":{"en":["Ownership and accountability","Standardized and auditable processes","Performance measures of efficiency and effectiveness","A commitment to eliminate all identified risks"],"fr":["La propriété et l’imputabilité","Des processus normalisés et auditables","Des mesures de performance d’efficience et d’efficacité","Un engagement à éliminer tous les risques relevés"]}},{"n":3,"answer":"A","section":{"en":"Building the cybersecurity operations capability: people, process, technology, and authority","fr":"Bâtir la capacité d’opérations de cybersécurité : personnes, processus, technologie et autorité"},"q":{"en":"Why does the chapter describe executive sponsorship as a crucial enabler rather than a soft factor?","fr":"Pourquoi le chapitre décrit-il le parrainage de la direction comme un facteur habilitant essentiel plutôt que comme un facteur secondaire?"},"options":{"en":["Without it, the function struggles to secure funding, enforce standards, or mandate remediation","It replaces the need for documented processes, measurable controls, and regular reporting","It allows the security team to bypass normal IT change procedures when urgent","It guarantees that the organization will pass its next external certification audit"],"fr":["Sans lui, la fonction peine à obtenir du financement, à faire respecter les normes ou à imposer des mesures correctives","Il remplace le besoin de processus documentés, de contrôles mesurables et de rapports réguliers","Il permet à l’équipe de sécurité de contourner les procédures normales de changement des TI en cas d’urgence","Il garantit que l’organisation réussira son prochain audit de certification externe"]}},{"n":4,"answer":"C","section":{"en":"The five-step operational cybersecurity cycle, viewing OPSEC as a managerial process","fr":"Le cycle opérationnel en cinq étapes de la cybersécurité : l’OPSEC vue comme un processus de gestion"},"q":{"en":"In the five-step operational cycle, during which step does the organization estimate the significance of each threat-vulnerability pair in terms of likelihood and business impact?","fr":"Dans le cycle opérationnel en cinq étapes, à quelle étape l’organisation estime-t-elle l’importance de chaque paire menace-vulnérabilité en matière de vraisemblance et d’impact sur les affaires?"},"options":{"en":["Step 1: Identify sensitive data and critical assets","Step 2: Identify relevant threats","Step 4: Appraise the exposure to adverse outcomes","Step 5: Implement countermeasures and monitor"],"fr":["Étape 1 : déterminer les données sensibles et les actifs critiques","Étape 2 : déterminer les menaces pertinentes","Étape 4 : apprécier l’exposition aux résultats défavorables","Étape 5 : mettre en œuvre les contre-mesures et surveiller"]}},{"n":5,"answer":"C","section":{"en":"Operational challenges: people, process, and complexity","fr":"Défis opérationnels : personnes, processus et complexité"},"q":{"en":"A team lists shared dispatcher accounts, a flat network, and SaaS applications that send no logs. Which step of the five-step cycle is it performing?","fr":"Une équipe relève des comptes de répartiteurs partagés, un réseau non segmenté et des applications SaaS qui n’envoient aucun journal. Quelle étape du cycle en cinq étapes réalise-t-elle?"},"options":{"en":["Identifying critical assets and sensitive data","Identifying relevant threats to the organization","Identifying vulnerabilities and weaknesses","Implementing countermeasures and monitoring effectiveness"],"fr":["La détermination des actifs critiques et des données sensibles","La détermination des menaces pertinentes pour l’organisation","La détermination des vulnérabilités et des faiblesses","La mise en œuvre des contre-mesures et la surveillance de leur efficacité"]}},{"n":6,"answer":"A","section":{"en":"Core operational practices that prevent predictable failures","fr":"Pratiques opérationnelles fondamentales qui préviennent les défaillances prévisibles"},"q":{"en":"The chapter states that an asset inventory is a governance mechanism, not merely a technical list. What makes it a governance mechanism?","fr":"Le chapitre affirme qu’un inventaire des actifs est un mécanisme de gouvernance, et pas seulement une liste technique. Qu’est-ce qui en fait un mécanisme de gouvernance?"},"options":{"en":["Each important asset has an owner, business purpose, criticality, and expected protection level","It is maintained exclusively by the security operations centre for its own use","It lists every device on the network regardless of its business importance","It is reviewed only once a year, during the annual certification audit"],"fr":["Chaque actif important a un responsable, une finalité d’affaires, une criticité et un niveau de protection attendu","Il est tenu exclusivement par le centre des opérations de sécurité pour son propre usage","Il énumère chaque appareil du réseau, quelle que soit son importance pour les affaires","Il n’est revu qu’une fois par année, lors de l’audit de certification annuel"]}},{"n":7,"answer":"B","section":{"en":"Core operational practices that prevent predictable failures","fr":"Pratiques opérationnelles fondamentales qui préviennent les défaillances prévisibles"},"q":{"en":"Why should administrative accounts be separated from regular user accounts in sensitive environments?","fr":"Pourquoi les comptes d’administration devraient-ils être séparés des comptes d’utilisateur ordinaires dans les environnements sensibles?"},"options":{"en":["To allow administrators to skip multi-factor authentication on daily tasks","To reduce the chance that email, browsing, or phishing exposes privileged credentials","To keep privileged actions out of the central logging platform and its reports","To remove the need for periodic reviews of privileged access rights"],"fr":["Pour permettre aux administrateurs d’éviter l’authentification multifacteur dans leurs tâches quotidiennes","Pour réduire le risque que le courriel, la navigation ou l’hameçonnage exposent des identifiants privilégiés","Pour garder les actions privilégiées hors de la plateforme de journalisation centrale et de ses rapports","Pour éliminer le besoin de revues périodiques des droits d’accès privilégiés"]}},{"n":8,"answer":"D","section":{"en":"Core operational practices that prevent predictable failures","fr":"Pratiques opérationnelles fondamentales qui préviennent les défaillances prévisibles"},"q":{"en":"Which statement best reflects the chapter's view of automation in cybersecurity operations?","fr":"Quel énoncé reflète le mieux le point de vue du chapitre sur l’automatisation dans les opérations de cybersécurité?"},"options":{"en":["Automation should replace analyst judgment wherever it is technically possible to do so","Automation is useful mainly for producing monthly management reports and dashboards","Automation should be avoided because it tends to amplify human mistakes","Automation should reinforce approved processes and be governed, tested, logged, and overseen"],"fr":["L’automatisation devrait remplacer le jugement des analystes partout où c’est techniquement possible","L’automatisation sert surtout à produire les rapports mensuels et les tableaux de bord de la direction","L’automatisation devrait être évitée parce qu’elle tend à amplifier les erreurs humaines","L’automatisation devrait renforcer les processus approuvés et être encadrée, testée, journalisée et supervisée"]}},{"n":9,"answer":"A","section":{"en":"Core operational practices that prevent predictable failures","fr":"Pratiques opérationnelles fondamentales qui préviennent les défaillances prévisibles"},"q":{"en":"How does the chapter distinguish incident response, disaster recovery, and business continuity?","fr":"Comment le chapitre distingue-t-il l’intervention en cas d’incident, la reprise après sinistre et la continuité des activités?"},"options":{"en":["Incident response handles security incidents, disaster recovery restores technology, business continuity maintains critical functions","They are three names for the same process used by different departments","Disaster recovery handles security incidents, while incident response restores technology","Business continuity is a technical activity, while incident response is a business activity"],"fr":["L’intervention traite les incidents de sécurité, la reprise rétablit la technologie, la continuité maintient les fonctions critiques","Ce sont trois noms pour le même processus, employés par des services différents","La reprise après sinistre traite les incidents de sécurité, tandis que l’intervention rétablit la technologie","La continuité des activités est une activité technique, tandis que l’intervention est une activité d’affaires"]}},{"n":10,"answer":"C","section":{"en":"The security operations centre (SOC): purpose, tiers, and modern operating models","fr":"Le centre des opérations de sécurité (COS) : finalité, niveaux et modèles opérationnels modernes"},"q":{"en":"In a tiered SOC, which tier normally reviews alerts, identifies likely false positives, executes approved first-response actions, and escalates uncertain or severe events?","fr":"Dans un COS à niveaux, quel niveau examine normalement les alertes, repère les faux positifs probables, exécute les premières actions d’intervention approuvées et fait remonter les événements incertains ou graves?"},"options":{"en":["Tier 3","Tier 2","Tier 1","The executive crisis team"],"fr":["Le niveau 3","Le niveau 2","Le niveau 1","La cellule de crise de la direction"]}},{"n":11,"answer":"B","section":{"en":"The security operations centre (SOC): purpose, tiers, and modern operating models","fr":"Le centre des opérations de sécurité (COS) : finalité, niveaux et modèles opérationnels modernes"},"q":{"en":"Which risk does the chapter associate with tiered SOC operations?","fr":"Quel risque le chapitre associe-t-il aux opérations d’un COS à niveaux?"},"options":{"en":["Tiering forces specialists to spend most of their time on routine alerts","Poor handoffs and unclear escalation criteria can delay detection or weaken response","Tiering makes it impossible to process large volumes of daily alerts","Tiered models cannot be combined with playbooks or severity criteria"],"fr":["La structure à niveaux oblige les spécialistes à consacrer la majeure partie de leur temps aux alertes courantes","De mauvaises transmissions et des critères de remontée flous peuvent retarder la détection ou affaiblir l’intervention","La structure à niveaux rend impossible le traitement de grands volumes d’alertes quotidiennes","Les modèles à niveaux ne peuvent pas être combinés avec des guides d’intervention ou des critères de gravité"]}},{"n":12,"answer":"D","section":{"en":"The security operations centre (SOC): purpose, tiers, and modern operating models","fr":"Le centre des opérations de sécurité (COS) : finalité, niveaux et modèles opérationnels modernes"},"q":{"en":"Why do modern SOCs integrate telemetry from identity, cloud, endpoints, suppliers, physical access, and operational technology?","fr":"Pourquoi les COS modernes intègrent-ils la télémétrie provenant de l’identité, du nuage, des terminaux, des fournisseurs, du contrôle d’accès physique et de la technologie opérationnelle?"},"options":{"en":["Because the SOC must take ownership of all of those functions itself","Because network monitoring is no longer accepted by most security standards","Because integration removes the need for separate incident response teams and plans","Because many cyber events are visible only when signals from several domains are combined"],"fr":["Parce que le COS doit prendre en charge lui-même toutes ces fonctions","Parce que la surveillance du réseau n’est plus reconnue par la plupart des normes de sécurité","Parce que l’intégration élimine le besoin d’équipes et de plans d’intervention distincts","Parce que de nombreux cyberévénements ne sont visibles que lorsque des signaux de plusieurs domaines sont combinés"]}},{"n":13,"answer":"A","section":{"en":"Operational challenges: people, process, and complexity","fr":"Défis opérationnels : personnes, processus et complexité"},"q":{"en":"An organization outsources 24/7 monitoring to a managed security service provider. According to the chapter, what remains the organization's responsibility?","fr":"Une organisation confie la surveillance 24 h/24, 7 j/7 à un fournisseur de services de sécurité gérés. Selon le chapitre, qu’est-ce qui demeure sa responsabilité?"},"options":{"en":["Accountability for cybersecurity outcomes, escalation decisions, and residual risk acceptance","Only the payment of the monthly service fee to the provider","Nothing further, provided the contract includes service-level targets","Only the selection and licensing of the provider's monitoring tools"],"fr":["L’imputabilité des résultats de cybersécurité, les décisions de remontée et l’acceptation du risque résiduel","Seulement le paiement des frais de service mensuels au fournisseur","Plus rien, pourvu que le contrat comporte des cibles de niveau de service","Seulement le choix et l’octroi de licences des outils de surveillance du fournisseur"]}},{"n":14,"answer":"C","section":{"en":"The security operations centre (SOC): purpose, tiers, and modern operating models","fr":"Défis opérationnels : personnes, processus et complexité"},"q":{"en":"A firm owns a SIEM receiving logs from 40% of critical systems, an EDR on half its endpoints, and a scanner unconnected to remediation. What is the chapter's most likely diagnosis?","fr":"Une entreprise possède un SIEM qui reçoit les journaux de 40 % des systèmes critiques, un EDR sur la moitié de ses terminaux et un scanneur non relié aux corrections. Quel est le diagnostic le plus probable selon le chapitre?"},"options":{"en":["The firm has achieved operational maturity through tool coverage","The firm should purchase additional tool categories to close gaps","The firm owns tools but has not operationalized them into a capability","The firm should eliminate monitoring until all tools are fully deployed"],"fr":["L’entreprise a atteint la maturité opérationnelle grâce à la couverture de ses outils","L’entreprise devrait acheter de nouvelles catégories d’outils pour combler les lacunes","L’entreprise possède des outils, mais ne les a pas transformés en capacité opérationnelle","L’entreprise devrait cesser la surveillance jusqu’au déploiement complet de tous les outils"]}},{"n":15,"answer":"D","section":{"en":"Measurement: how managers know operations are working","fr":"Mesure : comment les gestionnaires savent que les opérations fonctionnent"},"q":{"en":"Which of the following is an example of a risk-linked outcome metric rather than an efficiency metric?","fr":"Lequel des exemples suivants est une mesure de résultat liée au risque plutôt qu’une mesure d’efficience?"},"options":{"en":["Mean time to triage alerts","Analyst workload per shift","Ticket ageing in the alert queue","Reduction in residual risk for priority scenarios"],"fr":["Le délai moyen de triage des alertes","La charge de travail des analystes par quart","L’âge des billets dans la file d’alertes","La réduction du risque résiduel des scénarios prioritaires"]}},{"n":16,"answer":"B","section":{"en":"Measurement: how managers know operations are working","fr":"Mesure : comment les gestionnaires savent que les opérations fonctionnent"},"q":{"en":"Which of these is a leading indicator in the chapter's sense?","fr":"Lequel des éléments suivants est un indicateur avancé au sens du chapitre?"},"options":{"en":["The number of confirmed breaches reported during the last quarter","A growing alert backlog and missing logs from critical systems","Financial losses recorded after a fraud event was discovered","Audit findings issued by internal audit after the annual review"],"fr":["Le nombre de violations de données confirmées au cours du dernier trimestre","Un arriéré d’alertes croissant et des journaux manquants pour des systèmes critiques","Les pertes financières enregistrées après la découverte d’une fraude","Les constatations émises par l’audit interne après la revue annuelle"]}},{"n":17,"answer":"D","section":{"en":"Measurement: how managers know operations are working","fr":"Mesure : comment les gestionnaires savent que les opérations fonctionnent"},"q":{"en":"After better alert tuning, a SOC's monthly alert volume drops by half. How should a manager interpret this, according to the chapter?","fr":"Après un meilleur réglage des alertes, le volume mensuel d’alertes d’un COS diminue de moitié. Selon le chapitre, comment un gestionnaire devrait-il interpréter ce résultat?"},"options":{"en":["As proof that the threat environment facing the company has improved","As a sign that monitoring staff numbers can be reduced immediately","As a performance grade showing the SOC is now twice as effective","With care, since it may reflect better tuning but could also mean reduced visibility"],"fr":["Comme la preuve que l’environnement de menaces auquel fait face l’entreprise s’est amélioré","Comme un signe que l’effectif de surveillance peut être réduit immédiatement","Comme une note de performance montrant que le COS est désormais deux fois plus efficace","Avec prudence, car il peut refléter un meilleur réglage, mais aussi une visibilité réduite"]}},{"n":18,"answer":"B","section":{"en":"Operational challenges: people, process, and complexity","fr":"Assurance et rapports externes : les rapports SOC et leur importance opérationnelle"},"q":{"en":"What is the key difference between a SOC 2 Type I report and a SOC 2 Type II report?","fr":"Quelle est la principale différence entre un rapport SOC 2 de type I et un rapport SOC 2 de type II?"},"options":{"en":["Type I covers financial reporting controls, while Type II covers security and availability controls","Type I assesses design at one point; Type II also tests operating effectiveness over time","Type I is issued in Canada; Type II is issued in the United States","Type I is for general use; Type II is a summary for wider audiences"],"fr":["Le type I couvre les contrôles de l’information financière; le type II, les contrôles de sécurité et de disponibilité","Le type I évalue la conception à un moment donné; le type II teste aussi l’efficacité opérationnelle dans le temps","Le type I est délivré au Canada; le type II est délivré aux États-Unis","Le type I est destiné à un usage général; le type II est un résumé pour un public plus large"]}},{"n":19,"answer":"C","section":{"en":"Operational challenges: people, process, and complexity","fr":"Défis opérationnels : personnes, processus et complexité"},"q":{"en":"A provider's SOC 2 Type II report carves out its cloud host and lists complementary user entity controls. What should the customer conclude?","fr":"Le rapport SOC 2 de type II d’un fournisseur exclut son hébergeur infonuagique (carve-out) et énumère des contrôles complémentaires chez l’entité utilisatrice. Que devrait conclure le client?"},"options":{"en":["The report covers the cloud host, so no further review is needed","The report is invalid and must be rejected outright by procurement","Assess the carved-out provider separately and perform the user entity controls itself","The customer can ignore the user entity controls if no exceptions were reported"],"fr":["Le rapport couvre l’hébergeur infonuagique; aucun examen supplémentaire n’est donc nécessaire","Le rapport est invalide et doit être rejeté d’emblée par l’approvisionnement","Il doit évaluer séparément le fournisseur exclu et exercer lui-même les contrôles chez l’entité utilisatrice","Il peut ignorer les contrôles chez l’entité utilisatrice si aucune exception n’a été signalée"]}},{"n":20,"answer":"A","section":{"en":"Operational challenges: people, process, and complexity","fr":"Défis opérationnels : personnes, processus et complexité"},"q":{"en":"In the Fleuve-Nord tabletop exercise, the provider detected the intrusion quickly but its call reached an outdated on-call number. Which lesson does this best illustrate?","fr":"Lors de l’exercice sur table de Fleuve-Nord, le fournisseur a détecté rapidement l’intrusion, mais son appel a abouti à un numéro de garde périmé. Quelle leçon cela illustre-t-il le mieux?"},"options":{"en":["Escalation paths are part of the control and need regular testing, including after hours","Detection speed is the only SOC metric that really matters to management","Hybrid SOCs should be abandoned after any failed tabletop exercise","Tier 1 analysts should be allowed to contain dispatch servers on their own"],"fr":["Les voies de remontée font partie du contrôle et doivent être testées régulièrement, y compris hors des heures de bureau","La rapidité de détection est la seule mesure du COS qui compte vraiment pour la direction","Les COS hybrides devraient être abandonnés après tout exercice sur table raté","Les analystes de niveau 1 devraient pouvoir confiner seuls les serveurs de répartition"]}}]},{"n":8,"title":{"en":"Chapter 8: Cybersecurity Detection, Orchestration, Vulnerabilities, Response, and Testing","fr":"Chapitre 8 : Détection, orchestration, vulnérabilités, intervention et tests en cybersécurité"},"questions":[{"n":1,"answer":"C","section":{"en":"Security information and event management (SIEM)","fr":"Gestion des informations et des événements de sécurité (SIEM)"},"q":{"en":"Why do SIEM deployments depend on reliable time synchronization, typically through the Network Time Protocol?","fr":"Pourquoi les déploiements de SIEM dépendent-ils d’une synchronisation fiable de l’heure, habituellement au moyen du protocole NTP (Network Time Protocol)?"},"options":{"en":["Because licensing costs are calculated by the hour of ingestion","Because synchronized clocks encrypt log data in transit","Because without a common timeline events cannot be ordered and correlated reliably","Because regulators require all logs to carry the same time zone"],"fr":["Parce que les coûts de licence sont calculés selon l’heure d’ingestion","Parce que des horloges synchronisées chiffrent les journaux en transit","Parce que sans chronologie commune, les événements ne peuvent pas être ordonnés et corrélés de façon fiable","Parce que les organismes de réglementation exigent que tous les journaux portent le même fuseau horaire"]}},{"n":2,"answer":"A","section":{"en":"Security information and event management (SIEM)","fr":"Gestion des informations et des événements de sécurité (SIEM)"},"q":{"en":"According to the chapter, why are false positives in a SIEM more than a minor inconvenience?","fr":"Selon le chapitre, pourquoi les faux positifs d’un SIEM sont-ils plus qu’un inconvénient mineur?"},"options":{"en":["They raise alert fatigue, weaken response quality, and hide subtle but important signals","They breach most data-protection laws in force in Canada and Europe","They prevent the SIEM from storing or searching logs over time","They automatically trigger containment actions on critical production systems without approval"],"fr":["Ils accroissent la fatigue liée aux alertes, affaiblissent la qualité de l’intervention et masquent des signaux subtils, mais importants","Ils contreviennent à la plupart des lois sur la protection des données en vigueur au Canada et en Europe","Ils empêchent le SIEM de stocker les journaux ou d’y faire des recherches dans le temps","Ils déclenchent automatiquement des actions de confinement sur des systèmes de production critiques sans approbation"]}},{"n":3,"answer":"D","section":{"en":"Security information and event management (SIEM)","fr":"Gestion des informations et des événements de sécurité (SIEM)"},"q":{"en":"With SIEM, XDR, security data lakes, and MDR converging, what does the chapter say managers should focus on?","fr":"Alors que le SIEM, le XDR, les lacs de données de sécurité et le MDR convergent, sur quoi le chapitre dit-il que les gestionnaires devraient se concentrer?"},"options":{"en":["Choosing the product category with the newest and most popular market label","Buying separate SIEM and SOAR products from different vendors to avoid lock-in","Avoiding any platform that includes generative-AI assistants or automated responses","Telemetry coverage, ownership of detection content, cost scaling, approval rules, and data portability"],"fr":["Choisir la catégorie de produits portant l’étiquette commerciale la plus récente et la plus populaire","Acheter des produits SIEM et SOAR distincts auprès de fournisseurs différents pour éviter la dépendance","Éviter toute plateforme comportant des assistants d’IA générative ou des interventions automatisées","La couverture de la télémétrie, la propriété du contenu de détection, l’évolution des coûts, les règles d’approbation et la portabilité des données"]}},{"n":4,"answer":"B","section":{"en":"Physical security as part of operational security","fr":"La sécurité physique, composante de la sécurité opérationnelle"},"q":{"en":"Which statement best describes the governance role of a SOAR playbook?","fr":"Quel énoncé décrit le mieux le rôle de gouvernance d’un guide d’intervention SOAR?"},"options":{"en":["It replaces the need for a dedicated, permanent incident response team","It specifies which actions run automatically and which need human or legal approval","It guarantees that every incident is contained within one hour of detection","It records only technical steps and leaves out communications and evidence"],"fr":["Il remplace le besoin d’une équipe permanente et dédiée d’intervention en cas d’incident","Il précise quelles actions s’exécutent automatiquement et lesquelles exigent une approbation humaine ou juridique","Il garantit que chaque incident est confiné dans l’heure qui suit sa détection","Il ne consigne que les étapes techniques et laisse de côté les communications et les éléments probants"]}},{"n":5,"answer":"A","section":{"en":"Security orchestration, automation, and response (SOAR)","fr":"Orchestration, automatisation et intervention de sécurité (SOAR)"},"q":{"en":"Why does the chapter compare playbooks to checklists used in high-reliability environments?","fr":"Pourquoi le chapitre compare-t-il les guides d’intervention aux listes de vérification utilisées dans les environnements à haute fiabilité?"},"options":{"en":["Because structured procedures reduce error under pressure, even for experienced personnel","Because cybersecurity professionals generally lack expertise","Because checklists remove the need to rehearse or update procedures","Because regulators prohibit improvisation in all circumstances"],"fr":["Parce que des procédures structurées réduisent l’erreur sous pression, même pour du personnel expérimenté","Parce que les professionnels de la cybersécurité manquent généralement d’expertise","Parce que les listes de vérification éliminent le besoin de répéter ou de mettre à jour les procédures","Parce que les organismes de réglementation interdisent l’improvisation en toutes circonstances"]}},{"n":6,"answer":"D","section":{"en":"Security information and event management (SIEM)","fr":"Le SIEM par rapport au SOAR, et la logique de l’intégration"},"q":{"en":"A SIEM alerts on an account signing in from an unusual country and accessing sensitive systems. What would typically be the SOAR layer's contribution?","fr":"Un SIEM émet une alerte pour un compte qui se connecte depuis un pays inhabituel et accède à des systèmes sensibles. Quelle serait normalement la contribution de la couche SOAR?"},"options":{"en":["Collecting and normalizing the authentication, VPN, and cloud logs from all sources","Writing the original correlation rule that detected the anomalous sign-in pattern","Synchronizing clocks across the identity, VPN, and cloud systems involved","Enriching the alert, opening a case, preserving logs, and running an approved containment step"],"fr":["Collecter et normaliser les journaux d’authentification, du RPV et du nuage de toutes les sources","Rédiger la règle de corrélation initiale qui a détecté le schéma de connexion anormal","Synchroniser les horloges des systèmes d’identité, du RPV et du nuage concernés","Enrichir l’alerte, ouvrir un dossier, préserver les journaux et exécuter une étape de confinement approuvée"]}},{"n":7,"answer":"C","section":{"en":"Implementing monitoring and response platforms in practice","fr":"Mettre en œuvre des plateformes de surveillance et d’intervention en pratique"},"q":{"en":"Why does the chapter call a proof of concept a risk control rather than an optional step?","fr":"Pourquoi le chapitre qualifie-t-il la preuve de concept de contrôle du risque plutôt que d’étape facultative?"},"options":{"en":["It lets the vendor define the organization's requirements, scope, and success criteria","It removes the need for phased deployment and later tuning of the platform","It tests ingestion, detection, false positives, and integration in the real environment","It guarantees the lowest licensing cost among shortlisted vendors"],"fr":["Elle permet au fournisseur de définir les exigences, la portée et les critères de réussite de l’organisation","Elle élimine le besoin d’un déploiement par étapes et d’un réglage ultérieur de la plateforme","Elle teste l’ingestion, la détection, les faux positifs et l’intégration dans l’environnement réel","Elle garantit le coût de licence le plus bas parmi les fournisseurs présélectionnés"]}},{"n":8,"answer":"B","section":{"en":"Vulnerability management as an operational discipline","fr":"La gestion des vulnérabilités en tant que discipline opérationnelle"},"q":{"en":"Which of the following would the chapter classify as a systemic vulnerability?","fr":"Lequel des éléments suivants le chapitre classerait-il comme une vulnérabilité systémique?"},"options":{"en":["A missing operating system patch on a file server","Unclear ownership that allows known risks to remain unresolved","Staff susceptibility to convincing phishing emails sent to their inboxes","Default administrator credentials left unchanged on a network device"],"fr":["Un correctif de système d’exploitation manquant sur un serveur de fichiers","Une propriété floue qui laisse des risques connus sans résolution","La vulnérabilité du personnel à des courriels d’hameçonnage convaincants","Des identifiants d’administrateur par défaut laissés inchangés sur un appareil réseau"]}},{"n":9,"answer":"B","section":{"en":"Vulnerability management as an operational discipline","fr":"La gestion des vulnérabilités en tant que discipline opérationnelle"},"q":{"en":"What is the central goal of reducing the exposure window?","fr":"Quel est l’objectif central de la réduction de la fenêtre d’exposition?"},"options":{"en":["To make sure every system is scanned at least once per quarter","To reduce the time important assets remain exposed to vulnerabilities that could cause unacceptable consequences","To lower the total number of vulnerabilities reported by scanners each month","To ensure that every patch is applied within 24 hours of its release"],"fr":["S’assurer que chaque système est balayé au moins une fois par trimestre","Réduire la durée pendant laquelle les actifs importants restent exposés à des vulnérabilités aux conséquences inacceptables","Diminuer le nombre total de vulnérabilités signalées chaque mois par les scanneurs","Veiller à ce que chaque correctif soit appliqué dans les 24 heures suivant sa publication"]}},{"n":10,"answer":"C","section":{"en":"Vulnerability management as an operational discipline","fr":"La gestion des vulnérabilités en tant que discipline opérationnelle"},"q":{"en":"A critical-severity finding sits on an isolated test server; a high-severity finding sits on an Internet-facing system supporting an essential service. What does the chapter suggest?","fr":"Une constatation de gravité critique se trouve sur un serveur de test isolé; une constatation de gravité élevée, sur un système exposé à Internet qui soutient un service essentiel. Que suggère le chapitre?"},"options":{"en":["Fix the critical finding first, because technical severity always determines priority","Treat both findings identically, so that prioritization stays free of bias","The high-severity finding on the exposed essential system may be more urgent","Defer both findings until the next quarterly scan confirms them"],"fr":["Corriger d’abord la constatation critique, parce que la gravité technique détermine toujours la priorité","Traiter les deux constatations de façon identique, pour que la priorisation reste exempte de biais","La constatation de gravité élevée sur le système essentiel exposé peut être plus urgente","Reporter les deux constatations jusqu’à ce que le prochain balayage trimestriel les confirme"]}},{"n":11,"answer":"A","section":{"en":"Vulnerability management as an operational discipline","fr":"La gestion des vulnérabilités en tant que discipline opérationnelle"},"q":{"en":"A student wants to practise with Greenbone Community Edition. Which use is consistent with the chapter's guidance?","fr":"Un étudiant veut s’exercer avec Greenbone Community Edition. Quelle utilisation est conforme aux indications du chapitre?"},"options":{"en":["Scanning intentionally vulnerable machines in an isolated lab under the student's control","Scanning the university network to find real weaknesses for the IT team","Scanning a part-time employer's servers over a weekend","Scanning public websites without causing any damage"],"fr":["Balayer des machines volontairement vulnérables dans un laboratoire isolé qu’il contrôle","Balayer le réseau de l’université pour trouver de vraies faiblesses à l’intention de l’équipe des TI","Balayer les serveurs de son employeur à temps partiel pendant une fin de semaine","Balayer des sites Web publics sans causer de dommages"]}},{"n":12,"answer":"D","section":{"en":"Vulnerability intelligence data sources: CVE, CWE, CVSS, and advisories","fr":"Sources de renseignement sur les vulnérabilités : CVE, CWE, CVSS et avis"},"q":{"en":"In CVSS v4.0, what does a score labelled CVSS-BTE indicate?","fr":"Dans le CVSS v4.0, qu’indique un score étiqueté CVSS-BTE?"},"options":{"en":["A Base score only, as published by the vendor","A score calculated with an older CVSS v3.1 formula","A probability of exploitation in the next 30 days","A score combining Base, Threat, and Environmental metrics"],"fr":["Un score de base seulement, tel que publié par le fournisseur","Un score calculé avec une ancienne formule du CVSS v3.1","Une probabilité d’exploitation au cours des 30 prochains jours","Un score combinant les métriques de base, de menace et environnementales"]}},{"n":13,"answer":"C","section":{"en":"Vulnerability intelligence data sources: CVE, CWE, CVSS, and advisories","fr":"Sources de renseignement sur les vulnérabilités : CVE, CWE, CVSS et avis"},"q":{"en":"Which pairing of source and question answered is correct?","fr":"Quelle association entre une source et la question à laquelle elle répond est correcte?"},"options":{"en":["CWE: Is this CVE being actively exploited against organizations this week?","KEV: What class of software weakness caused this particular flaw?","EPSS: How likely is exploitation of this CVE in the next 30 days?","CVE: How urgent is this flaw for our own mission and services?"],"fr":["CWE : cette CVE est-elle activement exploitée contre des organisations cette semaine?","KEV : quelle catégorie de faiblesse logicielle a causé cette faille précise?","EPSS : quelle est la probabilité d’exploitation de cette CVE au cours des 30 prochains jours?","CVE : quelle est l’urgence de cette faille pour notre propre mission et nos services?"]}},{"n":14,"answer":"A","section":{"en":"Vulnerability intelligence data sources: CVE, CWE, CVSS, and advisories","fr":"Sources de renseignement sur les vulnérabilités : CVE, CWE, CVSS et avis"},"q":{"en":"What lesson does the chapter draw from the 2025 difficulties with the CVE Program contract and the NVD backlog?","fr":"Quelle leçon le chapitre tire-t-il des difficultés de 2025 liées au contrat du programme CVE et à l’arriéré de la NVD?"},"options":{"en":["Know which public feeds you rely on and keep a fallback if one fails","Stop using CVE identifiers entirely and rely on an internal naming scheme","Treat all public vulnerability data as too unreliable to use for any purpose","Switch exclusively to the European Vulnerability Database for all prioritization decisions"],"fr":["Savoir de quelles sources publiques on dépend et prévoir une solution de rechange si l’une fait défaut","Cesser complètement d’utiliser les identifiants CVE et adopter une nomenclature interne","Considérer toutes les données publiques sur les vulnérabilités comme trop peu fiables pour quelque usage que ce soit","Passer exclusivement à la base européenne de données sur les vulnérabilités pour toutes les décisions de priorisation"]}},{"n":15,"answer":"B","section":{"en":"Chapter summary","fr":"La gestion des vulnérabilités en tant que discipline opérationnelle"},"q":{"en":"Which statement best reflects the chapter's view of threat intelligence?","fr":"Quel énoncé reflète le mieux le point de vue du chapitre sur le renseignement sur les menaces?"},"options":{"en":["Subscribing to more intelligence feeds always produces better detection outcomes for the SOC","It is valuable only when relevant, reliable, timely, and actionable for the organization","Threat intelligence should replace routine vulnerability scanning and patch reporting","It becomes useful only after an incident has been formally declared"],"fr":["S’abonner à davantage de flux de renseignement produit toujours de meilleurs résultats de détection pour le COS","Il n’a de valeur que s’il est pertinent, fiable, opportun et exploitable pour l’organisation","Le renseignement sur les menaces devrait remplacer le balayage courant des vulnérabilités et les rapports sur les correctifs","Il ne devient utile qu’après la déclaration officielle d’un incident"]}},{"n":16,"answer":"D","section":{"en":"Incident response operations: teams, lifecycle, and resilience interfaces","fr":"Opérations d’intervention en cas d’incident : équipes, cycle de vie et interfaces avec la résilience"},"q":{"en":"Following NIST SP 800-61 Rev. 3, which situation is an incident rather than only an alert?","fr":"Selon la publication NIST SP 800-61 Rev. 3, quelle situation constitue un incident plutôt qu’une simple alerte?"},"options":{"en":["A single failed login attempt on a user account","A routine, scheduled software update applied to a server","Several failed logins, then a successful one from an unusual location, not yet investigated","Investigation confirms the account was compromised and sensitive systems were accessed"],"fr":["Une seule tentative de connexion échouée sur un compte d’utilisateur","Une mise à jour logicielle courante et planifiée appliquée à un serveur","Plusieurs connexions échouées, puis une réussie depuis un lieu inhabituel, pas encore analysée","L’enquête confirme que le compte a été compromis et que des systèmes sensibles ont été consultés"]}},{"n":17,"answer":"D","section":{"en":"Incident response operations: teams, lifecycle, and resilience interfaces","fr":"Opérations d’intervention en cas d’incident : équipes, cycle de vie et interfaces avec la résilience"},"q":{"en":"A ransomware incident is likely to keep a payment system unavailable beyond its acceptable interruption window. What should the organization most likely do?","fr":"Un incident de rançongiciel risque de rendre un système de paiement indisponible au-delà de sa fenêtre d’interruption acceptable. Que devrait le plus probablement faire l’organisation?"},"options":{"en":["Keep the response purely technical until eradication is complete","Wait until the maximum tolerable downtime is exceeded before escalating","Close the incident and open a disaster recovery ticket only","Activate business continuity procedures to maintain essential services"],"fr":["Garder l’intervention purement technique jusqu’à la fin de l’éradication","Attendre que le temps d’arrêt maximal tolérable soit dépassé avant de remonter","Fermer l’incident et ouvrir seulement un billet de reprise après sinistre","Activer les procédures de continuité des activités pour maintenir les services essentiels"]}},{"n":18,"answer":"B","section":{"en":"Incident response operations: teams, lifecycle, and resilience interfaces","fr":"Opérations d’intervention en cas d’incident : équipes, cycle de vie et interfaces avec la résilience"},"q":{"en":"Why should the war room model be defined before a crisis?","fr":"Pourquoi le modèle de la salle de crise devrait-il être défini avant une crise?"},"options":{"en":["Because only technical staff are allowed to attend during a live incident","Because pre-defined roles, cadence, channels, and approval rules prevent teams working from different facts","Because war rooms must always be physical rooms located at company headquarters","Because it allows executives to stay out of decisions during serious incidents"],"fr":["Parce que seul le personnel technique peut y participer pendant un incident en cours","Parce que des rôles, une cadence, des canaux et des règles d’approbation définis d’avance évitent que les équipes travaillent à partir de faits différents","Parce que la salle de crise doit toujours être une pièce physique située au siège social","Parce que cela permet à la haute direction de rester à l’écart des décisions lors d’incidents graves"]}},{"n":19,"answer":"C","section":{"en":"Incident response operations: teams, lifecycle, and resilience interfaces","fr":"Opérations d’intervention en cas d’incident : équipes, cycle de vie et interfaces avec la résilience"},"q":{"en":"In the incident response lifecycle, which activity belongs to eradication rather than containment?","fr":"Dans le cycle de vie de l’intervention en cas d’incident, quelle activité relève de l’éradication plutôt que du confinement?"},"options":{"en":["Isolating an infected system from the network","Temporarily disabling a suspicious account","Closing the exploited vulnerability and rebuilding compromised systems","Blocking a malicious indicator at the firewall"],"fr":["Isoler du réseau un système infecté","Désactiver temporairement un compte suspect","Fermer la vulnérabilité exploitée et reconstruire les systèmes compromis","Bloquer un indicateur malveillant au pare-feu"]}},{"n":20,"answer":"A","section":{"en":"Penetration testing: structured adversarial simulation","fr":"Les tests d’intrusion : une simulation structurée d’activité adverse"},"q":{"en":"An organization wants to know whether its SOC would detect a realistic intrusion without warning. Which test design fits best, and what safeguard is essential?","fr":"Une organisation veut savoir si son COS détecterait une intrusion réaliste sans avertissement. Quelle conception de test convient le mieux, et quelle mesure de protection est essentielle?"},"options":{"en":["A double-blind test, with a few trusted senior stakeholders keeping oversight","A white-box test, with the SOC briefed in advance","A black-box external scan, with no written authorization needed","A vulnerability assessment, with results shared only with the vendor"],"fr":["Un test à double insu, sous la supervision de quelques membres de la haute direction de confiance","Un test en boîte blanche, avec le COS informé à l’avance","Un balayage externe en boîte noire, sans autorisation écrite nécessaire","Une évaluation des vulnérabilités, dont les résultats ne sont communiqués qu’au fournisseur"]}}]},{"n":9,"title":{"en":"Chapter 9: Cybersecurity Control Frameworks","fr":"Chapitre 9 : Cadres de contrôles de cybersécurité"},"questions":[{"n":1,"answer":"D","section":{"en":"What is a standard?","fr":"Résumé du chapitre"},"q":{"en":"According to ISO/IEC Guide 2:2004, which feature is essential to a standard?","fr":"Selon le Guide ISO/IEC 2:2004, quelle caractéristique est essentielle à une norme?"},"options":{"en":["It is published by a government agency and enforced by law","It is adopted by the largest vendors in a market","It is a flexible model that each organization adapts freely","It is established by consensus and approved by a recognized body"],"fr":["Elle est publiée par un organisme gouvernemental et imposée par la loi","Elle est adoptée par les plus grands fournisseurs d’un marché","C’est un modèle souple que chaque organisation adapte librement","Elle est établie par consensus et approuvée par un organisme reconnu"]}},{"n":2,"answer":"B","section":{"en":"What is a framework?","fr":"Qu’est-ce qu’un cadre?"},"q":{"en":"Which question is a framework, rather than a standard, most likely to help a manager answer?","fr":"À quelle question un cadre, plutôt qu’une norme, est-il le plus susceptible d’aider un gestionnaire à répondre?"},"options":{"en":["What exact requirements must we meet to be certified?","How should we organize our thinking, responsibilities, and activities?","Which accredited body may audit our management system?","What is the legal penalty for non-compliance?"],"fr":["Quelles exigences précises devons-nous satisfaire pour être certifiés?","Comment devrions-nous organiser notre réflexion, nos responsabilités et nos activités?","Quel organisme accrédité peut auditer notre système de gestion?","Quelle est la sanction juridique en cas de non-conformité?"]}},{"n":3,"answer":"A","section":{"en":"Categories of standards and frameworks","fr":"Catégories de normes et de cadres"},"q":{"en":"A dominant cloud platform shapes how an organization must configure identity and logging, though no standards body approved it. How should governance treat it?","fr":"Une plateforme infonuagique dominante détermine la façon dont une organisation doit configurer l’identité et la journalisation, sans qu’aucun organisme de normalisation l’ait approuvée. Comment la gouvernance devrait-elle la traiter?"},"options":{"en":["As a constraint to assess for security, concentration risk, and needed compensating controls","As evidence of good governance because it is so widely adopted","As irrelevant, since only consensus standards carry real authority","As a binding legal requirement equivalent to a regulation or statute"],"fr":["Comme une contrainte à évaluer quant à la sécurité, au risque de concentration et aux contrôles compensatoires requis","Comme une preuve de bonne gouvernance, puisqu’elle est si largement adoptée","Comme non pertinente, puisque seules les normes consensuelles ont une réelle autorité","Comme une exigence juridique contraignante équivalant à un règlement ou à une loi"]}},{"n":4,"answer":"C","section":{"en":"Categories of standards and frameworks","fr":"Catégories de normes et de cadres"},"q":{"en":"Why does the chapter describe consensus-based standards as deliberately conservative?","fr":"Pourquoi le chapitre décrit-il les normes consensuelles comme délibérément prudentes?"},"options":{"en":["They are written only by government officials and regulators, not by industry","They forbid organizations from adopting any new technology until it is standardized","They must be acceptable to many stakeholders, so they codify broadly agreed, stable practices","They are revised every year so that they follow the latest research"],"fr":["Elles sont rédigées uniquement par des fonctionnaires et des organismes de réglementation, sans l’industrie","Elles interdisent aux organisations d’adopter une nouvelle technologie tant qu’elle n’est pas normalisée","Elles doivent être acceptables pour de nombreuses parties prenantes; elles codifient donc des pratiques stables et largement admises","Elles sont révisées chaque année afin de suivre les recherches les plus récentes"]}},{"n":5,"answer":"B","section":{"en":"Categories of standards and frameworks","fr":"Catégories de normes et de cadres"},"q":{"en":"A Canadian supplier bids on certain Government of Canada defence contracts. Which requirement does the chapter say may apply?","fr":"Un fournisseur canadien soumissionne pour certains contrats de défense du gouvernement du Canada. Quelle exigence peut s’appliquer, selon le chapitre?"},"options":{"en":["ISO/IEC 27001 certification of the entire enterprise","Level 1 certification against ITSP.10.171 under the CPCSC","A COBIT 2019 organizational certificate","A SOC 3 report on its cybersecurity program"],"fr":["La certification ISO/IEC 27001 de l’ensemble de l’entreprise","Une certification de niveau 1 selon l’ITSP.10.171 dans le cadre du PCCC","Un certificat organisationnel COBIT 2019","Un rapport SOC 3 sur son programme de cybersécurité"]}},{"n":6,"answer":"C","section":{"en":"ISO/IEC 27001:2022 and the information security management system (ISMS)","fr":"ISO/IEC 27001:2022 et le système de gestion de la sécurité de l’information (SGSI)"},"q":{"en":"In the PDCA reading of ISO/IEC 27001:2022, which clause corresponds broadly to Check?","fr":"Dans la lecture PDCA de la norme ISO/IEC 27001:2022, quel article correspond globalement à « vérifier »?"},"options":{"en":["Clause 6, Planning","Clause 8, Operation","Clause 9, Performance evaluation","Clause 10, Improvement"],"fr":["L’article 6, Planification","L’article 8, Fonctionnement","L’article 9, Évaluation des performances","L’article 10, Amélioration"]}},{"n":7,"answer":"D","section":{"en":"ISO/IEC 27001:2022 and the information security management system (ISMS)","fr":"ISO/IEC 27001:2022 et le système de gestion de la sécurité de l’information (SGSI)"},"q":{"en":"Why does the chapter call defining the ISMS scope under Clause 4 a major governance decision?","fr":"Pourquoi le chapitre qualifie-t-il la définition de la portée du SGSI, à l’article 4, de décision de gouvernance majeure?"},"options":{"en":["Because the scope alone determines the fee charged by the certification body","Because ISO/IEC 27001 requires the whole enterprise to be in scope from the start","Because scope can be changed freely at any time after the certificate is issued","Because a narrow scope is simpler but can give false assurance by excluding critical dependencies"],"fr":["Parce que la portée détermine à elle seule les honoraires de l’organisme de certification","Parce que l’ISO/IEC 27001 exige que toute l’entreprise soit visée dès le départ","Parce que la portée peut être modifiée librement en tout temps après la délivrance du certificat","Parce qu’une portée étroite est plus simple, mais peut donner une fausse assurance en excluant des dépendances critiques"]}},{"n":8,"answer":"A","section":{"en":"ISO/IEC 27001:2022 and the information security management system (ISMS)","fr":"Résumé du chapitre"},"q":{"en":"What does the Statement of Applicability require an organization to do?","fr":"Qu’est-ce que la déclaration d’applicabilité exige d’une organisation?"},"options":{"en":["Identify necessary controls, their status, and justify inclusion or exclusion of Annex A controls","Implement every one of the Annex A controls without any exception","List only the controls that failed during the most recent internal audit","Replace the risk assessment with a simpler checklist of applicable controls"],"fr":["Déterminer les contrôles nécessaires, leur état et justifier l’inclusion ou l’exclusion des mesures de l’annexe A","Mettre en œuvre chacune des mesures de l’annexe A, sans aucune exception","Énumérer seulement les contrôles qui ont échoué lors du plus récent audit interne","Remplacer l’évaluation des risques par une liste de vérification plus simple des contrôles applicables"]}},{"n":9,"answer":"C","section":{"en":"ISO/IEC 27002:2022: The control catalogue","fr":"ISO/IEC 27002:2022 : Le catalogue de mesures"},"q":{"en":"ISO/IEC 27002:2022 groups its controls into themes of 37, 8, 14, and 34 controls. What total do they make, and how does it compare with the 2013 edition?","fr":"L’ISO/IEC 27002:2022 regroupe ses mesures en thèmes de 37, 8, 14 et 34 mesures. Quel total obtient-on, et comment se compare-t-il à l’édition 2013?"},"options":{"en":["93 controls, up from 81 in the 2013 edition","114 controls, unchanged from the 2013 edition","93 controls, consolidated from 114, with 11 new","103 controls, consolidated from 114, with 4 new"],"fr":["93 mesures, en hausse par rapport aux 81 de l’édition 2013","114 mesures, inchangées depuis l’édition 2013","93 mesures, regroupant les 114 précédentes, dont 11 nouvelles","103 mesures, regroupant les 114 précédentes, dont 4 nouvelles"]}},{"n":10,"answer":"A","section":{"en":"ISO/IEC 27002:2022: The control catalogue","fr":"ISO/IEC 27002:2022 : Le catalogue de mesures"},"q":{"en":"A manager wants to report which controls are preventive, detective, or corrective, and which support confidentiality, integrity, or availability. Which ISO/IEC 27002:2022 feature helps most?","fr":"Un gestionnaire veut indiquer quels contrôles sont préventifs, de détection ou correctifs, et lesquels soutiennent la confidentialité, l’intégrité ou la disponibilité. Quelle caractéristique de l’ISO/IEC 27002:2022 l’aide le plus?"},"options":{"en":["Control attributes","The four control themes","The certification scope","The climate-action amendment"],"fr":["Les attributs des mesures","Les quatre thèmes de mesures","La portée de certification","L’amendement sur l’action climatique"]}},{"n":11,"answer":"D","section":{"en":"Chapter summary","fr":"ISO/IEC 27005:2022 : Gestion des risques liés à la sécurité de l’information"},"q":{"en":"Which statement about ISO/IEC 27005:2022 is accurate?","fr":"Quel énoncé au sujet de la norme ISO/IEC 27005:2022 est exact?"},"options":{"en":["It prescribes a mandatory risk matrix and scoring formula","It replaces ISO/IEC 27001 as the certifiable standard","It applies only to quantitative, monetary risk assessment","It gives process guidance and vocabulary without prescribing one method"],"fr":["Elle prescrit une matrice des risques et une formule de cotation obligatoires","Elle remplace l’ISO/IEC 27001 comme norme certifiable","Elle ne s’applique qu’à l’évaluation quantitative et monétaire des risques","Elle fournit des lignes directrices de processus et un vocabulaire sans prescrire de méthode unique"]}},{"n":12,"answer":"B","section":{"en":"Implications for business technology managers","fr":"Conséquences pour les gestionnaires des technologies d’affaires"},"q":{"en":"A system has run in production for two years with known residual risk that no one formally accepted. Which principle from ISO/IEC 27005 and the NIST RMF does this violate?","fr":"Un système est en production depuis deux ans avec un risque résiduel connu que personne n’a accepté formellement. Quel principe de l’ISO/IEC 27005 et du RMF du NIST cela enfreint-il?"},"options":{"en":["That residual risks must always be transferred to an insurer before go-live","That an accountable owner should accept residual risk deliberately, with evidence and periodic review","That all controls in a baseline must be implemented before production","That every risk assessment must be repeated each month by the security team"],"fr":["Que les risques résiduels doivent toujours être transférés à un assureur avant la mise en service","Qu’un responsable imputable devrait accepter le risque résiduel délibérément, avec des éléments probants et une revue périodique","Que tous les contrôles d’une base de référence doivent être mis en œuvre avant la production","Que chaque évaluation des risques doit être refaite chaque mois par l’équipe de sécurité"]}},{"n":13,"answer":"A","section":{"en":"The NIST cybersecurity ecosystem","fr":"L’écosystème de cybersécurité du NIST"},"q":{"en":"What is the relationship between NIST SP 800-53 Rev. 5 and SP 800-53B?","fr":"Quelle est la relation entre les publications NIST SP 800-53 Rev. 5 et SP 800-53B?"},"options":{"en":["SP 800-53 is the catalogue; SP 800-53B gives low, moderate, high, and privacy baselines","SP 800-53B replaces SP 800-53 as NIST's current, complete control catalogue","SP 800-53 covers privacy only; SP 800-53B covers security controls only","SP 800-53B is the assessment procedure used to test SP 800-53 controls"],"fr":["La SP 800-53 est le catalogue; la SP 800-53B fournit les bases de référence faible, modérée, élevée et de vie privée","La SP 800-53B remplace la SP 800-53 comme catalogue de contrôles actuel et complet du NIST","La SP 800-53 couvre seulement la vie privée; la SP 800-53B, seulement les contrôles de sécurité","La SP 800-53B est la procédure d’évaluation utilisée pour tester les contrôles de la SP 800-53"]}},{"n":14,"answer":"B","section":{"en":"The NIST cybersecurity ecosystem","fr":"L’écosystème de cybersécurité du NIST"},"q":{"en":"Which step of the NIST Risk Management Framework is a formal, risk-based decision by an accountable official?","fr":"Quelle étape du cadre de gestion des risques du NIST est une décision formelle, fondée sur le risque, prise par une personne responsable imputable?"},"options":{"en":["Categorize","Authorize","Implement","Monitor"],"fr":["Catégoriser","Autoriser","Mettre en œuvre","Surveiller"]}},{"n":15,"answer":"C","section":{"en":"Implications for business technology managers","fr":"Combiner les cadres en pratique"},"q":{"en":"A board wants to see where cybersecurity stands today, where it should be, and what closing the gap will cost. Which NIST CSF 2.0 concept best supports this?","fr":"Un conseil d’administration veut voir où en est la cybersécurité aujourd’hui, où elle devrait être et ce que coûtera la réduction de l’écart. Quelle notion du NIST CSF 2.0 soutient le mieux cette démarche?"},"options":{"en":["The 20 control families of SP 800-53","Implementation tiers used as a certification score","Current and target Profiles","FIPS 199 impact categorization"],"fr":["Les 20 familles de contrôles de la SP 800-53","Les niveaux de mise en œuvre utilisés comme score de certification","Les profils actuel et cible","La catégorisation de l’impact selon la FIPS 199"]}},{"n":16,"answer":"D","section":{"en":"COBIT 2019: Enterprise governance of information and technology","fr":"COBIT 2019 : Gouvernance d’entreprise de l’information et de la technologie"},"q":{"en":"Under COBIT 2019, which activity belongs to governance rather than management?","fr":"Selon COBIT 2019, quelle activité relève de la gouvernance plutôt que de la gestion?"},"options":{"en":["Building and running the organization's security services","Implementing configuration baselines on production servers","Planning and staffing a vulnerability remediation project","Evaluating stakeholder needs, setting priorities, and monitoring performance"],"fr":["Bâtir et exploiter les services de sécurité de l’organisation","Mettre en œuvre des configurations de référence sur les serveurs de production","Planifier et doter en personnel un projet de correction des vulnérabilités","Évaluer les besoins des parties prenantes, fixer les priorités et surveiller la performance"]}},{"n":17,"answer":"A","section":{"en":"COBIT 2019: Enterprise governance of information and technology","fr":"COBIT 2019 : Gouvernance d’entreprise de l’information et de la technologie"},"q":{"en":"Which COBIT 2019 objective would a board's risk committee most likely use to set risk-related expectations?","fr":"Quel objectif de COBIT 2019 le comité des risques d’un conseil d’administration utiliserait-il le plus probablement pour fixer ses attentes en matière de risque?"},"options":{"en":["EDM03 Ensured Risk Optimization","APO13 Managed Security","DSS05 Managed Security Services","MEA04 Managed Assurance"],"fr":["EDM03 Assurer l’optimisation des risques","APO13 Gérer la sécurité","DSS05 Gérer les services de sécurité","MEA04 Gérer l’assurance"]}},{"n":18,"answer":"C","section":{"en":"COBIT 2019: Enterprise governance of information and technology","fr":"COBIT 2019 : Gouvernance d’entreprise de l’information et de la technologie"},"q":{"en":"A vulnerability process exists on paper, but asset ownership is unclear, exceptions are not reviewed, and the board never sees unresolved exposure. Which COBIT concept best explains why it fails?","fr":"Un processus de gestion des vulnérabilités existe sur papier, mais la propriété des actifs est floue, les exceptions ne sont pas revues et le conseil ne voit jamais l’exposition non résolue. Quelle notion de COBIT explique le mieux cet échec?"},"options":{"en":["The goals cascade","The certification scope","The seven interacting components of a governance system","The five domains of the Core Model"],"fr":["La cascade des objectifs","La portée de certification","Les sept composantes interdépendantes d’un système de gouvernance","Les cinq domaines du modèle de base"]}},{"n":19,"answer":"D","section":{"en":"COBIT 2019: Enterprise governance of information and technology","fr":"COBIT 2019 : Gouvernance d’entreprise de l’information et de la technologie"},"q":{"en":"An organization sets COBIT capability target level 4 for risk management and level 2 for an internal administrative process. How does the chapter view this?","fr":"Une organisation fixe un niveau de capacité cible COBIT de 4 pour la gestion des risques et de 2 pour un processus administratif interne. Comment le chapitre voit-il cela?"},"options":{"en":["As non-compliant, since COBIT requires every objective to reach level 5","As inappropriate, because capability targets must be uniform across all objectives","As irrelevant, since COBIT 2019 does not define any capability scale","As appropriate if justified by enterprise goals, design factors, risk, and cost"],"fr":["Comme une non-conformité, puisque COBIT exige que chaque objectif atteigne le niveau 5","Comme inapproprié, parce que les capacités cibles doivent être uniformes pour tous les objectifs","Comme sans objet, puisque COBIT 2019 ne définit aucune échelle de capacité","Comme approprié s’il est justifié par les objectifs d’entreprise, les facteurs de conception, le risque et le coût"]}},{"n":20,"answer":"B","section":{"en":"Combining frameworks in practice","fr":"Combiner les cadres en pratique"},"q":{"en":"In the Haute-Côte scenario, why are mappings recorded as full, partial, or none, with the compliance function confirming regulatory expectations?","fr":"Dans la mise en situation de Haute-Côte, pourquoi les correspondances sont-elles consignées comme complètes, partielles ou nulles, la fonction conformité confirmant les attentes réglementaires?"},"options":{"en":["Because certification bodies require all mappings to be recorded as full","Because mappings are not equivalences, and regulators may expect evidence no safeguard produces","Because engineers are not permitted to read regulatory guidance documents","Because CIS safeguards always satisfy ISO controls completely and exactly"],"fr":["Parce que les organismes de certification exigent que toutes les correspondances soient consignées comme complètes","Parce que les correspondances ne sont pas des équivalences, et que les régulateurs peuvent attendre des preuves qu’aucune mesure ne produit","Parce que les ingénieurs ne sont pas autorisés à lire les documents d’orientation réglementaire","Parce que les mesures du CIS satisfont toujours entièrement et exactement les mesures ISO"]}}]},{"n":10,"title":{"en":"Chapter 10: Identity and Access Management","fr":"Chapitre 10 : Gestion des identités et des accès"},"questions":[{"n":1,"answer":"A","section":{"en":"IAM and PAM: definitions and the managerial boundary","fr":"GIA et GAP : définitions et frontière managériale"},"q":{"en":"According to the chapter, what is the most useful managerial distinction between IAM and PAM?","fr":"Selon le chapitre, quelle est la distinction managériale la plus utile entre la GIA et la GAP?"},"options":{"en":["IAM governs access across the organization, while PAM governs exceptional privileges within it","IAM governs employee accounts, while PAM governs all supplier and contractor accounts","IAM is a business process, while PAM is a purely technical function owned by IT","IAM covers cloud services, while PAM covers on-premises servers and network devices"],"fr":["La GIA encadre l’accès dans toute l’organisation, tandis que la GAP encadre les privilèges exceptionnels en son sein","La GIA encadre les comptes des employés, tandis que la GAP encadre tous les comptes des fournisseurs et des contractuels","La GIA est un processus d’affaires, tandis que la GAP est une fonction purement technique relevant des TI","La GIA couvre les services infonuagiques, tandis que la GAP couvre les serveurs et les appareils réseau sur place"]}},{"n":2,"answer":"B","section":{"en":"IAM and PAM: definitions and the managerial boundary","fr":"GIA et GAP : définitions et frontière managériale"},"q":{"en":"Why does the chapter describe privileged access as more than a stronger form of ordinary access?","fr":"Pourquoi le chapitre décrit-il l’accès privilégié comme davantage qu’une forme plus puissante d’accès ordinaire?"},"options":{"en":["It always requires hardware tokens that ordinary users are never issued","It is delegated organizational authority that can change the safeguards constraining other users","It is legally owned by the IT department rather than by business units","It is used only during emergencies and is otherwise disabled by default"],"fr":["Il exige toujours des jetons matériels qui ne sont jamais remis aux utilisateurs ordinaires","Il constitue une autorité organisationnelle déléguée qui peut modifier les mesures de protection imposées aux autres utilisateurs","Il appartient légalement au service des TI plutôt qu’aux unités d’affaires","Il n’est utilisé qu’en situation d’urgence et est autrement désactivé par défaut"]}},{"n":3,"answer":"C","section":{"en":"Why identity failures dominate the incident landscape","fr":"Pourquoi les défaillances liées à l’identité dominent le paysage des incidents"},"q":{"en":"Which of the following is one of the five structural reasons the chapter gives for identity failures dominating the incident landscape?","fr":"Laquelle des propositions suivantes fait partie des cinq raisons structurelles que donne le chapitre pour expliquer que les défaillances liées à l’identité dominent le paysage des incidents?"},"options":{"en":["Encryption algorithms protecting stored passwords are routinely broken by attackers","Firewalls cannot inspect traffic once users connect from remote locations","Permissions accumulate over time because removal receives less attention than granting","Identity platforms are rarely included in vendor support contracts"],"fr":["Les algorithmes de chiffrement qui protègent les mots de passe stockés sont couramment cassés par les attaquants","Les pare-feu ne peuvent pas inspecter le trafic une fois que les utilisateurs se connectent à distance","Les permissions s’accumulent avec le temps, car leur retrait reçoit moins d’attention que leur attribution","Les plateformes d’identité sont rarement incluses dans les contrats de soutien des fournisseurs"]}},{"n":4,"answer":"D","section":{"en":"IAM governance in practice: decision rights, operating model, and accountability","fr":"La gouvernance de la GIA dans la pratique : droits décisionnels, modèle opérationnel et imputabilité"},"q":{"en":"In the chapter's three-layer IAM operating model, which layer should judge whether a particular employee genuinely needs access to a business resource?","fr":"Dans le modèle opérationnel de GIA à trois niveaux du chapitre, quel niveau devrait juger si un employé a réellement besoin d’accéder à une ressource d’affaires?"},"options":{"en":["The central identity function, because it operates the identity platforms and workflows","Internal audit, because it provides independent assurance over access decisions","The help desk, because it receives and processes most access requests","Business ownership, because access is a business risk decision implemented through technology"],"fr":["La fonction centrale d’identité, parce qu’elle exploite les plateformes et les flux de travail d’identité","L’audit interne, parce qu’il fournit une assurance indépendante sur les décisions d’accès","Le centre d’assistance, parce qu’il reçoit et traite la plupart des demandes d’accès","Les responsables métier, parce que l’accès est une décision de risque d’affaires mise en œuvre par la technologie"]}},{"n":5,"answer":"D","section":{"en":"Identity lifecycle: the most underestimated control","fr":"Cycle de vie des identités : le contrôle le plus sous-estimé"},"q":{"en":"An analyst transfers from accounts payable to treasury. Under joiner–mover–leaver discipline, what should the role change trigger?","fr":"Une analyste passe des comptes fournisseurs à la trésorerie. Selon la rigueur du processus d’arrivées, de mutations et de départs, que devrait déclencher ce changement de rôle?"},"options":{"en":["Provisioning of treasury access while keeping prior access in case it is needed","A full account deletion and new identity, with no review of earlier approvals","No change until the next annual access certification campaign is completed","Provisioning of treasury access and removal of accounts-payable access no longer justified"],"fr":["L’attribution des accès à la trésorerie, en conservant les accès antérieurs au cas où ils seraient nécessaires","La suppression complète du compte et une nouvelle identité, sans revue des approbations antérieures","Aucun changement avant la fin de la prochaine campagne annuelle de certification des accès","L’attribution des accès à la trésorerie et le retrait des accès aux comptes fournisseurs qui ne sont plus justifiés"]}},{"n":6,"answer":"C","section":{"en":"Authentication strategy: MFA, phishing resistance, and conditional access","fr":"Stratégie d’authentification : AMF, résistance à l’hameçonnage et accès conditionnel"},"q":{"en":"Why does the chapter warn that push-based MFA approvals are not phishing-resistant?","fr":"Pourquoi le chapitre prévient-il que les approbations d’AMF par notification ne résistent pas à l’hameçonnage?"},"options":{"en":["Push notifications cannot be delivered to mobile devices outside the corporate network","Push approvals store the user's password in plain text on the mobile device","Attackers can send repeated requests until a user accepts one, a pattern called MFA fatigue","Push methods are not recognized by NIST SP 800-63-4 at any assurance level"],"fr":["Les notifications ne peuvent pas être livrées aux appareils mobiles hors du réseau de l’entreprise","Les approbations par notification stockent le mot de passe de l’utilisateur en clair sur l’appareil mobile","Les attaquants peuvent envoyer des demandes répétées jusqu’à ce que l’utilisateur en accepte une, un schéma appelé fatigue AMF","Les méthodes par notification ne sont reconnues à aucun niveau d’assurance par la publication NIST SP 800-63-4"]}},{"n":7,"answer":"B","section":{"en":"Authentication strategy: MFA, phishing resistance, and conditional access","fr":"Stratégie d’authentification : AMF, résistance à l’hameçonnage et accès conditionnel"},"q":{"en":"Under NIST SP 800-63-4 as described in the chapter, how are synced passkeys treated?","fr":"Selon la publication NIST SP 800-63-4 telle que décrite dans le chapitre, comment les clés d’accès synchronisées sont-elles traitées?"},"options":{"en":["Acceptable at AAL3 because they are phishing-resistant and convenient for users","Acceptable at AAL2 but not at AAL3, which needs a phishing-resistant, non-exportable authenticator","Not acceptable at any level because they can be copied between devices","Acceptable only for identity proofing, not for authentication or federation"],"fr":["Acceptables au niveau AAL3, parce qu’elles résistent à l’hameçonnage et sont pratiques pour les utilisateurs","Acceptables au niveau AAL2, mais pas au niveau AAL3, qui exige un authentifiant résistant à l’hameçonnage et non exportable","Inacceptables à tout niveau, parce qu’elles peuvent être copiées d’un appareil à l’autre","Acceptables uniquement pour la vérification d’identité, et non pour l’authentification ou la fédération"]}},{"n":8,"answer":"A","section":{"en":"Authentication strategy: MFA, phishing resistance, and conditional access","fr":"GAP : des contrôles « joyaux de la couronne » que les gestionnaires doivent exiger"},"q":{"en":"An organization deploys phishing-resistant keys for administrators, but the help desk resets accounts after a caller answers basic personal questions. What weakness does this illustrate?","fr":"Une organisation déploie des clés résistantes à l’hameçonnage pour ses administrateurs, mais le centre d’assistance réinitialise les comptes dès qu’un appelant répond à quelques questions personnelles simples. Quelle faiblesse cela illustre-t-il?"},"options":{"en":["Recovery has become an alternative path around strong authentication controls","Conditional access policies have been configured too strictly for administrators","Role explosion has made administrator roles too difficult to review","Federation has extended trust to an unmanaged external identity provider"],"fr":["La récupération est devenue une voie de contournement des contrôles d’authentification robustes","Les politiques d’accès conditionnel ont été configurées de façon trop stricte pour les administrateurs","L’explosion des rôles a rendu les rôles d’administrateur trop difficiles à réviser","La fédération a étendu la confiance à un fournisseur d’identité externe non géré"]}},{"n":9,"answer":"B","section":{"en":"Authorization models: role engineering, RBAC/ABAC, and access reviews","fr":"Modèles d’autorisation : ingénierie des rôles, RBAC/ABAC et revues des accès"},"q":{"en":"Which statement best describes the governance risk of role explosion in RBAC?","fr":"Quel énoncé décrit le mieux le risque de gouvernance que pose l’explosion des rôles dans le RBAC?"},"options":{"en":["Roles become so broad that every user ends up receiving administrator permissions by default","So many narrow roles exist that they are almost as hard to govern as permissions","Roles are replaced entirely by attributes, making access decisions unpredictable and hard to audit","Roles are deleted automatically whenever business processes change or the organization restructures"],"fr":["Les rôles deviennent si larges que chaque utilisateur finit par recevoir des permissions d’administrateur par défaut","Il existe tant de rôles étroits qu’ils sont presque aussi difficiles à encadrer que les permissions elles-mêmes","Les rôles sont entièrement remplacés par des attributs, ce qui rend les décisions d’accès imprévisibles et difficiles à auditer","Les rôles sont supprimés automatiquement chaque fois que les processus d’affaires changent ou que l’organisation se restructure"]}},{"n":10,"answer":"A","section":{"en":"Authorization models: role engineering, RBAC/ABAC, and access reviews","fr":"Modèles d’autorisation : ingénierie des rôles, RBAC/ABAC et revues des accès"},"q":{"en":"According to the chapter, what is the main governance concern with ABAC?","fr":"Selon le chapitre, quelle est la principale préoccupation de gouvernance liée à l’ABAC?"},"options":{"en":["Overlapping attributes and conditional policies can be hard to predict, test, and audit","It cannot use context such as device status, location, or authentication strength","It requires every user to be assigned to exactly one job role at all times","It is prohibited by ISO/IEC 27002:2022 for systems holding sensitive information"],"fr":["Les attributs qui se chevauchent et les politiques conditionnelles peuvent être difficiles à prévoir, à tester et à auditer","Il ne peut pas utiliser le contexte, comme l’état de l’appareil, l’emplacement ou la robustesse de l’authentification","Il exige que chaque utilisateur soit affecté en tout temps à un seul et unique rôle","Il est interdit par l’ISO/IEC 27002:2022 pour les systèmes contenant de l’information sensible"]}},{"n":11,"answer":"D","section":{"en":"Authorization models: role engineering, RBAC/ABAC, and access reviews","fr":"Modèles d’autorisation : ingénierie des rôles, RBAC/ABAC et revues des accès"},"q":{"en":"A business unit reports 100 percent completion of its quarterly access certifications, yet almost no access was removed. What does the chapter suggest management should conclude?","fr":"Une unité d’affaires déclare un taux d’achèvement de 100 % de ses certifications trimestrielles des accès, mais presque aucun accès n’a été retiré. Que devrait conclure la direction, selon le chapitre?"},"options":{"en":["The access model is clean, so reviews can safely move from quarterly to annual","Reviewers are performing well, so remediation tracking is no longer necessary","Review frequency is too high and is creating unnecessary administrative work","Completion shows the process ran, but not that access risk was competently assessed"],"fr":["Le modèle d’accès est propre; les revues peuvent donc passer sans risque d’une fréquence trimestrielle à annuelle","Les réviseurs font du bon travail; le suivi des mesures correctives n’est donc plus nécessaire","La fréquence des revues est trop élevée et crée un travail administratif inutile","L’achèvement montre que le processus a été exécuté, mais non que le risque lié à l’accès a été évalué avec compétence"]}},{"n":12,"answer":"C","section":{"en":"Implementation roadmap: a practical sequence for managers","fr":"Feuille de route de mise en œuvre : une séquence pratique pour les gestionnaires"},"q":{"en":"Which combination is the clearest example of a toxic combination in a purchase-to-pay process?","fr":"Quelle combinaison constitue l’exemple le plus clair de combinaison de droits incompatibles dans un processus d’approvisionnement à paiement?"},"options":{"en":["One user can view supplier records and also print purchase-order reports","One user can submit expense claims and also view their own payment history","One user can create a new supplier and also release payments to that supplier","One user can update their own contact details and also reset their password"],"fr":["Un utilisateur peut consulter les fiches des fournisseurs et aussi imprimer des rapports de bons de commande","Un utilisateur peut soumettre des demandes de remboursement de dépenses et aussi consulter son propre historique de paiements","Un utilisateur peut créer un nouveau fournisseur et aussi libérer des paiements à ce fournisseur","Un utilisateur peut mettre à jour ses propres coordonnées et aussi réinitialiser son mot de passe"]}},{"n":13,"answer":"C","section":{"en":"Segregation of duties: IAM as fraud prevention and control assurance","fr":"Séparation des tâches : la GIA au service de la prévention de la fraude et de l’assurance des contrôles"},"q":{"en":"How does the chapter link segregation of duties to the fraud triangle introduced in Chapter 1?","fr":"Comment le chapitre relie-t-il la séparation des tâches au triangle de la fraude présenté au chapitre 1?"},"options":{"en":["SoD reduces rationalization by requiring employees to sign annual ethics statements","SoD reduces pressure by distributing workloads more evenly across finance teams","SoD reduces opportunity, the fraud condition that controls can most directly influence","SoD removes all three fraud conditions once preventive conflict rules are in place"],"fr":["La séparation des tâches réduit la rationalisation en obligeant les employés à signer une déclaration éthique annuelle","La séparation des tâches réduit la pression en répartissant plus également la charge de travail entre les équipes des finances","La séparation des tâches réduit l’occasion, la condition de fraude sur laquelle les contrôles peuvent le plus directement agir","La séparation des tâches élimine les trois conditions de la fraude dès que des règles préventives de conflit sont en place"]}},{"n":14,"answer":"D","section":{"en":"Third-party and partner access governance: the extended identity problem","fr":"Gouvernance des accès des tiers et des partenaires : le problème de l’identité étendue"},"q":{"en":"What principle does the chapter state about third-party access governance?","fr":"Quel principe le chapitre énonce-t-il au sujet de la gouvernance de l’accès des tiers?"},"options":{"en":["Suppliers become fully accountable for any access granted under a signed contract","Federated partner identities need no internal governance once trust is configured","External access should be permanent to avoid disrupting essential supplier support","Delegating access does not transfer accountability; external access stays within our risk boundary"],"fr":["Les fournisseurs deviennent entièrement imputables de tout accès accordé en vertu d’un contrat signé","Les identités fédérées des partenaires n’exigent aucune gouvernance interne une fois la confiance configurée","L’accès externe devrait être permanent pour éviter de perturber le soutien essentiel des fournisseurs","Déléguer l’accès ne transfère pas l’imputabilité; l’accès externe demeure à l’intérieur de notre périmètre de risque"]}},{"n":15,"answer":"A","section":{"en":"Chapter summary","fr":"Feuille de route de mise en œuvre : une séquence pratique pour les gestionnaires"},"q":{"en":"Which practice best reflects the PAM goal of reducing standing privilege?","fr":"Quelle pratique reflète le mieux l’objectif de la GAP de réduire les privilèges permanents?"},"options":{"en":["Granting time-limited elevation for an approved task and removing it automatically afterwards","Giving all administrators permanent rights but recording their sessions on video","Sharing one administrator password among the team and rotating it every year","Assigning administrative rights to users' ordinary email and browsing identities"],"fr":["Accorder une élévation limitée dans le temps pour une tâche approuvée et la retirer automatiquement par la suite","Donner des droits permanents à tous les administrateurs, mais enregistrer leurs sessions en vidéo","Partager un seul mot de passe d’administrateur au sein de l’équipe et le changer chaque année","Attribuer des droits d’administration aux identités ordinaires de courriel et de navigation des utilisateurs"]}},{"n":16,"answer":"B","section":{"en":"Break-glass accounts: emergency access without permanent weakness","fr":"Comptes « bris de glace » : un accès d’urgence sans faiblesse permanente"},"q":{"en":"Which statement captures the chapter's principle for break-glass emergency access?","fr":"Quel énoncé traduit le principe du chapitre au sujet de l’accès d’urgence (« bris de glace »)?"},"options":{"en":["It should rely on the main identity provider so that it stays fully consistent","It should bypass failed dependencies, not governance itself","It should be known to all administrators so it is always available in a crisis","It should be excluded from monitoring so attackers cannot detect its existence"],"fr":["Il devrait reposer sur le fournisseur d’identité principal afin de demeurer entièrement cohérent","Il devrait contourner les dépendances défaillantes, et non la gouvernance elle-même","Il devrait être connu de tous les administrateurs afin d’être toujours disponible en situation de crise","Il devrait être exclu de la surveillance afin que les attaquants ne puissent pas détecter son existence"]}},{"n":17,"answer":"A","section":{"en":"Non-human identities: service accounts, API keys, tokens, and machine-to-machine trust","fr":"Identités non humaines : comptes de service, clés d’API, jetons et confiance de machine à machine"},"q":{"en":"Why does the chapter argue that least privilege matters even more for machine identities than for people?","fr":"Pourquoi le chapitre soutient-il que le moindre privilège importe encore plus pour les identités machines que pour les personnes?"},"options":{"en":["An overprivileged automated process may run thousands of times daily and be trusted implicitly","Machine identities are always exempt from logging, so their activity cannot be observed","Machine identities can never be classified as privileged under the PAM model","Machine identities always use phishing-resistant authentication, so they are rarely compromised"],"fr":["Un processus automatisé doté de privilèges excessifs peut s’exécuter des milliers de fois par jour et bénéficier d’une confiance implicite","Les identités machines sont toujours exemptées de journalisation; leur activité ne peut donc pas être observée","Les identités machines ne peuvent jamais être classées comme privilégiées dans le modèle de GAP","Les identités machines utilisent toujours une authentification résistante à l’hameçonnage et sont donc rarement compromises"]}},{"n":18,"answer":"C","section":{"en":"PAM: the crown jewel controls managers must demand","fr":"GAP : des contrôles « joyaux de la couronne » que les gestionnaires doivent exiger"},"q":{"en":"Logs of privileged activity are stored on a platform that the same domain administrators can modify and delete. What is the main assurance problem?","fr":"Les journaux de l’activité privilégiée sont stockés sur une plateforme que les mêmes administrateurs de domaine peuvent modifier et supprimer. Quel est le principal problème d’assurance?"},"options":{"en":["The logs are probably too small to support a full forensic investigation","The logs will be retained too long and breach every privacy requirement","The evidence can be altered by the identities whose actions it documents","The logs record activity in a format that managers cannot read directly"],"fr":["Les journaux sont probablement trop petits pour soutenir une enquête criminalistique complète","Les journaux seront conservés trop longtemps et contreviendront à toutes les exigences en matière de vie privée","Les éléments probants peuvent être altérés par les identités dont ils consignent les actions","Les journaux consignent l’activité dans un format que les gestionnaires ne peuvent pas lire directement"]}},{"n":19,"answer":"B","section":{"en":"Measurement: IAM/PAM metrics that matter to governance","fr":"Mesure : les mesures de GIA et de GAP qui comptent pour la gouvernance"},"q":{"en":"Which of the following is an effectiveness metric rather than an activity metric, in the chapter's terms?","fr":"Au sens du chapitre, laquelle des mesures suivantes est une mesure d’efficacité plutôt qu’une mesure d’activité?"},"options":{"en":["Ten thousand access reviews completed during the year","95 percent of inappropriate permissions remediated within 30 days","Five hundred privileged-access requests processed this quarter","Two thousand password resets handled by the service desk"],"fr":["Dix mille revues des accès effectuées au cours de l’année","95 % des permissions inappropriées corrigées dans un délai de 30 jours","Cinq cents demandes d’accès privilégié traitées au cours du trimestre","Deux mille réinitialisations de mots de passe traitées par le centre de services"]}},{"n":20,"answer":"D","section":{"en":"Implementation roadmap: a practical sequence for managers","fr":"Feuille de route de mise en œuvre : une séquence pratique pour les gestionnaires"},"q":{"en":"In the Québec manufacturer scenario, why did the CISO reorder the vendor's proposed IAM roadmap?","fr":"Dans la mise en situation du fabricant québécois, pourquoi le CSI a-t-il réordonné la feuille de route de GIA proposée par le fournisseur?"},"options":{"en":["The board refused to fund any role-engineering work across its applications","Regulators required PAM deployment before any other identity control could proceed","The outsourced provider could not support the ERP system's role-based access model","Two scenarios exceeded risk appetite, so the most consequential access paths were addressed first"],"fr":["Le conseil d’administration a refusé de financer tout travail d’ingénierie des rôles dans ses applications","Les organismes de réglementation exigeaient le déploiement de la GAP avant tout autre contrôle d’identité","Le fournisseur en impartition ne pouvait pas prendre en charge le modèle d’accès fondé sur les rôles du PGI","Deux scénarios dépassaient l’appétence pour le risque; les voies d’accès les plus lourdes de conséquences ont donc été traitées en premier"]}}]},{"n":11,"title":{"en":"Chapter 11: OT, IoT, and Cyber-Physical Security","fr":"Chapitre 11 : Sécurité des TO, de l’IdO et des systèmes cyberphysiques"},"questions":[{"n":1,"answer":"A","section":{"en":"Definitions and scope: what managers should include in OT, IoT, and CPS","fr":"Définitions et portée : ce que les gestionnaires devraient inclure dans les TO, l’IdO et les systèmes cyberphysiques"},"q":{"en":"How did NIST SP 800-82 Rev. 3 change the terminology used for industrial control systems?","fr":"Comment la publication NIST SP 800-82 Rev. 3 a-t-elle modifié la terminologie employée pour les systèmes de contrôle industriels?"},"options":{"en":["It broadened 'industrial control systems' to 'operational technology' to reflect wider use","It replaced 'operational technology' with 'cyber-physical systems' for all sectors","It limited its scope to electricity and pipelines regulated by federal agencies","It merged IoT and OT into a single category called the industrial IoT"],"fr":["Elle a élargi « systèmes de contrôle industriels » à « technologie opérationnelle » pour refléter un usage plus large","Elle a remplacé « technologie opérationnelle » par « systèmes cyberphysiques » pour tous les secteurs","Elle a limité sa portée à l’électricité et aux pipelines réglementés par des organismes fédéraux","Elle a fusionné l’IdO et la TO en une seule catégorie appelée Internet industriel des objets"]}},{"n":2,"answer":"B","section":{"en":"Definitions and scope: what managers should include in OT, IoT, and CPS","fr":"Définitions et portée : ce que les gestionnaires devraient inclure dans les TO, l’IdO et les systèmes cyberphysiques"},"q":{"en":"According to the chapter's scope test, which pair of 'yes' answers usually places a system in the high-consequence tier?","fr":"Selon le test de portée du chapitre, quelle paire de réponses « oui » place habituellement un système dans le niveau à forte conséquence?"},"options":{"en":["Connectivity and ownership","Physical influence and consequence","Manageability and data","Data and connectivity"],"fr":["Connectivité et responsabilité","Influence physique et conséquence","Gérabilité et données","Données et connectivité"]}},{"n":3,"answer":"C","section":{"en":"How OT and IoT risk differs: priorities, constraints, and risk types","fr":"Résumé du chapitre"},"q":{"en":"Which statement best reflects the chapter's view of priorities in operational environments?","fr":"Quel énoncé reflète le mieux le point de vue du chapitre sur les priorités dans les environnements opérationnels?"},"options":{"en":["Confidentiality is irrelevant because OT data has no value to attackers","Confidentiality always outranks availability because recipes are trade secrets","Safety, process availability, and integrity of control usually take precedence over confidentiality","Availability matters only for IoT devices, not for safety-related controllers"],"fr":["La confidentialité est sans importance, car les données de TO n’ont aucune valeur pour les attaquants","La confidentialité l’emporte toujours sur la disponibilité, car les recettes sont des secrets commerciaux","La sécurité des personnes, la disponibilité des processus et l’intégrité de la commande l’emportent habituellement sur la confidentialité","La disponibilité ne compte que pour les appareils IdO, et non pour les automates liés à la sécurité"]}},{"n":4,"answer":"D","section":{"en":"Chapter summary","fr":"Résumé du chapitre"},"q":{"en":"A plant engineer says a controller 'cannot be patched'. How does the chapter say this statement should be treated?","fr":"Un ingénieur d’usine affirme qu’un automate « ne peut pas recevoir de correctif ». Selon le chapitre, comment cet énoncé devrait-il être traité?"},"options":{"en":["As a final answer that closes the vulnerability record for that asset","As evidence that the controller is safe because it is isolated by design","As a reason to transfer the asset's ownership to the central IT department","As a constraint requiring an explicit risk decision, compensating controls, and a plan"],"fr":["Comme une réponse définitive qui ferme le dossier de vulnérabilité de cet actif","Comme la preuve que l’automate est sûr parce qu’il est isolé par conception","Comme une raison de transférer la responsabilité de l’actif au service central des TI","Comme une contrainte qui exige une décision de risque explicite, des contrôles compensatoires et un plan"]}},{"n":5,"answer":"D","section":{"en":"How OT and IoT risk differs: priorities, constraints, and risk types","fr":"En quoi le risque lié aux TO et à l’IdO diffère : priorités, contraintes et types de risques"},"q":{"en":"Which risk type from the chapter's taxonomy can let a system keep running while producing unsafe or misleading results?","fr":"Quel type de risque de la taxonomie du chapitre peut permettre à un système de continuer à fonctionner tout en produisant des résultats dangereux ou trompeurs?"},"options":{"en":["Operational disruption through ransomware encryption","Loss of visibility caused by incomplete inventories","Supplier remote-access risk through shared accounts","Integrity manipulation of setpoints, readings, logic, or alarms"],"fr":["La perturbation opérationnelle causée par le chiffrement d’un rançongiciel","La perte de visibilité causée par des inventaires incomplets","Le risque lié à l’accès à distance des fournisseurs au moyen de comptes partagés","La manipulation de l’intégrité des points de consigne, des lectures, de la logique ou des alarmes"]}},{"n":6,"answer":"C","section":{"en":"The standards and regulatory landscape","fr":"Le paysage des normes et de la réglementation"},"q":{"en":"What is the distinctive contribution of the ISA/IEC 62443 series, according to the chapter?","fr":"Selon le chapitre, quel est l’apport distinctif de la série ISA/IEC 62443?"},"options":{"en":["It sets mandatory reporting deadlines for incidents at critical infrastructure operators","It replaces functional safety standards such as IEC 61508 for industrial processes","It assigns requirements to asset owners, service providers and integrators, and product suppliers","It applies only to consumer IoT devices sold on the European market"],"fr":["Elle fixe des délais obligatoires de déclaration des incidents pour les exploitants d’infrastructures essentielles","Elle remplace les normes de sécurité fonctionnelle comme l’IEC 61508 pour les procédés industriels","Elle attribue des exigences aux propriétaires d’actifs, aux fournisseurs de services et intégrateurs, et aux fournisseurs de produits","Elle ne s’applique qu’aux appareils IdO grand public vendus sur le marché européen"]}},{"n":7,"answer":"B","section":{"en":"The standards and regulatory landscape","fr":"Résumé du chapitre"},"q":{"en":"Why does the chapter describe setting a target security level (SL 1 to SL 4) for a zone as a managerial matter?","fr":"Pourquoi le chapitre présente-t-il le choix d’un niveau de sécurité cible (SL 1 à SL 4) pour une zone comme une question managériale?"},"options":{"en":["It determines the product warranty period that suppliers must provide by law","It defines the attacker the zone must withstand, which is a risk-appetite decision","It sets the maximum number of devices that may be placed in each zone","It is assigned automatically by certification bodies such as ISASecure"],"fr":["Il détermine la période de garantie que les fournisseurs doivent offrir en vertu de la loi","Il définit l’attaquant auquel la zone doit résister, ce qui est une décision d’appétence pour le risque","Il fixe le nombre maximal d’appareils pouvant être placés dans chaque zone","Il est attribué automatiquement par des organismes de certification comme ISASecure"]}},{"n":8,"answer":"A","section":{"en":"The standards and regulatory landscape","fr":"Le paysage des normes et de la réglementation"},"q":{"en":"Under the EU Cyber Resilience Act as described in the chapter, when do the main obligations such as essential requirements, support periods, and CE marking apply?","fr":"Selon le règlement européen sur la cyberrésilience tel que décrit dans le chapitre, à partir de quand s’appliquent les principales obligations, comme les exigences essentielles, les périodes de soutien et le marquage CE?"},"options":{"en":["From December 11, 2027","From December 10, 2024","From September 11, 2026","From October 17, 2024"],"fr":["À partir du 11 décembre 2027","À partir du 10 décembre 2024","À partir du 11 septembre 2026","À partir du 17 octobre 2024"]}},{"n":9,"answer":"B","section":{"en":"The standards and regulatory landscape","fr":"Le paysage des normes et de la réglementation"},"q":{"en":"A Québec municipal water utility asks whether Canada's Critical Cyber Systems Protection Act (CCSPA) applies to it. Based on the chapter, what is the most accurate answer?","fr":"Un service municipal d’eau québécois demande si la Loi sur la protection des cybersystèmes essentiels (LPCE) du Canada s’applique à lui. D’après le chapitre, quelle est la réponse la plus juste?"},"options":{"en":["Yes, because the CCSPA covers every operator of drinking-water systems in Canada","Probably not, because the CCSPA targets designated operators in federally regulated sectors","Yes, because the CCSPA applies to all organizations using SCADA systems","No, because the CCSPA has not yet received Royal Assent in Parliament"],"fr":["Oui, car la LPCE vise tous les exploitants de systèmes d’eau potable au Canada","Probablement pas, car la LPCE vise les exploitants désignés des secteurs sous réglementation fédérale","Oui, car la LPCE s’applique à toutes les organisations qui utilisent des systèmes SCADA","Non, car la LPCE n’a pas encore reçu la sanction royale au Parlement"]}},{"n":10,"answer":"A","section":{"en":"Governance foundations: inventory, criticality, and what must not fail","fr":"Fondements de la gouvernance : inventaire, criticité et ce qui ne doit pas tomber en panne"},"q":{"en":"Why does the chapter recommend combining passive monitoring, configuration review, walk-downs, and records to build an OT inventory?","fr":"Pourquoi le chapitre recommande-t-il de combiner la surveillance passive, l’examen des configurations, les inspections sur le terrain et les dossiers pour constituer un inventaire de la TO?"},"options":{"en":["Aggressive active scanning can disrupt fragile OT devices","Passive methods are required by NIS2 for all essential entities","Physical walk-downs replace the need for ongoing inventory maintenance","Vendor documentation is always complete and current for legacy equipment"],"fr":["Une analyse active agressive peut perturber des appareils de TO fragiles","La directive NIS2 exige des méthodes passives pour toutes les entités essentielles","Les inspections sur le terrain rendent inutile la mise à jour continue de l’inventaire","La documentation des fournisseurs est toujours complète et à jour pour l’équipement patrimonial"]}},{"n":11,"answer":"D","section":{"en":"Chapter summary","fr":"Fondements de la gouvernance : inventaire, criticité et ce qui ne doit pas tomber en panne"},"q":{"en":"In OT and CPS, how does the chapter say criticality should primarily be defined?","fr":"En TO et dans les systèmes cyberphysiques, comment le chapitre indique-t-il que la criticité devrait principalement être définie?"},"options":{"en":["By the sensitivity of the data the system stores and processes","By the purchase price and replacement cost of the equipment","By the number of users who log in to the system each day","By the consequences of disruption or manipulation, working back from the worst credible outcomes"],"fr":["Selon la sensibilité des données que le système stocke et traite","Selon le prix d’achat et le coût de remplacement de l’équipement","Selon le nombre d’utilisateurs qui se connectent au système chaque jour","Selon les conséquences d’une perturbation ou d’une manipulation, en remontant à partir des pires résultats crédibles"]}},{"n":12,"answer":"C","section":{"en":"Operating model and accountability: bridging IT, engineering, facilities, and vendors","fr":"Modèle opérationnel et imputabilité : rapprocher les TI, l’ingénierie, les installations et les fournisseurs"},"q":{"en":"During an OT incident, security wants to isolate a network, operations fears production loss, and a vendor demands unverified remote access. What does the chapter identify as the governance gap?","fr":"Pendant un incident de TO, l’équipe de sécurité veut isoler un réseau, l’exploitation craint une perte de production et un fournisseur exige un accès à distance non vérifié. Quelle lacune de gouvernance le chapitre relève-t-il?"},"options":{"en":["The organization lacked enough endpoint agents on its controllers","The vendor contract did not include a sufficiently high penalty clause","Decision rights were not explicitly agreed and documented before the incident","The SOC had not been given administrative rights to the OT network"],"fr":["L’organisation n’avait pas assez d’agents de terminal sur ses automates","Le contrat du fournisseur ne comportait pas de clause pénale assez élevée","Les droits décisionnels n’avaient pas été explicitement convenus et documentés avant l’incident","Le COS n’avait pas reçu de droits d’administration sur le réseau de TO"]}},{"n":13,"answer":"C","section":{"en":"Policy and procurement: controlling risk before devices are deployed","fr":"Politique et approvisionnement : maîtriser le risque avant le déploiement des appareils"},"q":{"en":"Why does the chapter call procurement a primary cybersecurity control in OT and IoT?","fr":"Pourquoi le chapitre qualifie-t-il l’approvisionnement de contrôle de cybersécurité de premier plan en TO et en IdO?"},"options":{"en":["Procurement teams are the only function with authority to patch devices","Suppliers are legally liable for all incidents once a contract is signed","Governance leverage is highest before purchase, since devices may create risk for twenty years","Purchasing rules automatically satisfy the requirements of ISA/IEC 62443"],"fr":["Les équipes d’approvisionnement sont la seule fonction autorisée à appliquer des correctifs aux appareils","Les fournisseurs sont légalement responsables de tous les incidents une fois le contrat signé","Le levier de gouvernance est le plus fort avant l’achat, car les appareils peuvent créer un risque pendant vingt ans","Les règles d’achat satisfont automatiquement aux exigences de la série ISA/IEC 62443"]}},{"n":14,"answer":"D","section":{"en":"Policy and procurement: controlling risk before devices are deployed","fr":"Politique et approvisionnement : maîtriser le risque avant le déploiement des appareils"},"q":{"en":"Which remote-access arrangement best matches the chapter's expectations for OT vendors?","fr":"Quel arrangement d’accès à distance correspond le mieux aux attentes du chapitre à l’égard des fournisseurs de TO?"},"options":{"en":["An always-on VPN account shared by the vendor's technicians for faster support","A vendor-installed cellular modem so access does not depend on corporate networks","Permanent access to the whole plant network to avoid delays during breakdowns","Approved per session, MFA-protected, routed through a controlled access point, restricted, and logged"],"fr":["Un compte RPV toujours actif, partagé par les techniciens du fournisseur pour accélérer le soutien","Un modem cellulaire installé par le fournisseur pour que l’accès ne dépende pas des réseaux de l’entreprise","Un accès permanent à tout le réseau de l’usine pour éviter les retards en cas de panne","Approuvé par session, protégé par AMF, acheminé par un point d’accès contrôlé, restreint et journalisé"]}},{"n":15,"answer":"A","section":{"en":"Chapter summary","fr":"Architecture : zones, conduits, moindre privilège et présomption de compromission"},"q":{"en":"In ISA/IEC 62443-3-2 terms, what is a conduit?","fr":"Au sens de l’ISA/IEC 62443-3-2, qu’est-ce qu’un conduit?"},"options":{"en":["A controlled communication path between zones with defined permitted traffic and protective measures","A grouping of assets that share common security requirements and consequences","A hardwired safety layer that brings a process to a safe state on failure","A certification scheme for suppliers' secure development lifecycles"],"fr":["Une voie de communication contrôlée entre des zones, assortie d’un trafic autorisé et de mesures de protection définis","Un regroupement d’actifs qui partagent des exigences de sécurité et des conséquences communes","Une couche de sécurité câblée qui amène un processus à un état sûr en cas de défaillance","Un programme de certification des cycles de développement sécurisé des fournisseurs"]}},{"n":16,"answer":"B","section":{"en":"Patch and change governance under operational constraints","fr":"Gouvernance des correctifs et du changement sous contraintes opérationnelles"},"q":{"en":"Two vulnerabilities share a high CVSS score: one on an Internet-exposed remote-access gateway, one on an isolated sensor deep inside a well-protected zone. Applying the chapter, which prioritization is most defensible?","fr":"Deux vulnérabilités ont le même score CVSS élevé : l’une touche une passerelle d’accès à distance exposée à Internet, l’autre un capteur isolé au cœur d’une zone bien protégée. En appliquant le chapitre, quelle priorisation est la plus défendable?"},"options":{"en":["Patch both immediately, because equal CVSS scores require equal treatment","Act urgently on the gateway; the sensor may wait for the next planned outage","Patch the sensor first, because it is closer to the physical process","Defer both until the annual shutdown to avoid any production disruption"],"fr":["Appliquer immédiatement les deux correctifs, car des scores CVSS égaux exigent un traitement égal","Agir d’urgence sur la passerelle; le capteur peut attendre le prochain arrêt planifié","Corriger d’abord le capteur, car il est plus près du processus physique","Reporter les deux jusqu’à l’arrêt annuel pour éviter toute perturbation de la production"]}},{"n":17,"answer":"A","section":{"en":"Safety and security: one risk conversation","fr":"Sécurité des personnes et cybersécurité : une seule conversation sur le risque"},"q":{"en":"What is the central idea of IEC TR 63069:2019 as presented in the chapter?","fr":"Quelle est l’idée centrale de l’IEC TR 63069:2019 telle que présentée dans le chapitre?"},"options":{"en":["Security protects the safety function, so safety assumptions remain valid","Safety systems should be connected to the Internet for real-time monitoring","Security controls should replace independent layers of protection over time","Safety and security should be managed by separate teams with separate reports"],"fr":["La sécurité protège la fonction de sécurité fonctionnelle, de sorte que les hypothèses de sécurité demeurent valides","Les systèmes de sécurité fonctionnelle devraient être connectés à Internet pour une surveillance en temps réel","Les contrôles de sécurité devraient remplacer avec le temps les couches de protection indépendantes","La sécurité fonctionnelle et la cybersécurité devraient être gérées par des équipes distinctes, avec des rapports distincts"]}},{"n":18,"answer":"C","section":{"en":"Detection, response, and resilience when systems are degraded","fr":"Détection, intervention et résilience lorsque les systèmes sont dégradés"},"q":{"en":"What is the purpose of pre-agreed precautionary shutdown criteria in OT incident response?","fr":"Quel est l’objectif de critères d’arrêt préventif convenus à l’avance dans l’intervention en cas d’incident de TO?"},"options":{"en":["To guarantee that production never stops during any cyber incident or outage","To let the vendor decide alone whether the plant should keep operating normally","To decide in advance when to stop a process that can no longer be trusted","To replace the need for manual fallback procedures and exercises"],"fr":["Garantir que la production ne s’arrête jamais pendant un cyberincident ou une panne","Laisser le fournisseur décider seul si l’usine devrait continuer à fonctionner normalement","Décider à l’avance quand arrêter un processus auquel on ne peut plus se fier","Rendre inutiles les procédures et exercices de repli en mode manuel"]}},{"n":19,"answer":"B","section":{"en":"AI-enabled cyber-physical environments: model abuse, data poisoning, and unsafe automation","fr":"Environnements cyberphysiques intégrant l’IA : usage abusif des modèles, empoisonnement des données et automatisation dangereuse"},"q":{"en":"An AI optimization system could adjust a process automatically in ways that conflict with a safety instrumented function. What does the chapter require?","fr":"Un système d’optimisation fondé sur l’IA pourrait ajuster automatiquement un processus d’une façon qui entre en conflit avec une fonction instrumentée de sécurité. Qu’exige le chapitre?"},"options":{"en":["The AI may override the safety function if its accuracy exceeds that of operators","AI must never override or bypass the safety function, and protective layers must stay independent","The safety function should be retuned to follow the AI's optimized setpoints","Human approval can be removed once the model has run safely for a year"],"fr":["L’IA peut outrepasser la fonction de sécurité si sa précision dépasse celle des opérateurs","L’IA ne doit jamais outrepasser ni contourner la fonction de sécurité, et les couches de protection doivent demeurer indépendantes","La fonction de sécurité devrait être réglée de nouveau pour suivre les points de consigne optimisés par l’IA","L’approbation humaine peut être retirée une fois que le modèle a fonctionné de façon sûre pendant un an"]}},{"n":20,"answer":"D","section":{"en":"Governing OT and IoT risk in practice: metrics, a worked scenario, and questions","fr":"Gouverner le risque lié à la TO et à l’IdO dans la pratique : mesures, scénario détaillé et questions"},"q":{"en":"In the water utility scenario, the board's appetite statement expressed 'very low appetite' for interruptions over four hours. Why was the Internet-exposed HMI scenario judged clearly intolerable?","fr":"Dans la mise en situation du service d’eau, l’énoncé d’appétence du conseil exprimait une « très faible appétence » pour les interruptions de plus de quatre heures. Pourquoi le scénario de l’IHM exposée à Internet a-t-il été jugé clairement intolérable?"},"options":{"en":["It had the highest CVSS score of all vulnerabilities found during discovery","Its remediation would have cost more than the utility's annual budget","The integrator refused to support the HMIs after the contract renewal","It threatened drinking water safety, for which the board had stated no appetite"],"fr":["Il présentait le score CVSS le plus élevé de toutes les vulnérabilités découvertes","Sa correction aurait coûté davantage que le budget annuel du service","L’intégrateur a refusé de soutenir les IHM après le renouvellement du contrat","Il menaçait la sécurité de l’eau potable, pour laquelle le conseil avait déclaré n’avoir aucune appétence"]}}]},{"n":12,"title":{"en":"Chapter 12: Incident Management, Business Continuity, and Resilience","fr":"Chapitre 12 : Gestion des incidents, continuité des activités et résilience"},"questions":[{"n":1,"answer":"A","section":{"en":"Chapter summary","fr":"Résumé du chapitre"},"q":{"en":"According to the chapter, at what point does a cybersecurity incident become an executive crisis rather than a technical event?","fr":"Selon le chapitre, à quel moment un incident de cybersécurité devient-il une crise pour la haute direction plutôt qu’un événement technique?"},"options":{"en":["When residual risk materializes at a scale the security operations centre cannot absorb alone","When the incident response team has been working on it for more than one shift","When the attacker is confirmed to be a state-sponsored threat actor","When the incident has been assigned a CVSS v4.0 score above nine"],"fr":["Lorsque le risque résiduel se matérialise à une échelle que le centre des opérations de sécurité ne peut pas absorber seul","Lorsque l’équipe d’intervention y travaille depuis plus d’un quart de travail","Lorsqu’il est confirmé que l’attaquant est un acteur de menace parrainé par un État","Lorsque l’incident a reçu un score CVSS v4.0 supérieur à neuf"]}},{"n":2,"answer":"B","section":{"en":"Why major incidents are executive crises","fr":"Pourquoi les incidents majeurs sont des crises pour la haute direction"},"q":{"en":"What does the chapter identify as the usual governance failure regarding crisis decision-making?","fr":"Quelle défaillance de gouvernance le chapitre relève-t-il habituellement dans la prise de décision en situation de crise?"},"options":{"en":["The wrong executive consistently makes decisions that should belong to the CISO","No one is sure who should decide, so decisions are delayed or later contested","Boards insist on taking every operational decision during the incident","Decision-makers rely too heavily on documented authority and rehearsed criteria"],"fr":["Le mauvais dirigeant prend systématiquement des décisions qui devraient revenir au CSI","Personne ne sait avec certitude qui devrait décider; les décisions sont donc retardées ou contestées par la suite","Les conseils d’administration insistent pour prendre chaque décision opérationnelle pendant l’incident","Les décideurs se fient trop à une autorité documentée et à des critères répétés"]}},{"n":3,"answer":"C","section":{"en":"Why major incidents are executive crises","fr":"Pourquoi les incidents majeurs sont des crises pour la haute direction"},"q":{"en":"Which of the following is an escalation threshold expressed in business terms, as the chapter recommends?","fr":"Lequel des énoncés suivants est un seuil de remontée exprimé en termes d’affaires, comme le recommande le chapitre?"},"options":{"en":["More than fifty endpoint detection alerts in one hour","Detection of malware with a known signature on a laptop","Interruption of a critical service beyond a defined period","A firewall rule change made outside the change window"],"fr":["Plus de cinquante alertes de détection sur les terminaux en une heure","La détection d’un logiciel malveillant dont la signature est connue sur un ordinateur portable","L’interruption d’un service critique au-delà d’une période définie","Une modification de règle de pare-feu effectuée hors de la fenêtre de changement"]}},{"n":4,"answer":"D","section":{"en":"Two systems that must interlock: the incident response team and the crisis management team","fr":"Résumé du chapitre"},"q":{"en":"Which statement best describes the different purposes of the IRT and the CMT?","fr":"Quel énoncé décrit le mieux les finalités différentes de l’équipe d’intervention en cas d’incident et de la cellule de crise?"},"options":{"en":["The IRT handles external communications; the CMT performs forensic investigation","The IRT sets business priorities; the CMT carries out containment and eradication","The IRT reports to the board; the CMT reports to the security operations centre","The IRT regains control of the environment; the CMT protects the enterprise while that happens"],"fr":["L’équipe d’intervention gère les communications externes; la cellule de crise mène l’enquête criminalistique","L’équipe d’intervention fixe les priorités d’affaires; la cellule de crise effectue le confinement et l’éradication","L’équipe d’intervention rend compte au conseil; la cellule de crise rend compte au centre des opérations de sécurité","L’équipe d’intervention reprend le contrôle de l’environnement; la cellule de crise protège l’entreprise pendant ce temps"]}},{"n":5,"answer":"D","section":{"en":"Two systems that must interlock: the incident response team and the crisis management team","fr":"Deux systèmes qui doivent s’imbriquer : l’équipe d’intervention en cas d’incident et la cellule de crise"},"q":{"en":"A technical team restores the systems it considers important while the business needed others first, and executives issue statements they later retract. Which failure mode does this illustrate?","fr":"Une équipe technique restaure les systèmes qu’elle juge importants alors que l’entreprise avait d’abord besoin d’autres systèmes, et des dirigeants publient des déclarations qu’ils doivent ensuite retirer. Quel mode de défaillance cela illustre-t-il?"},"options":{"en":["Blending of the two teams into one overloaded structure","Excessive reliance on a single source of truth","Over-use of out-of-band communication channels","Separation of the two teams without integration"],"fr":["La fusion des deux équipes en une seule structure surchargée","Une dépendance excessive envers une source unique de vérité","Un recours excessif aux canaux de communication hors bande","La séparation des deux équipes sans intégration"]}},{"n":6,"answer":"C","section":{"en":"Two systems that must interlock: the incident response team and the crisis management team","fr":"Deux systèmes qui doivent s’imbriquer : l’équipe d’intervention en cas d’incident et la cellule de crise"},"q":{"en":"Which element of the IRT–CMT interface ensures that some decisions, such as issuing an external statement, can be taken only by the executive team?","fr":"Quel élément de l’interface entre l’équipe d’intervention et la cellule de crise garantit que certaines décisions, comme la publication d’une déclaration externe, ne peuvent être prises que par l’équipe de direction?"},"options":{"en":["Battle rhythm","Liaison role","Reserved decisions","Out-of-band communications"],"fr":["Le rythme opérationnel","Le rôle d’agent de liaison","Les décisions réservées","Les communications hors bande"]}},{"n":7,"answer":"B","section":{"en":"A governance view of the incident lifecycle","fr":"Une vision du cycle de vie des incidents axée sur la gouvernance"},"q":{"en":"In the chapter's five executive phases, what is the main objective of situational clarity?","fr":"Dans les cinq phases vues par la haute direction, quel est le principal objectif de la clarté de la situation?"},"options":{"en":["Complete certainty about the attacker's identity before any decision is taken","Coherent decision-making under uncertainty, using confirmed facts, hypotheses, and confidence levels","Restoring every affected system before informing executives of the incident","Producing the funded remediation roadmap approved by the board"],"fr":["Une certitude complète sur l’identité de l’attaquant avant toute décision","Une prise de décision cohérente dans l’incertitude, à l’aide de faits confirmés, d’hypothèses et de niveaux de confiance","La restauration de tous les systèmes touchés avant d’informer la haute direction de l’incident","La production de la feuille de route corrective financée et approuvée par le conseil"]}},{"n":8,"answer":"A","section":{"en":"A governance view of the incident lifecycle","fr":"Une vision du cycle de vie des incidents axée sur la gouvernance"},"q":{"en":"Why does the chapter insist that after-action reviews identify managerial causes and be facilitated by someone independent of the response?","fr":"Pourquoi le chapitre insiste-t-il pour que les revues post-incident cernent les causes managériales et soient animées par une personne indépendante de l’intervention?"},"options":{"en":["Managerial causes implicate people in the room, and reviews finding only technical causes produce a patch","Regulators require all after-action reviews to be performed and signed by external auditors","Technical causes are rarely real and should therefore be left out of the review report","Independent facilitators are the only people who can assign disciplinary penalties to staff"],"fr":["Les causes managériales mettent en cause des personnes présentes, et une revue qui ne trouve que des causes techniques ne produit qu’un correctif","Les organismes de réglementation exigent que toutes les revues post-incident soient effectuées et signées par des auditeurs externes","Les causes techniques sont rarement réelles et devraient donc être exclues du rapport de revue","Seules des personnes indépendantes peuvent imposer des sanctions disciplinaires au personnel"]}},{"n":9,"answer":"B","section":{"en":"A governance view of the incident lifecycle","fr":"Une vision du cycle de vie des incidents axée sur la gouvernance"},"q":{"en":"What is the most significant conceptual change in NIST SP 800-61 Rev. 3 for managers?","fr":"Quel est le changement conceptuel le plus important de la publication NIST SP 800-61 Rev. 3 pour les gestionnaires?"},"options":{"en":["It adds a seventh incident phase dedicated to ransom negotiation","It maps incident response recommendations onto the six CSF 2.0 functions, including Govern","It replaces the CSF with ISO/IEC 27035 as the basis for incident response","It limits its scope to U.S. federal agencies and their contractors"],"fr":["Elle ajoute une septième phase d’incident consacrée à la négociation de la rançon","Elle associe ses recommandations d’intervention aux six fonctions du CSF 2.0, y compris Gouverner","Elle remplace le CSF par l’ISO/IEC 27035 comme fondement de l’intervention en cas d’incident","Elle limite sa portée aux organismes fédéraux américains et à leurs contractuels"]}},{"n":10,"answer":"A","section":{"en":"Legal and regulatory response discipline","fr":"Rigueur de l’intervention juridique et réglementaire"},"q":{"en":"Why might reimaging an infected server immediately to restore service conflict with legal response discipline?","fr":"Pourquoi la réinstallation immédiate d’un serveur infecté pour rétablir le service peut-elle entrer en conflit avec la rigueur juridique de l’intervention?"},"options":{"en":["It may destroy the only evidence of how the attacker entered and what was taken","It automatically triggers a public disclosure under SEC Form 8-K Item 1.05","It voids all cyber insurance coverage regardless of the policy's terms","It is prohibited under Québec Law 25 for any system holding personal data"],"fr":["Elle peut détruire les seuls éléments probants montrant comment l’attaquant est entré et ce qui a été pris","Elle déclenche automatiquement une divulgation publique en vertu de l’Item 1.05 du formulaire 8-K de la SEC","Elle annule toute couverture de cyberassurance, quelles que soient les modalités de la police","Elle est interdite par la Loi 25 du Québec pour tout système contenant des renseignements personnels"]}},{"n":11,"answer":"D","section":{"en":"Notification obligations: governing several clocks at once","fr":"Obligations d’avis : gouverner plusieurs échéanciers à la fois"},"q":{"en":"Under Québec Law 25 as described in the chapter, which confidentiality incidents must be entered in the register?","fr":"Selon la Loi 25 du Québec telle que décrite dans le chapitre, quels incidents de confidentialité doivent être inscrits au registre?"},"options":{"en":["Only incidents that present a risk of serious injury to the persons concerned","Only incidents involving more than a defined number of affected individuals","Only incidents that the Commission d'accès à l'information has requested","Every confidentiality incident, whether or not it presents a risk of serious injury"],"fr":["Seulement les incidents qui présentent un risque qu’un préjudice sérieux soit causé aux personnes concernées","Seulement les incidents touchant plus qu’un nombre défini de personnes","Seulement les incidents que la Commission d’accès à l’information a demandés","Chaque incident de confidentialité, qu’il présente ou non un risque qu’un préjudice sérieux soit causé"]}},{"n":12,"answer":"C","section":{"en":"Notification obligations: governing several clocks at once","fr":"Obligations d’avis : gouverner plusieurs échéanciers à la fois"},"q":{"en":"A Canadian company with a U.S. listing determines on Monday that an incident is material. Assuming no holidays, by when must it file Form 8-K Item 1.05 disclosure?","fr":"Une entreprise canadienne inscrite à une bourse américaine détermine un lundi qu’un incident est important. En l’absence de jours fériés, à quelle date doit-elle déposer la divulgation prévue à l’Item 1.05 du formulaire 8-K?"},"options":{"en":["Monday, the same day as the materiality determination","Thursday, 72 hours after the incident was first discovered","Friday, four business days after the materiality determination","The following Monday, seven calendar days after discovery"],"fr":["Le lundi, le jour même de la décision sur l’importance relative","Le jeudi, 72 heures après la découverte initiale de l’incident","Le vendredi, quatre jours ouvrables après la décision sur l’importance relative","Le lundi suivant, sept jours civils après la découverte"]}},{"n":13,"answer":"C","section":{"en":"Notification obligations: governing several clocks at once","fr":"Obligations d’avis : gouverner plusieurs échéanciers à la fois"},"q":{"en":"An EU financial entity classifies an incident as major six hours after becoming aware of it. Under DORA, when is the initial notification due?","fr":"Une entité financière de l’UE classe un incident comme majeur six heures après en avoir pris connaissance. En vertu du règlement DORA, quand la notification initiale est-elle due?"},"options":{"en":["Within 24 hours of classification, with no limit based on awareness","Within 72 hours of awareness, as for NIS2 incident notifications","Within four hours of classification, and no later than 24 hours after awareness","Within four business days of determining that the incident is material"],"fr":["Dans les 24 heures suivant le classement, sans limite liée à la prise de connaissance","Dans les 72 heures suivant la prise de connaissance, comme pour les notifications d’incident de la directive NIS2","Dans les quatre heures suivant le classement, et au plus tard 24 heures après la prise de connaissance","Dans les quatre jours ouvrables suivant la décision établissant que l’incident est important"]}},{"n":14,"answer":"D","section":{"en":"Ransomware as a governance stress test","fr":"Résumé du chapitre"},"q":{"en":"According to the chapter, what is the most effective way to avoid an impossible extortion decision?","fr":"Selon le chapitre, quel est le moyen le plus efficace d’éviter une décision d’extorsion impossible?"},"options":{"en":["Pre-negotiate a payment ceiling with ransomware brokers before any attack","Purchase cyber insurance that reimburses any ransom paid by the organization","Delegate the payment decision to an experienced external negotiator","Invest, well before the incident, in recoverability that makes payment unnecessary"],"fr":["Négocier à l’avance un plafond de paiement avec des intermédiaires de rançongiciels","Souscrire une cyberassurance qui rembourse toute rançon payée par l’organisation","Confier la décision de paiement à un négociateur externe expérimenté","Investir, bien avant l’incident, dans une capacité de reprise qui rend le paiement inutile"]}},{"n":15,"answer":"A","section":{"en":"Business continuity management: the managerial spine of resilience","fr":"Gestion de la continuité des activités : la colonne vertébrale managériale de la résilience"},"q":{"en":"Which statement about the relationship between MTPD and RTO is consistent with the chapter?","fr":"Quel énoncé sur la relation entre la MTPD et le RTO est conforme au chapitre?"},"options":{"en":["The RTO must be shorter than the MTPD, leaving a margin for the unexpected","The RTO must be longer than the MTPD to allow full forensic investigation","The RTO and MTPD should be equal so that resources are not wasted","The MTPD is set by IT after the RTO has been technically validated"],"fr":["Le RTO doit être plus court que la MTPD, afin de laisser une marge pour l’imprévu","Le RTO doit être plus long que la MTPD pour permettre une enquête criminalistique complète","Le RTO et la MTPD devraient être égaux afin de ne pas gaspiller de ressources","La MTPD est fixée par les TI une fois le RTO validé techniquement"]}},{"n":16,"answer":"B","section":{"en":"Business continuity management: the managerial spine of resilience","fr":"Gestion de la continuité des activités : la colonne vertébrale managériale de la résilience"},"q":{"en":"A hospital accepts that it can operate for a time on paper charting with reduced services rather than full electronic records. Which recovery objective expresses this acceptable degraded level?","fr":"Un hôpital accepte de fonctionner pendant un certain temps avec des dossiers papier et des services réduits plutôt qu’avec des dossiers électroniques complets. Quel objectif de reprise exprime ce niveau dégradé acceptable?"},"options":{"en":["Recovery point objective (RPO)","Minimum business continuity objective (MBCO)","Maximum tolerable period of disruption (MTPD)","Recovery time objective (RTO)"],"fr":["Le point de reprise visé (RPO)","Le niveau minimal de continuité des activités (MBCO)","La durée maximale d’interruption tolérable (MTPD)","Le délai de reprise visé (RTO)"]}},{"n":17,"answer":"A","section":{"en":"Disaster recovery: from restoring servers to reconstituting trust","fr":"Reprise après sinistre : de la restauration des serveurs au rétablissement de la confiance"},"q":{"en":"Why does the chapter treat identity and key recovery as part of disaster recovery scope?","fr":"Pourquoi le chapitre inclut-il la reprise des identités et des clés dans la portée de la reprise après sinistre?"},"options":{"en":["If the directory service is compromised, every system trusting it is compromised too","Identity systems are the cheapest component to restore after an incident","Regulators prohibit restoring data before identity services are replaced","Identity platforms never contain backups and must always be purchased again"],"fr":["Si le service d’annuaire est compromis, tous les systèmes qui lui font confiance le sont aussi","Les systèmes d’identité sont le composant le moins coûteux à restaurer après un incident","Les organismes de réglementation interdisent de restaurer des données avant le remplacement des services d’identité","Les plateformes d’identité ne contiennent jamais de sauvegardes et doivent toujours être rachetées"]}},{"n":18,"answer":"C","section":{"en":"Operational resilience and systemic dependency","fr":"Résilience opérationnelle et dépendance systémique"},"q":{"en":"How does OSFI Guideline E-21's operational resilience question differ from traditional continuity planning?","fr":"En quoi la question de résilience opérationnelle de la ligne directrice E-21 du BSIF diffère-t-elle de la planification traditionnelle de la continuité?"},"options":{"en":["It asks whether each individual system can recover within its documented RTO","It asks whether backup copies are stored in at least two separate data centres","It asks whether a critical operation can stay within tolerance, regardless of which component fails","It asks whether the institution has purchased sufficient cyber insurance coverage"],"fr":["Elle demande si chaque système peut être repris dans les limites de son RTO documenté","Elle demande si les copies de sauvegarde sont conservées dans au moins deux centres de données distincts","Elle demande si une opération critique peut demeurer dans les limites de tolérance, quel que soit le composant défaillant","Elle demande si l’institution a souscrit une couverture de cyberassurance suffisante"]}},{"n":19,"answer":"B","section":{"en":"A worked crisis: ransomware at a Québec distributor","fr":"Une crise résolue : un rançongiciel chez un distributeur québécois"},"q":{"en":"In the Saint-Laurent scenario, the BIA set a 72-hour MTPD for hospital fulfilment and a 48-hour RTO for the warehouse system, but recovery took six days. Why was the MTPD for critical hospital supply not breached?","fr":"Dans la mise en situation de Saint-Laurent, le BIA fixait une MTPD de 72 heures pour l’exécution des commandes des hôpitaux et un RTO de 48 heures pour le système d’entrepôt, mais la reprise a pris six jours. Pourquoi la MTPD de l’approvisionnement critique des hôpitaux n’a-t-elle pas été dépassée?"},"options":{"en":["The attacker supplied a working decryptor that restored the warehouse system early","Manual fulfilment of critical-item orders kept service above the MBCO while systems were rebuilt","The hospitals agreed to extend the MTPD to six days during the first CMT meeting","Pharmacy orders were rerouted through the hospitals' own warehouse systems"],"fr":["L’attaquant a fourni un outil de déchiffrement fonctionnel qui a permis de rétablir tôt le système d’entrepôt","L’exécution manuelle des commandes d’articles critiques a maintenu le service au-dessus du MBCO pendant la reconstruction des systèmes","Les hôpitaux ont accepté de porter la MTPD à six jours lors de la première réunion de la cellule de crise","Les commandes de la pharmacie ont été réacheminées par les propres systèmes d’entrepôt des hôpitaux"]}},{"n":20,"answer":"D","section":{"en":"Metrics, evidence, and a governance-first implementation sequence","fr":"Mesures, éléments probants et séquence de mise en œuvre axée d’abord sur la gouvernance"},"q":{"en":"Which statement does the chapter present as the most honest resilience metric?","fr":"Quel énoncé le chapitre présente-t-il comme la mesure de résilience la plus honnête?"},"options":{"en":["The number of continuity plans written and approved during the year","The percentage of employees who completed incident awareness training","The total budget spent on backup and recovery technology this year","The gap between the recovery time promised and the recovery time demonstrated"],"fr":["Le nombre de plans de continuité rédigés et approuvés au cours de l’année","Le pourcentage d’employés ayant suivi la formation de sensibilisation aux incidents","Le budget total consacré à la technologie de sauvegarde et de reprise cette année","L’écart entre le délai de reprise promis et le délai de reprise démontré"]}}]},{"n":13,"title":{"en":"Chapter 13: Security Architecture and Security Engineering","fr":"Chapitre 13 : Architecture et ingénierie de la sécurité"},"questions":[{"n":1,"answer":"B","section":{"en":"Architecture and engineering: what managers must govern","fr":"Architecture et ingénierie : ce que les gestionnaires doivent gouverner"},"q":{"en":"According to the chapter, which question does security architecture answer?","fr":"Selon le chapitre, à quelle question l’architecture de sécurité répond-elle?"},"options":{"en":["How will we build and operate target states in our real environment?","What must be true about our environment for risk to stay within appetite?","Which tools should the security operations centre deploy to detect intrusions?","Which business owner accepts the residual risk when a design falls short?"],"fr":["Comment construirons-nous et exploiterons-nous les états cibles dans notre environnement réel?","Qu’est-ce qui doit être vrai dans notre environnement pour que le risque demeure dans les limites de l’appétence?","Quels outils le centre des opérations de sécurité devrait-il déployer pour détecter les intrusions?","Quel responsable métier accepte le risque résiduel lorsqu’une conception est insuffisante?"]}},{"n":2,"answer":"D","section":{"en":"Architecture and engineering: what managers must govern","fr":"Architecture et ingénierie : ce que les gestionnaires doivent gouverner"},"q":{"en":"When a proposed design falls short of the target state, who decides whether to accept the resulting gap?","fr":"Lorsqu’une conception proposée n’atteint pas l’état cible, qui décide s’il faut accepter l’écart qui en résulte?"},"options":{"en":["The security architect who reviewed and documented the design","The architecture review board, by a majority vote of its members","The engineering team responsible for implementing the design","The business owner of the affected service, within risk appetite"],"fr":["L’architecte de sécurité qui a examiné et documenté la conception","Le comité d’examen de l’architecture, par un vote majoritaire de ses membres","L’équipe d’ingénierie chargée de mettre en œuvre la conception","Le responsable métier du service touché, dans les limites de l’appétence pour le risque"]}},{"n":3,"answer":"A","section":{"en":"Architecture and engineering: what managers must govern","fr":"Architecture et ingénierie : ce que les gestionnaires doivent gouverner"},"q":{"en":"Why does the chapter describe architectural controls as having more leverage than detective or procedural controls?","fr":"Pourquoi le chapitre décrit-il les contrôles architecturaux comme ayant plus d’effet de levier que les contrôles de détection ou procéduraux?"},"options":{"en":["They change the environment's structure so whole classes of scenarios become less likely or harmful","They cost less to purchase than detection tools and carry no ongoing operating cost","They rely on staff following written procedures, which auditors find easier to test","They remove the need for risk owners to accept any residual risk at all"],"fr":["Ils modifient la structure de l’environnement, de sorte que des catégories entières de scénarios deviennent moins probables ou moins dommageables","Ils coûtent moins cher à acquérir que les outils de détection et n’entraînent aucun coût d’exploitation continu","Ils reposent sur le respect de procédures écrites par le personnel, que les auditeurs trouvent plus faciles à tester","Ils éliminent la nécessité pour les responsables du risque d’accepter quelque risque résiduel que ce soit"]}},{"n":4,"answer":"C","section":{"en":"Architecture and engineering: what managers must govern","fr":"Architecture et ingénierie : ce que les gestionnaires doivent gouverner"},"q":{"en":"Which ISO/IEC 27002:2022 control specifically addresses secure system architecture and engineering principles?","fr":"Quelle mesure de l’ISO/IEC 27002:2022 porte précisément sur les principes d’architecture et d’ingénierie des systèmes sécurisés?"},"options":{"en":["Control 8.9, configuration management","Control 8.25, secure development life cycle","Control 8.27, secure system architecture and engineering principles","Control 8.28, secure coding"],"fr":["Mesure 8.9, gestion de la configuration","Mesure 8.25, cycle de vie de développement sécurisé","Mesure 8.27, principes d’architecture et d’ingénierie des systèmes sécurisés","Mesure 8.28, codage sécurisé"]}},{"n":5,"answer":"C","section":{"en":"Architecture governance: review boards, design authority, and decisions","fr":"Gouvernance de l’architecture : comités d’examen, autorité de conception et décisions"},"q":{"en":"After an incident, what important distinction does a well-kept architecture decision record allow the organization to make?","fr":"Après un incident, quelle distinction importante une fiche de décision d’architecture bien tenue permet-elle à l’organisation de faire?"},"options":{"en":["Whether the vendor or the customer introduced the vulnerability","Whether the incident must be reported under Québec's Law 25","Whether a risk was consciously accepted or never considered","Whether the review board met its committed service levels"],"fr":["Si c’est le fournisseur ou le client qui a introduit la vulnérabilité","Si l’incident doit être déclaré en vertu de la Loi 25 du Québec","Si un risque a été accepté en connaissance de cause ou n’a jamais été envisagé","Si le comité d’examen a respecté les niveaux de service auxquels il s’était engagé"]}},{"n":6,"answer":"A","section":{"en":"Security by design and secure by default","fr":"Sécurité dès la conception et sécurité par défaut"},"q":{"en":"The chapter calls security by design a sequencing decision. What does that mean?","fr":"Le chapitre qualifie la sécurité dès la conception de décision de séquencement. Qu’est-ce que cela signifie?"},"options":{"en":["It moves security analysis to the point where change is cheapest and options are widest","It places responsibility for safe configuration on the party best able to carry it","It requires security testing to be completed only after deployment to production","It orders controls by cost so that the cheapest ones are implemented first"],"fr":["Elle déplace l’analyse de sécurité au moment où le changement coûte le moins cher et où les options sont les plus vastes","Elle confie la responsabilité de la configuration sûre à la partie la mieux placée pour l’assumer","Elle exige que les tests de sécurité soient effectués seulement après le déploiement en production","Elle ordonne les contrôles selon leur coût afin que les moins chers soient mis en œuvre en premier"]}},{"n":7,"answer":"D","section":{"en":"Security by design and secure by default","fr":"Sécurité dès la conception et sécurité par défaut"},"q":{"en":"Which of the following is one of the three principles in CISA's Secure by Design guidance for software manufacturers?","fr":"Lequel des énoncés suivants est l’un des trois principes des orientations Secure by Design de la CISA destinées aux fabricants de logiciels?"},"options":{"en":["Shift security testing entirely to the customer's operations team","Certify every product against ISO/IEC 27001 before its release","Require customers to enable multi-factor authentication themselves","Take ownership of customer security outcomes"],"fr":["Transférer entièrement les tests de sécurité à l’équipe des opérations du client","Certifier chaque produit selon la norme ISO/IEC 27001 avant sa mise en marché","Exiger que les clients activent eux-mêmes l’authentification multifacteur","Assumer la responsabilité des résultats de sécurité des clients"]}},{"n":8,"answer":"B","section":{"en":"Enterprise architecture frameworks and security architecture","fr":"Cadres d’architecture d’entreprise et architecture de sécurité"},"q":{"en":"A Canadian firm already uses TOGAF for enterprise architecture. According to the chapter, how should it handle security architecture?","fr":"Une entreprise canadienne utilise déjà TOGAF pour l’architecture d’entreprise. Selon le chapitre, comment devrait-elle traiter l’architecture de sécurité?"},"options":{"en":["Create a separate security architecture method running in parallel with TOGAF","Embed security requirements, threat analysis, and risk acceptance in relevant ADM phases","Replace TOGAF entirely with SABSA because SABSA is specific to security","Adopt Open Security Architecture patterns untailored to save design time"],"fr":["Créer une méthode distincte d’architecture de sécurité menée en parallèle avec TOGAF","Intégrer les exigences de sécurité, l’analyse des menaces et l’acceptation du risque aux phases pertinentes de l’ADM","Remplacer entièrement TOGAF par SABSA, parce que SABSA est propre à la sécurité","Adopter sans adaptation les patrons d’Open Security Architecture pour gagner du temps de conception"]}},{"n":9,"answer":"A","section":{"en":"Enterprise architecture frameworks and security architecture","fr":"Cadres d’architecture d’entreprise et architecture de sécurité"},"q":{"en":"What is the main managerial benefit of SABSA's business attributes profiling?","fr":"Quel est le principal avantage, pour la gestion, du profilage des attributs d’affaires de SABSA?"},"options":{"en":["Two-way traceability between business attributes and architectural elements","A maturity scale from Traditional to Optimal for each security domain","A catalogue of observed adversary techniques grounded in real behaviour","A machine-readable format for checking configuration compliance at scale"],"fr":["Une traçabilité dans les deux sens entre les attributs d’affaires et les éléments architecturaux","Une échelle de maturité allant de Traditionnel à Optimal pour chaque domaine de sécurité","Un catalogue des techniques d’adversaires observées, ancré dans des comportements réels","Un format lisible par machine pour vérifier à grande échelle la conformité des configurations"]}},{"n":10,"answer":"C","section":{"en":"Enterprise architecture frameworks and security architecture","fr":"Cadres d’architecture d’entreprise et architecture de sécurité"},"q":{"en":"Why does the chapter warn against adopting an external security pattern without tailoring it?","fr":"Pourquoi le chapitre met-il en garde contre l’adoption d’un patron de sécurité externe sans l’adapter?"},"options":{"en":["External patterns are rarely mapped to any recognized control framework","Creative Commons licences prohibit commercial organizations from using them","It becomes compliance theatre if no one checks it addresses actual scenarios","Auditors refuse to accept patterns that were not developed internally"],"fr":["Les patrons externes sont rarement mis en correspondance avec un cadre de contrôles reconnu","Les licences Creative Commons interdisent leur utilisation par des organisations commerciales","Il devient de la conformité de façade si personne ne vérifie qu’il répond aux scénarios réels","Les auditeurs refusent d’accepter les patrons qui n’ont pas été élaborés à l’interne"]}},{"n":11,"answer":"B","section":{"en":"The seven architectural pillars","fr":"Les sept piliers architecturaux"},"q":{"en":"Why is resilience architecture shown as the foundation of the seven architectural pillars?","fr":"Pourquoi l’architecture de résilience est-elle présentée comme le fondement des sept piliers architecturaux?"},"options":{"en":["It is the cheapest pillar and should therefore always be completed first","It is the pillar that assumes the other pillars will sometimes fail","It is the only pillar that maps directly to NIST CSF 2.0 outcomes","It replaces the need for segmentation in cloud-native environments"],"fr":["C’est le pilier le moins coûteux, qui devrait donc toujours être réalisé en premier","C’est le pilier qui suppose que les autres piliers feront parfois défaut","C’est le seul pilier qui correspond directement aux résultats du NIST CSF 2.0","Il rend la segmentation inutile dans les environnements infonuagiques natifs"]}},{"n":12,"answer":"D","section":{"en":"The seven architectural pillars","fr":"Les sept piliers architecturaux"},"q":{"en":"An organization decides to defer its segmentation program by one year. What does the chapter say it should do?","fr":"Une organisation décide de reporter d’un an son programme de segmentation. Que devrait-elle faire, selon le chapitre?"},"options":{"en":["Nothing, because segmentation is an optional refinement in modern designs","Suspend identity improvements until segmentation can be funded with them","Treat the deferral as an operational matter for the network team alone","Record the decision and raise the importance of identity and detection coverage"],"fr":["Rien, parce que la segmentation est un raffinement facultatif dans les conceptions modernes","Suspendre les améliorations de l’identité jusqu’à ce que la segmentation puisse être financée avec elles","Traiter le report comme une question opérationnelle relevant de la seule équipe réseau","Consigner la décision et accroître l’importance de l’identité et de la couverture de détection"]}},{"n":13,"answer":"D","section":{"en":"Pillars that sustain trust: baselines, keys, logs, and recovery","fr":"Les piliers qui préservent la confiance : bases de référence, clés, journaux et reprise"},"q":{"en":"A firm mandates encryption across all systems but does not manage the key life cycle. What is the chapter's main concern?","fr":"Une entreprise impose le chiffrement dans tous ses systèmes, mais ne gère pas le cycle de vie des clés. Quelle est la principale préoccupation du chapitre?"},"options":{"en":["Encryption will slow application performance below acceptable thresholds","Regulators prohibit encryption unless the customer holds all keys","Post-quantum algorithms will immediately make the encryption useless","Hidden fragility: it may be unable to recover its own data in an incident"],"fr":["Le chiffrement ralentira les applications sous les seuils de performance acceptables","Les organismes de réglementation interdisent le chiffrement à moins que le client détienne toutes les clés","Les algorithmes post-quantiques rendront immédiatement le chiffrement inutile","Une fragilité cachée : elle pourrait être incapable de récupérer ses propres données lors d’un incident"]}},{"n":14,"answer":"B","section":{"en":"Technical debt as cybersecurity risk","fr":"La dette technique comme risque de cybersécurité"},"q":{"en":"According to the chapter, what is the first governance step for significant security debt?","fr":"Selon le chapitre, quelle est la première étape de gouvernance pour une dette de sécurité importante?"},"options":{"en":["Add it to the engineering backlog for the next delivery sprint","Record it in the risk register, described in scenario terms","Defer it until the affected systems reach their end of support","Report it to the external auditor as a control deficiency"],"fr":["L’ajouter au carnet de travail de l’ingénierie pour le prochain sprint de livraison","La consigner dans le registre des risques, décrite en termes de scénarios","La reporter jusqu’à ce que les systèmes touchés atteignent leur fin de soutien","La signaler à l’auditeur externe comme une déficience de contrôle"]}},{"n":15,"answer":"C","section":{"en":"Zero trust architecture as a governance concept","fr":"L’architecture à vérification systématique en tant que concept de gouvernance"},"q":{"en":"What is the central shift introduced by NIST SP 800-207, Zero Trust Architecture?","fr":"Quel est le changement central introduit par la publication NIST SP 800-207, Zero Trust Architecture?"},"options":{"en":["Replacing perimeter firewalls with a single access broker product","Requiring all employees to work only from the corporate network","Abandoning implicit trust based on network location","Encrypting all data at rest with customer-held keys"],"fr":["Remplacer les pare-feu de périmètre par un seul produit de courtage d’accès","Exiger que tout le personnel travaille uniquement à partir du réseau de l’entreprise","Abandonner la confiance implicite fondée sur l’emplacement dans le réseau","Chiffrer toutes les données au repos avec des clés détenues par le client"]}},{"n":16,"answer":"A","section":{"en":"Zero trust architecture as a governance concept","fr":"L’architecture à vérification systématique en tant que concept de gouvernance"},"q":{"en":"An organization reaches Advanced maturity in the CISA ZTMM identity pillar while its data pillar remains Initial. How does the chapter view this?","fr":"Une organisation atteint la maturité Avancé dans le pilier Identité du ZTMM de la CISA, alors que son pilier Données demeure au stade Initial. Comment le chapitre considère-t-il cette situation?"},"options":{"en":["Acceptable if the choice is deliberate, tied to risk scenarios, and recorded","Unacceptable, because all pillars must advance in lockstep each year","Sufficient to declare the organization a zero trust organization","Evidence that the Governance capability can safely be matured later"],"fr":["Acceptable si le choix est délibéré, lié à des scénarios de risque et consigné","Inacceptable, parce que tous les piliers doivent progresser au même rythme chaque année","Suffisante pour déclarer que l’organisation applique la vérification systématique","La preuve que la capacité Gouvernance peut sans danger mûrir plus tard"]}},{"n":17,"answer":"A","section":{"en":"Threat modelling as a managerial control","fr":"La modélisation des menaces en tant que contrôle de gestion"},"q":{"en":"Which threat modelling method applies a structured approach specifically to privacy threats, making it useful alongside Law 25 privacy impact assessments?","fr":"Quelle méthode de modélisation des menaces applique une démarche structurée précisément aux menaces pour la vie privée, ce qui la rend utile en complément des évaluations des facteurs relatifs à la vie privée exigées par la Loi 25?"},"options":{"en":["LINDDUN","STRIDE","PASTA","MITRE ATT&CK"],"fr":["LINDDUN","STRIDE","PASTA","MITRE ATT&CK"]}},{"n":18,"answer":"D","section":{"en":"Threat modelling as a managerial control","fr":"La modélisation des menaces en tant que contrôle de gestion"},"q":{"en":"A team performs a one-hour threat model for a low-impact internal tool but a deep, documented analysis for its payment platform. Which property of governable threat modelling does this illustrate?","fr":"Une équipe réalise une modélisation des menaces d’une heure pour un outil interne à faible impact, mais une analyse approfondie et documentée pour sa plateforme de paiement. Quelle propriété d’une modélisation des menaces gouvernable cela illustre-t-il?"},"options":{"en":["Required","Evidenced","Connected","Proportionate"],"fr":["Obligatoire","Documentée","Reliée","Proportionnée"]}},{"n":19,"answer":"C","section":{"en":"Architecture governance: review boards, design authority, and decisions","fr":"Gouvernance de l’architecture : comités d’examen, autorité de conception et décisions"},"q":{"en":"What is the role of the architecture review board when a design cannot meet a security requirement?","fr":"Quel est le rôle du comité d’examen de l’architecture lorsqu’une conception ne peut pas satisfaire à une exigence de sécurité?"},"options":{"en":["Accept the residual risk on behalf of the business sponsor","Reject the project outright and cancel its remaining funding","Describe the resulting risk clearly for the accountable risk owner","Approve the design automatically when delivery is urgent"],"fr":["Accepter le risque résiduel au nom du promoteur d’affaires","Rejeter catégoriquement le projet et annuler le reste de son financement","Décrire clairement le risque qui en résulte pour le responsable du risque imputable","Approuver automatiquement la conception lorsque la livraison est urgente"]}},{"n":20,"answer":"B","section":{"en":"Measuring architecture and aligning with standards","fr":"Mesurer l’architecture et l’aligner sur les normes"},"q":{"en":"A hypothetical report shows segmentation coverage for clinical systems rising from 40% to 85%. What would make this most meaningful to a board?","fr":"Un rapport hypothétique montre que la couverture de segmentation des systèmes cliniques passe de 40 % à 85 %. Qu’est-ce qui rendrait cette donnée la plus significative pour un conseil d’administration?"},"options":{"en":["Expressing it as the number of firewall rules changed this quarter","Presenting it with the ransomware scenario it addresses and the estimated impact reduction","Comparing it with the number of design reviews conducted this year","Reporting it only to internal audit in its third-line role"],"fr":["L’exprimer en nombre de règles de pare-feu modifiées au cours du trimestre","La présenter avec le scénario de rançongiciel qu’elle traite et la réduction estimée de son impact","La comparer au nombre d’examens de conception effectués au cours de l’année","La communiquer uniquement à l’audit interne, dans son rôle de troisième ligne"]}}]},{"n":14,"title":{"en":"Chapter 14: Security Baselines and Configuration Governance","fr":"Chapitre 14 : Bases de référence de sécurité et gouvernance de la configuration"},"questions":[{"n":1,"answer":"C","section":{"en":"Core concepts: baselines, hardening, drift, and secure-by-default","fr":"Concepts de base : bases de référence, durcissement, dérive et sécurité par défaut"},"q":{"en":"Which statement best defines a security baseline as the chapter uses the term?","fr":"Quel énoncé définit le mieux une base de référence de sécurité au sens où le chapitre emploie ce terme?"},"options":{"en":["A vendor's recommended settings for a typical customer's environment","An aspirational guide describing good configuration practices","A documented, approved minimum secure configuration for a class of systems","The recorded, approved state of one particular system under change control"],"fr":["Les paramètres recommandés par un fournisseur pour l’environnement d’un client type","Un guide idéal qui décrit de bonnes pratiques de configuration","Une configuration sécurisée minimale documentée et approuvée pour une catégorie de systèmes","L’état consigné et approuvé d’un système particulier sous contrôle des changements"]}},{"n":2,"answer":"A","section":{"en":"Core concepts: baselines, hardening, drift, and secure-by-default","fr":"Résumé du chapitre"},"q":{"en":"What is configuration drift?","fr":"Qu’est-ce que la dérive de configuration?"},"options":{"en":["The gradual divergence between the intended baseline and the actual deployed state","The planned migration of systems from one baseline version to the next","The difference in strictness between CIS Level 1 and Level 2 profiles","The process of adapting an external benchmark to local constraints"],"fr":["L’écart progressif entre la base de référence prévue et l’état réellement déployé","La migration planifiée des systèmes d’une version de base de référence à la suivante","La différence de rigueur entre les profils de niveau 1 et de niveau 2 du CIS","Le processus d’adaptation d’un référentiel externe aux contraintes locales"]}},{"n":3,"answer":"D","section":{"en":"Core concepts: baselines, hardening, drift, and secure-by-default","fr":"Concepts de base : bases de référence, durcissement, dérive et sécurité par défaut"},"q":{"en":"A manager reports that 'all production servers meet the hardening standard' because they were built from approved images. Why can this statement not be supported?","fr":"Un gestionnaire affirme que « tous les serveurs de production respectent la norme de durcissement » parce qu’ils ont été construits à partir d’images approuvées. Pourquoi cet énoncé ne peut-il pas être étayé?"},"options":{"en":["It overstates the number of servers in the production environment","It relies on the wrong external benchmark for server hardening","It is acceptable as long as every image used was a golden image","It describes how systems were built, not how they are configured today"],"fr":["Il surestime le nombre de serveurs de l’environnement de production","Il s’appuie sur le mauvais référentiel externe pour le durcissement des serveurs","Il est acceptable tant que chaque image utilisée était une image de référence","Il décrit la façon dont les systèmes ont été construits, et non leur configuration actuelle"]}},{"n":4,"answer":"B","section":{"en":"Why baselines are governance, not technical hygiene","fr":"Pourquoi les bases de référence relèvent de la gouvernance, et non de l’hygiène technique"},"q":{"en":"Which control, new in the 2022 edition, calls for configurations to be established, documented, implemented, monitored, and reviewed?","fr":"Quel contrôle, nouveau dans l’édition de 2022, exige que les configurations soient établies, documentées, mises en œuvre, surveillées et révisées?"},"options":{"en":["CIS Controls v8.1, Control 4","ISO/IEC 27002:2022, control 8.9","NIST CSF 2.0, outcome PR.PS-01","NIST SP 800-53 Rev. 5, CM-7"],"fr":["CIS Controls v8.1, Control 4","ISO/IEC 27002:2022, mesure 8.9","NIST CSF 2.0, résultat PR.PS-01","NIST SP 800-53 Rev. 5, CM-7"]}},{"n":5,"answer":"A","section":{"en":"Metrics and evidence: how managers know baseline governance works","fr":"Mesures et éléments probants : comment les gestionnaires savent que la gouvernance des bases de référence fonctionne"},"q":{"en":"Tier 1 baseline assessment coverage is 96%, and 99% of assessed assets are compliant. Using the chapter's illustrative KRIs, what should happen?","fr":"La couverture de l’évaluation des bases de référence de niveau 1 est de 96 %, et 99 % des actifs évalués sont conformes. Selon les ICR illustratifs du chapitre, que devrait-il se passer?"},"options":{"en":["Escalate, because coverage is below the illustrative 98% threshold","Take no action, because compliance is above 98% of assessed assets","Escalate only if a critical deviation stays open beyond 72 hours","Report the 99% compliance figure to the board as the headline"],"fr":["Faire remonter, parce que la couverture est inférieure au seuil illustratif de 98 %","Ne rien faire, parce que la conformité dépasse 98 % des actifs évalués","Faire remonter seulement si un écart critique reste ouvert plus de 72 heures","Présenter au conseil le taux de conformité de 99 % comme donnée principale"]}},{"n":6,"answer":"D","section":{"en":"The reference ecosystem: benchmarks, technical guides, and checklists","fr":"Conception des bases de référence : convertir l’appétence pour le risque en configurations sécurisées minimales"},"q":{"en":"An organization that is not subject to DISA STIGs wants to use them. What does the chapter recommend?","fr":"Une organisation qui n’est pas assujettie aux STIG de la DISA souhaite les utiliser. Que recommande le chapitre?"},"options":{"en":["Adopt them wholesale to achieve the highest possible security posture","Ignore them, because they apply only to U.S. Department of Defense systems","Replace CIS Benchmarks with them across the whole estate","Use them as a reference for high-assurance systems and as a cross-check"],"fr":["Les adopter intégralement pour atteindre la posture de sécurité la plus élevée possible","Les ignorer, parce qu’ils ne s’appliquent qu’aux systèmes du département de la Défense des États-Unis","Remplacer les CIS Benchmarks par ceux-ci dans l’ensemble du parc","Les utiliser comme référence pour les systèmes à haute assurance et comme vérification croisée"]}},{"n":7,"answer":"B","section":{"en":"The reference ecosystem: benchmarks, technical guides, and checklists","fr":"L’écosystème de référence : référentiels, guides techniques et listes de contrôle"},"q":{"en":"What is the main managerial principle embodied by SCAP and machine-readable configuration content?","fr":"Quel est le principal principe de gestion qu’incarnent le SCAP et le contenu de configuration lisible par machine?"},"options":{"en":["Every baseline should be re-encoded in each tool's own proprietary language","A machine-readable baseline can be checked automatically, continuously, and consistently across tools","Configuration checks should remain manual to avoid translation errors between tools","Only NIST may publish configuration checklists for IT products"],"fr":["Chaque base de référence devrait être recodée dans le langage propriétaire de chaque outil","Une base de référence lisible par machine peut être vérifiée automatiquement, en continu et de façon cohérente d’un outil à l’autre","Les vérifications de configuration devraient rester manuelles pour éviter les erreurs de traduction entre outils","Seul le NIST peut publier des listes de vérification de configuration pour les produits de TI"]}},{"n":8,"answer":"C","section":{"en":"Defining baseline scope: what should have a baseline","fr":"Définir la portée des bases de référence : ce qui devrait en avoir une"},"q":{"en":"Applying the chapter's blast-radius principle, which configuration domains belong near the top of the baseline scope ladder?","fr":"En appliquant le principe du rayon d’impact du chapitre, quels domaines de configuration se situent près du sommet de l’échelle de portée des bases de référence?"},"options":{"en":["Office desktops, because they are the most numerous asset class","Conference room equipment, because it is often forgotten by IT","The identity provider tenant and the deployment pipeline","Test servers, because their configuration changes most frequently"],"fr":["Les ordinateurs de bureau, parce qu’ils constituent la catégorie d’actifs la plus nombreuse","L’équipement des salles de conférence, parce qu’il est souvent oublié par les TI","Le locataire du fournisseur d’identité et la chaîne de déploiement","Les serveurs de test, parce que leur configuration change le plus souvent"]}},{"n":9,"answer":"D","section":{"en":"Defining baseline scope: what should have a baseline","fr":"Définir la portée des bases de référence : ce qui devrait en avoir une"},"q":{"en":"Why does the chapter consider coverage gaps more dangerous than known non-compliance?","fr":"Pourquoi le chapitre considère-t-il les lacunes de couverture comme plus dangereuses que la non-conformité connue?"},"options":{"en":["They always involve systems that store personal information","Auditors penalize them more heavily than any other finding","They are always more expensive to remediate than known deviations","They are invisible in every report the organization produces"],"fr":["Elles concernent toujours des systèmes qui stockent des renseignements personnels","Les auditeurs les sanctionnent plus sévèrement que toute autre constatation","Elles coûtent toujours plus cher à corriger que les écarts connus","Elles sont invisibles dans tous les rapports que produit l’organisation"]}},{"n":10,"answer":"B","section":{"en":"Baseline design: turning risk appetite into minimum secure configurations","fr":"Conception des bases de référence : convertir l’appétence pour le risque en configurations sécurisées minimales"},"q":{"en":"What is a key benefit of tiering baselines into foundation, enhanced, and high-assurance levels?","fr":"Quel est l’un des principaux avantages de répartir les bases de référence en niveaux fondamental, renforcé et haute assurance?"},"options":{"en":["It ensures the strictest settings apply to every system everywhere","It reduces exception volume because teams select a tier matching their system's classification","It removes the need for risk owners to approve any deviations","It lets each engineer choose the settings they prefer for their system"],"fr":["Cela garantit que les paramètres les plus stricts s’appliquent à tous les systèmes, partout","Cela réduit le volume d’exceptions, parce que les équipes choisissent le niveau correspondant à la classification de leur système","Cela élimine la nécessité pour les responsables du risque d’approuver les dérogations","Cela permet à chaque ingénieur de choisir les paramètres qu’il préfère pour son système"]}},{"n":11,"answer":"A","section":{"en":"Baseline design: turning risk appetite into minimum secure configurations","fr":"Conception des bases de référence : convertir l’appétence pour le risque en configurations sécurisées minimales"},"q":{"en":"A baseline states that 'appropriate logging shall be configured'. What is the main problem with this requirement?","fr":"Une base de référence indique qu’« une journalisation appropriée doit être configurée ». Quel est le principal problème de cette exigence?"},"options":{"en":["Compliance with it cannot be measured, so it is useless for governance","It is too strict for most systems and will generate many exceptions","It conflicts with the safeguards defined in CIS Control 4","It can be assessed only with SCAP-compatible scanning tools"],"fr":["Sa conformité ne peut pas être mesurée; elle est donc inutile pour la gouvernance","Elle est trop stricte pour la plupart des systèmes et générera de nombreuses exceptions","Elle entre en conflit avec les mesures de protection définies dans le CIS Control 4","Elle ne peut être évaluée qu’avec des outils d’analyse compatibles avec le SCAP"]}},{"n":12,"answer":"C","section":{"en":"Baseline design: turning risk appetite into minimum secure configurations","fr":"Conception des bases de référence : convertir l’appétence pour le risque en configurations sécurisées minimales"},"q":{"en":"Each baseline requirement should carry four attributes. Which attribute later drives remediation timelines and exception approval levels?","fr":"Chaque exigence de base de référence devrait comporter quatre attributs. Quel attribut détermine ensuite les délais de correction et les niveaux d’approbation des exceptions?"},"options":{"en":["The rationale or risk it addresses","The method of verification","The severity of non-compliance","The setting or outcome required"],"fr":["La justification ou le risque traité","La méthode de vérification","La gravité de la non-conformité","Le paramètre ou le résultat exigé"]}},{"n":13,"answer":"B","section":{"en":"Metrics and evidence: how managers know baseline governance works","fr":"Mesures et éléments probants : comment les gestionnaires savent que la gouvernance des bases de référence fonctionne"},"q":{"en":"In the CyberRiskGuardian method, how are configuration KRIs such as unreconciled console changes used?","fr":"Dans la méthode CyberRiskGuardian, comment les ICR de configuration, comme les modifications de console non rapprochées, sont-ils utilisés?"},"options":{"en":["They automatically recalculate estimated risk at the end of each month","They are recorded as evidence to revisit Pb(ψ,A) and resilience θ at each review","They replace scenario assessment with measured compliance percentages","They set the organization's risk appetite and tolerance for the year"],"fr":["Ils recalculent automatiquement le risque estimé à la fin de chaque mois","Ils sont consignés comme éléments probants pour réexaminer Pb(ψ,A) et la résilience θ à chaque revue","Ils remplacent l’évaluation par scénarios par des pourcentages de conformité mesurés","Ils fixent l’appétence pour le risque et la tolérance de l’organisation pour l’année"]}},{"n":14,"answer":"A","section":{"en":"Baseline design: turning risk appetite into minimum secure configurations","fr":"Conception des bases de référence : convertir l’appétence pour le risque en configurations sécurisées minimales"},"q":{"en":"Under the chapter's split ownership model, who owns risk acceptance for baseline exceptions?","fr":"Dans le modèle de responsabilité partagée du chapitre, qui est responsable de l’acceptation du risque pour les exceptions aux bases de référence?"},"options":{"en":["Risk owners at the appropriate management level, within delegated authority","Platform and infrastructure teams that implement the baseline","The CISO or security architecture function that writes the content","Internal audit, as the independent third line of assurance"],"fr":["Les responsables du risque au niveau de direction approprié, dans les limites des pouvoirs délégués","Les équipes de plateforme et d’infrastructure qui mettent en œuvre la base de référence","Le CSI ou la fonction d’architecture de sécurité qui rédige le contenu","L’audit interne, en tant que troisième ligne indépendante d’assurance"]}},{"n":15,"answer":"C","section":{"en":"Secure-by-default deployment: making compliance automatic","fr":"Déploiement sécurisé par défaut : rendre la conformité automatique"},"q":{"en":"A golden image was hardened two years ago and has never been rebuilt. How does the chapter characterize it?","fr":"Une image de référence a été durcie il y a deux ans et n’a jamais été reconstruite. Comment le chapitre la qualifie-t-il?"},"options":{"en":["Still a golden image, provided it was formally approved","A candidate for immediate conversion to infrastructure as code","A template for deploying known vulnerabilities","Acceptable if it was based on a CIS hardened image"],"fr":["Toujours une image de référence, pourvu qu’elle ait été approuvée officiellement","Une candidate à une conversion immédiate en infrastructure en tant que code","Un modèle pour déployer des vulnérabilités connues","Acceptable si elle reposait sur une image durcie du CIS"]}},{"n":16,"answer":"D","section":{"en":"Secure-by-default deployment: making compliance automatic","fr":"Déploiement sécurisé par défaut : rendre la conformité automatique"},"q":{"en":"What governance risk of policy as code does the chapter highlight?","fr":"Quel risque de gouvernance de la politique en tant que code le chapitre met-il en évidence?"},"options":{"en":["Policy rules cannot be placed under version control or review","Enforcement depends on how attentive individual reviewers are","Rules are ambiguous because they can partly pass or fail","Policy code can become a hidden governance layer only engineers can read"],"fr":["Les règles de politique ne peuvent pas être placées sous contrôle de version ni examinées","L’application dépend de l’attention de chaque examinateur","Les règles sont ambiguës parce qu’elles peuvent réussir ou échouer en partie","Le code de politique peut devenir une couche de gouvernance cachée que seuls les ingénieurs peuvent lire"]}},{"n":17,"answer":"C","section":{"en":"Change management and configuration control","fr":"Gestion du changement et contrôle de la configuration"},"q":{"en":"During an outage, an engineer opens a firewall rule using a break-glass account to restore service. According to the chapter, what would be the governance failure?","fr":"Pendant une panne, un ingénieur ouvre une règle de pare-feu au moyen d’un compte d’accès d’urgence pour rétablir le service. Selon le chapitre, où se situerait la défaillance de gouvernance?"},"options":{"en":["Making an emergency change during a production outage","Using a controlled break-glass account to act quickly","The absence of reconciliation and retrospective review afterwards","Logging every action taken with the break-glass account"],"fr":["Effectuer un changement d’urgence pendant une panne de production","Utiliser un compte d’accès d’urgence contrôlé pour agir rapidement","L’absence de rapprochement et de revue rétrospective par la suite","Journaliser chaque action effectuée avec le compte d’accès d’urgence"]}},{"n":18,"answer":"D","section":{"en":"Change management and configuration control","fr":"Gestion du changement et contrôle de la configuration"},"q":{"en":"A manager asks for the number of servers from the CMDB and from the cloud provider's API, and the numbers differ. What does the chapter say this difference represents?","fr":"Un gestionnaire demande le nombre de serveurs selon la CMDB et selon l’API du fournisseur infonuagique, et les chiffres diffèrent. Selon le chapitre, que représente cette différence?"},"options":{"en":["An error in the cloud API, because the CMDB is always the authoritative record","A rounding issue that should be resolved by reporting the higher of the two numbers","Evidence that the posture management tool is faulty and should be replaced","The organization's blind spot: assets that one source of truth does not know about"],"fr":["Une erreur de l’API infonuagique, parce que la CMDB est toujours le registre faisant autorité","Un problème d’arrondi qu’il faut régler en présentant le plus élevé des deux chiffres","La preuve que l’outil de gestion de la posture est défectueux et devrait être remplacé","L’angle mort de l’organisation : des actifs qu’une source de vérité ne connaît pas"]}},{"n":19,"answer":"A","section":{"en":"Drift detection and remediation: keeping reality aligned with intent","fr":"La gouvernance de la configuration en pratique"},"q":{"en":"Which drift is most appropriate for automatic correction, according to the chapter?","fr":"Selon le chapitre, quelle dérive se prête le mieux à une correction automatique?"},"options":{"en":["Disabled audit logging on a sensitive data store","A non-compliant screen-lock timeout on a kiosk","An approved emergency fix not yet recorded","Every deviation, regardless of production impact"],"fr":["La journalisation d’audit désactivée sur un dépôt de données sensibles","Un délai de verrouillage d’écran non conforme sur une borne","Un correctif d’urgence approuvé qui n’a pas encore été consigné","Tout écart, quel que soit son impact sur la production"]}},{"n":20,"answer":"B","section":{"en":"Configuration governance in practice","fr":"La gouvernance de la configuration en pratique"},"q":{"en":"Ridgeview Credit Union's board saw '95% configuration compliance' before the incident. What was the fundamental flaw in that figure?","fr":"Avant l’incident, le conseil de Ridgeview Credit Union voyait une « conformité de configuration de 95 % ». Quel était le défaut fondamental de ce chiffre?"},"options":{"en":["CIS Level 1 benchmarks are too weak to support any compliance claim","It covered only on-premises servers and workstations, so coverage was presented as compliance","The figure was calculated incorrectly by the posture management tool","The posture tool failed to detect the public storage container"],"fr":["Les référentiels CIS de niveau 1 sont trop faibles pour étayer toute affirmation de conformité","Il ne couvrait que les serveurs et les postes de travail sur place; la couverture était donc présentée comme de la conformité","Le chiffre avait été mal calculé par l’outil de gestion de la posture","L’outil de posture n’avait pas détecté le conteneur de stockage public"]}}]},{"n":15,"title":{"en":"Chapter 15: Cloud Cybersecurity","fr":"Chapitre 15 : Cybersécurité infonuagique"},"questions":[{"n":1,"answer":"D","section":{"en":"Chapter summary","fr":"Résumé du chapitre"},"q":{"en":"What does the chapter identify as the central governance problem of cloud adoption?","fr":"Selon le chapitre, quel est le problème de gouvernance central de l’adoption du nuage?"},"options":{"en":["Provider infrastructure is generally less secure than on-premises data centres","Cloud removes the need for vendor management and contractual oversight","Cloud costs grow unpredictably and cannot be governed by finance","Cloud redistributes control without redistributing accountability"],"fr":["L’infrastructure des fournisseurs est généralement moins sûre que les centres de données sur place","Le nuage élimine la nécessité de gérer les fournisseurs et d’encadrer les contrats","Les coûts infonuagiques croissent de façon imprévisible et ne peuvent pas être gouvernés par les finances","Le nuage redistribue le contrôle sans redistribuer l’imputabilité"]}},{"n":2,"answer":"B","section":{"en":"Cloud computing: service models and deployment models","fr":"L’infonuagique : modèles de service et modèles de déploiement"},"q":{"en":"Which NIST SP 800-145 essential characteristic most directly explains the appearance of cloud sprawl and shadow IT?","fr":"Quelle caractéristique essentielle de la publication NIST SP 800-145 explique le plus directement l’apparition de la prolifération infonuagique et des TI fantômes?"},"options":{"en":["Resource pooling","On-demand self-service","Measured service","Rapid elasticity"],"fr":["La mise en commun des ressources","Le libre-service à la demande","Le service mesuré","L’élasticité rapide"]}},{"n":3,"answer":"C","section":{"en":"Virtualization and containers: the foundation and the concentration of risk","fr":"Virtualisation et conteneurs : le fondement et la concentration du risque"},"q":{"en":"As an organization moves from virtual machines to containers to serverless functions, what happens to the customer's security responsibilities?","fr":"À mesure qu’une organisation passe des machines virtuelles aux conteneurs, puis aux fonctions sans serveur, qu’advient-il des responsabilités de sécurité du client?"},"options":{"en":["They disappear, because the provider runs the code on demand","Identity and permissions become far less important than before","The customer configures less, but what remains becomes proportionally more important","The provider becomes accountable for the customer's data and flows"],"fr":["Elles disparaissent, parce que le fournisseur exécute le code à la demande","L’identité et les autorisations deviennent beaucoup moins importantes qu’auparavant","Le client configure moins, mais ce qui reste gagne proportionnellement en importance","Le fournisseur devient imputable des données et des flux du client"]}},{"n":4,"answer":"A","section":{"en":"What actually changes in the cloud: the risk profile","fr":"Résumé du chapitre"},"q":{"en":"Why does the chapter describe the management plane as the dominant cloud attack surface?","fr":"Pourquoi le chapitre décrit-il le plan de gestion comme la principale surface d’attaque infonuagique?"},"options":{"en":["It is reachable from anywhere through consoles and APIs and protected chiefly by identity","Provider encryption and isolation are routinely defeated by attackers","Hypervisor exploits are the most common cause of cloud incidents","The data plane produces no logs that defenders could use"],"fr":["Il est accessible de partout au moyen de consoles et d’API et protégé surtout par l’identité","Les attaquants déjouent couramment le chiffrement et l’isolement des fournisseurs","Les codes d’exploitation visant les hyperviseurs sont la cause la plus fréquente des incidents infonuagiques","Le plan de données ne produit aucun journal utilisable par les défenseurs"]}},{"n":5,"answer":"B","section":{"en":"The shared responsibility model as a governance instrument","fr":"Le modèle de responsabilité partagée comme instrument de gouvernance"},"q":{"en":"Regardless of the service model, which security responsibility always remains with the customer?","fr":"Quel que soit le modèle de service, quelle responsabilité de sécurité demeure toujours celle du client?"},"options":{"en":["Physical security of the provider's data centres","Its data, identities and access decisions, and how it configures services","Security of the virtualization layer and underlying hardware","Operating system patching for every service it consumes"],"fr":["La sécurité physique des centres de données du fournisseur","Ses données, ses identités et ses décisions d’accès, ainsi que la configuration des services","La sécurité de la couche de virtualisation et du matériel sous-jacent","L’application des correctifs au système d’exploitation de chaque service consommé"]}},{"n":6,"answer":"C","section":{"en":"The shared responsibility model as a governance instrument","fr":"Établir une base de référence des contrôles de sécurité infonuagique : une méthode pratique et reproductible"},"q":{"en":"An executive argues that moving to SaaS means the organization's cyber risk has narrowed along with its responsibilities. How does the chapter respond?","fr":"Un dirigeant soutient que le passage au SaaS signifie que le cyberrisque de l’organisation s’est réduit en même temps que ses responsabilités. Que répond le chapitre?"},"options":{"en":["It agrees, because the provider controls most of the technology stack","It agrees, provided the provider holds an ISO/IEC 27001 certificate","It disagrees: the data, workforce identities, and sharing settings remain the customer's","It disagrees, because SaaS providers are not covered by assurance reports"],"fr":["Il est d’accord, parce que le fournisseur contrôle la majeure partie de la pile technologique","Il est d’accord, pourvu que le fournisseur détienne une certification ISO/IEC 27001","Il n’est pas d’accord : les données, les identités du personnel et les paramètres de partage restent ceux du client","Il n’est pas d’accord, parce que les fournisseurs SaaS ne sont pas visés par des rapports d’assurance"]}},{"n":7,"answer":"A","section":{"en":"The shared responsibility model as a governance instrument","fr":"Le modèle de responsabilité partagée comme instrument de gouvernance"},"q":{"en":"Under OSFI Guideline B-10, what is the position of a federally regulated financial institution that outsources a service to a cloud provider?","fr":"Selon la ligne directrice B-10 du BSIF, quelle est la position d’une institution financière fédérale qui impartit un service à un fournisseur infonuagique?"},"options":{"en":["It remains accountable for the activities it outsources","Accountability transfers to the provider under the contract","Accountability is split equally between the institution and provider","Accountability applies only to IaaS, not to SaaS arrangements"],"fr":["Elle demeure imputable des activités qu’elle impartit","L’imputabilité passe au fournisseur en vertu du contrat","L’imputabilité est partagée également entre l’institution et le fournisseur","L’imputabilité ne s’applique qu’à l’IaaS, et non aux ententes SaaS"]}},{"n":8,"answer":"D","section":{"en":"The shared responsibility model as a governance instrument","fr":"Le modèle de responsabilité partagée comme instrument de gouvernance"},"q":{"en":"In a provider's SOC 2 Type II report, what are complementary user entity controls, and what should the customer do with them?","fr":"Dans le rapport SOC 2 de type II d’un fournisseur, que sont les contrôles complémentaires chez l’entité utilisatrice, et que devrait en faire le client?"},"options":{"en":["Controls the auditor tested at the provider, to be filed as evidence","Subservice organizations excluded from scope through the carve-out method","Exceptions the auditor found, to be raised with the provider's management","Controls the customer must operate, to be mapped to named internal owners"],"fr":["Des contrôles que l’auditeur a testés chez le fournisseur, à classer comme éléments probants","Des sous-traitants exclus de la portée selon la méthode d’exclusion (carve-out)","Des exceptions relevées par l’auditeur, à soulever auprès de la direction du fournisseur","Des contrôles que le client doit exploiter, à attribuer à des responsables internes désignés"]}},{"n":9,"answer":"C","section":{"en":"The cloud governance operating model","fr":"Le modèle opérationnel de gouvernance infonuagique"},"q":{"en":"What is the purpose of a cloud centre of excellence, according to the chapter?","fr":"Selon le chapitre, quelle est la raison d’être d’un centre d’excellence infonuagique?"},"options":{"en":["To approve every cloud change before it reaches production","To accept residual risk on behalf of each workload's business owner","To make the secure way the easy way by setting standards and building platforms","To replace the organization's existing governance bodies for cloud matters"],"fr":["Approuver chaque changement infonuagique avant sa mise en production","Accepter le risque résiduel au nom du responsable métier de chaque charge de travail","Faire de la façon sécurisée la façon facile en établissant des normes et en construisant des plateformes","Remplacer les instances de gouvernance existantes de l’organisation pour les questions infonuagiques"]}},{"n":10,"answer":"A","section":{"en":"Building a cloud security controls baseline: a practical, repeatable method","fr":"Établir une base de référence des contrôles de sécurité infonuagique : une méthode pratique et reproductible"},"q":{"en":"At Laurentide Mutual, the top scenario was administrator compromise via a help-desk reset, followed by deletion of production data and backups. Which treatment most directly limits the backup deletion?","fr":"Chez Laurentide Mutual, le scénario prioritaire était la compromission d’un administrateur par une réinitialisation faite par le centre d’assistance, suivie de la suppression des données de production et des sauvegardes. Quel traitement limite le plus directement la suppression des sauvegardes?"},"options":{"en":["Immutable backups in a separate account with independent credentials","An SSPM review of the collaboration suite against the CIS benchmark","A guardrail restricting resource creation to Canadian regions","A quarterly cloud governance report to the risk committee"],"fr":["Des sauvegardes immuables dans un compte distinct, avec des identifiants indépendants","Un examen SSPM de la suite de collaboration au regard du référentiel du CIS","Un garde-fou qui limite la création de ressources aux régions canadiennes","Un rapport trimestriel sur la gouvernance infonuagique au comité des risques"]}},{"n":11,"answer":"D","section":{"en":"The cloud governance operating model","fr":"Établir une base de référence des contrôles de sécurité infonuagique : une méthode pratique et reproductible"},"q":{"en":"A cloud policy automatically reverts any storage bucket that becomes publicly accessible. Which type of guardrail is this?","fr":"Une politique infonuagique annule automatiquement l’accès public de tout compartiment de stockage qui devient accessible au public. De quel type de garde-fou s’agit-il?"},"options":{"en":["Preventive","Detective","Exception","Corrective"],"fr":["Préventif","De détection","D’exception","Correctif"]}},{"n":12,"answer":"B","section":{"en":"The cloud governance operating model","fr":"Le modèle opérationnel de gouvernance infonuagique"},"q":{"en":"A cost-reduction initiative quietly shortens log retention and removes cross-region backup copies. How should this decision be treated?","fr":"Une initiative de réduction des coûts raccourcit discrètement la conservation des journaux et supprime les copies de sauvegarde interrégionales. Comment cette décision devrait-elle être traitée?"},"options":{"en":["As a routine FinOps optimization recorded in the billing report","As a risk acceptance decision to be made by the risk owner","As automatically acceptable whenever the savings exceed tooling cost","As a technical choice for the cloud centre of excellence alone"],"fr":["Comme une optimisation FinOps courante consignée dans le rapport de facturation","Comme une décision d’acceptation du risque à prendre par le responsable du risque","Comme automatiquement acceptable dès que les économies dépassent le coût des outils","Comme un choix technique relevant uniquement du centre d’excellence infonuagique"]}},{"n":13,"answer":"A","section":{"en":"Identity as the cloud control plane","fr":"L’identité comme plan de contrôle du nuage"},"q":{"en":"Which practice reflects the chapter's governance expectations for workload identities and secrets?","fr":"Quelle pratique reflète les attentes de gouvernance du chapitre pour les identités de charges de travail et les secrets?"},"options":{"en":["Prefer short-lived, platform-issued credentials and store secrets in a managed vault","Keep long-lived access keys in configuration files so automation stays reliable","Grant broad permissions by default to avoid outages caused by missing rights","Review non-human identities only when a human owner leaves the organization"],"fr":["Privilégier des identifiants de courte durée émis par la plateforme et conserver les secrets dans un coffre géré","Garder des clés d’accès de longue durée dans les fichiers de configuration pour fiabiliser l’automatisation","Accorder par défaut des autorisations étendues pour éviter les pannes dues à des droits manquants","N’examiner les identités non humaines que lorsqu’un responsable humain quitte l’organisation"]}},{"n":14,"answer":"C","section":{"en":"Misconfiguration and cloud posture management","fr":"Erreurs de configuration et gestion de la posture infonuagique"},"q":{"en":"A CSPM dashboard shows thousands of findings. According to the chapter, when does it become a security control?","fr":"Un tableau de bord CSPM affiche des milliers de constatations. Selon le chapitre, quand devient-il un contrôle de sécurité?"},"options":{"en":["When the tool detects more findings than in the previous quarter","When the organization upgrades from CSPM to a full CNAPP platform","When findings go to owners with targets and critical ones trigger immediate response","When raw finding counts are reported to the board each month"],"fr":["Lorsque l’outil détecte plus de constatations qu’au trimestre précédent","Lorsque l’organisation passe du CSPM à une plateforme CNAPP complète","Lorsque les constatations sont transmises à des responsables avec des cibles et que les critiques déclenchent une intervention immédiate","Lorsque le nombre brut de constatations est présenté au conseil chaque mois"]}},{"n":15,"answer":"D","section":{"en":"SaaS security posture and SaaS sprawl","fr":"Posture de sécurité SaaS et prolifération des applications SaaS"},"q":{"en":"Why do SaaS-to-SaaS OAuth integrations create a distinct and growing risk?","fr":"Pourquoi les intégrations OAuth entre applications SaaS créent-elles un risque distinct et croissant?"},"options":{"en":["Their tokens expire whenever the user changes the account password","They can grant access only to basic profile information","Each SaaS vendor reviews every token granted to third parties","They can give broad, persistent access that survives password changes and is rarely reviewed"],"fr":["Leurs jetons expirent chaque fois que l’utilisateur change le mot de passe de son compte","Elles ne peuvent donner accès qu’aux renseignements de profil de base","Chaque fournisseur SaaS examine tous les jetons accordés à des tiers","Elles peuvent donner un accès étendu et persistant qui survit aux changements de mot de passe et est rarement examiné"]}},{"n":16,"answer":"B","section":{"en":"Data protection, residency, and sovereignty in the cloud","fr":"Protection, résidence et souveraineté des données dans le nuage"},"q":{"en":"Data is stored in a Canadian region of a provider headquartered in another country. What does the chapter say about this arrangement?","fr":"Des données sont stockées dans une région canadienne d’un fournisseur dont le siège se trouve dans un autre pays. Que dit le chapitre de cet arrangement?"},"options":{"en":["Only Canadian law can apply because residency determines jurisdiction","The data may still face lawful-access demands under the provider's home-country laws","The arrangement is exempt from Law 25's privacy impact assessment rules","The data cannot be encrypted with customer-managed keys in that region"],"fr":["Seul le droit canadien peut s’appliquer, parce que la résidence détermine la compétence","Les données peuvent tout de même faire l’objet de demandes d’accès légal en vertu des lois du pays d’origine du fournisseur","L’arrangement est soustrait aux règles de la Loi 25 sur l’évaluation des facteurs relatifs à la vie privée","Les données ne peuvent pas être chiffrées avec des clés gérées par le client dans cette région"]}},{"n":17,"answer":"D","section":{"en":"Data protection, residency, and sovereignty in the cloud","fr":"Protection, résidence et souveraineté des données dans le nuage"},"q":{"en":"What does Québec's Law 25 require before personal information is communicated outside Québec, including to a cloud provider?","fr":"Qu’exige la Loi 25 du Québec avant que des renseignements personnels soient communiqués à l’extérieur du Québec, y compris à un fournisseur infonuagique?"},"options":{"en":["A SOC 2 Type II report from the receiving cloud provider","A sovereign cloud arrangement located within the province","Encryption with keys held only by the enterprise itself","A privacy impact assessment and adequate protection of the information"],"fr":["Un rapport SOC 2 de type II du fournisseur infonuagique destinataire","Un arrangement de nuage souverain situé dans la province","Un chiffrement avec des clés détenues uniquement par l’entreprise","Une évaluation des facteurs relatifs à la vie privée et une protection adéquate des renseignements"]}},{"n":18,"answer":"A","section":{"en":"Logging, detection, and response in the cloud","fr":"Journalisation, détection et intervention dans le nuage"},"q":{"en":"Which logging design best ensures that evidence survives an attacker who gains administrative access to a workload account?","fr":"Quelle conception de la journalisation garantit le mieux que les éléments probants survivent à un attaquant qui obtient un accès administratif à un compte de charge de travail?"},"options":{"en":["Central logging account without workload write or delete rights, immutable storage, alerts on changes","Logs kept in each workload account so the application team can manage them","Data-access logging enabled everywhere regardless of volume and cost","Provider default settings and retention, which are designed for investigations"],"fr":["Un compte de journalisation central sans droit d’écriture ni de suppression pour les charges, un stockage immuable et des alertes sur les changements","Des journaux conservés dans chaque compte de charge de travail pour que l’équipe applicative les gère","La journalisation des accès aux données activée partout, quels que soient le volume et le coût","Les paramètres et la conservation par défaut du fournisseur, conçus pour les enquêtes"]}},{"n":19,"answer":"B","section":{"en":"Resilience, concentration risk, and exit strategy","fr":"Résilience, risque de concentration et stratégie de sortie"},"q":{"en":"What does ISO/IEC 27002:2022 control 5.23, Information security for use of cloud services, require organizations to establish?","fr":"Que la mesure 5.23 de l’ISO/IEC 27002:2022, Sécurité de l’information dans l’utilisation de services en nuage, exige-t-elle que les organisations établissent?"},"options":{"en":["Encryption of all cloud data using customer-held keys","Processes for the acquisition, use, management, and exit from cloud services","A multicloud architecture for every critical business service","An annual SOC 2 Type II report for each cloud provider used"],"fr":["Le chiffrement de toutes les données infonuagiques avec des clés détenues par le client","Des processus pour l’acquisition, l’utilisation, la gestion et la sortie des services infonuagiques","Une architecture multinuage pour chaque service d’affaires critique","Un rapport SOC 2 de type II annuel pour chaque fournisseur infonuagique utilisé"]}},{"n":20,"answer":"C","section":{"en":"Building a cloud security controls baseline: a practical, repeatable method","fr":"Établir une base de référence des contrôles de sécurité infonuagique : une méthode pratique et reproductible"},"q":{"en":"According to the chapter, what is the most common failure when organizations build a cloud security controls baseline using the seven-step method?","fr":"Selon le chapitre, quelle est la défaillance la plus courante lorsque les organisations bâtissent une base de référence des contrôles de sécurité infonuagique à l’aide de la méthode en sept étapes?"},"options":{"en":["Skipping the current-state inventory and starting with framework selection","Combining too many frameworks into a single control backbone","Stopping at step 5 with a document no pipeline enforces or dashboard measures","Defining more baseline tiers than the organization can manage"],"fr":["Sauter l’inventaire de l’état actuel et commencer par le choix d’un cadre","Combiner trop de cadres dans une seule ossature de contrôles","S’arrêter à l’étape 5 avec un document qu’aucune chaîne de déploiement n’applique et qu’aucun tableau de bord ne mesure","Définir plus de niveaux de base de référence que l’organisation ne peut en gérer"]}}]},{"n":16,"title":{"en":"Chapter 16: Data Protection and Privacy","fr":"Chapitre 16 : Protection des données et des renseignements personnels"},"questions":[{"n":1,"answer":"B","section":{"en":"The regulatory landscape: Québec, Canada, the EU, and beyond","fr":"Le paysage réglementaire : le Québec, le Canada, l’UE et au-delà"},"q":{"en":"Under Québec's Law 25, who is the person in charge of the protection of personal information by default?","fr":"En vertu de la Loi 25 du Québec, qui est, par défaut, la personne responsable de la protection des renseignements personnels?"},"options":{"en":["The chief information security officer","The person exercising the highest authority in the enterprise","A data protection officer registered with the CAI","The head of legal affairs or compliance"],"fr":["Le chef de la sécurité de l’information","La personne ayant la plus haute autorité au sein de l’entreprise","Un délégué à la protection des données inscrit auprès de la CAI","Le responsable des affaires juridiques ou de la conformité"]}},{"n":2,"answer":"D","section":{"en":"Core concepts: personal information, sensitivity, and the actors","fr":"Concepts fondamentaux : renseignements personnels, sensibilité et acteurs"},"q":{"en":"An analytics team replaces customer names with tokens but keeps a separate key that allows records to be re-linked. How should this dataset be treated?","fr":"Une équipe d’analytique remplace les noms des clients par des jetons, mais conserve une clé distincte qui permet de rattacher les enregistrements. Comment ce jeu de données doit-il être traité?"},"options":{"en":["As anonymized information outside the scope of privacy law","As public information once the key is encrypted","As commercial data governed only by confidentiality rules","As personal information still subject to privacy obligations"],"fr":["Comme des renseignements anonymisés, hors du champ d’application des lois sur la vie privée","Comme des renseignements publics une fois la clé chiffrée","Comme des données commerciales régies uniquement par des règles de confidentialité","Comme des renseignements personnels toujours soumis aux obligations en matière de vie privée"]}},{"n":3,"answer":"A","section":{"en":"Core concepts: personal information, sensitivity, and the actors","fr":"Concepts fondamentaux : renseignements personnels, sensibilité et acteurs"},"q":{"en":"According to the NIST Privacy Framework, how does privacy risk differ from cybersecurity risk?","fr":"Selon le NIST Privacy Framework, en quoi le risque d’atteinte à la vie privée diffère-t-il du risque de cybersécurité?"},"options":{"en":["Privacy risk arises from data processing that can cause problems for individuals","Privacy risk arises only from loss of confidentiality of personal records","Privacy risk is limited to breaches that require regulatory notification","Privacy risk concerns legal penalties, while security risk concerns attackers"],"fr":["Il découle d’un traitement de données susceptible de causer des problèmes aux personnes","Il découle uniquement d’une perte de confidentialité des dossiers personnels","Il se limite aux violations qui exigent un avis à un organisme de réglementation","Il concerne les sanctions juridiques, alors que le risque de sécurité concerne les attaquants"]}},{"n":4,"answer":"C","section":{"en":"Core concepts: personal information, sensitivity, and the actors","fr":"Concepts fondamentaux : renseignements personnels, sensibilité et acteurs"},"q":{"en":"A software-as-a-service provider hosts its customers' client files and also runs its own billing and marketing. What roles does it hold?","fr":"Un fournisseur de logiciel-service héberge les dossiers des clients de ses clients et gère aussi sa propre facturation et son propre marketing. Quels rôles assume-t-il?"},"options":{"en":["Controller for all data, because it operates the platform","Processor for all data, because it provides a service","Processor for customers' data and controller for its own billing and marketing data","Joint controller with each customer for every dataset"],"fr":["Responsable du traitement pour toutes les données, puisqu’il exploite la plateforme","Sous-traitant pour toutes les données, puisqu’il fournit un service","Sous-traitant pour les données de ses clients et responsable du traitement pour ses propres données de facturation et de marketing","Responsable conjoint du traitement avec chaque client pour chaque jeu de données"]}},{"n":5,"answer":"C","section":{"en":"The regulatory landscape: Québec, Canada, the EU, and beyond","fr":"Le paysage réglementaire : le Québec, le Canada, l’UE et au-delà"},"q":{"en":"Which Law 25 phase gave individuals a right to data portability in a structured, commonly used technological format?","fr":"Quelle phase de la Loi 25 a accordé aux personnes un droit à la portabilité des données dans un format technologique structuré et couramment utilisé?"},"options":{"en":["September 22, 2021","September 22, 2022","September 22, 2024","September 22, 2023"],"fr":["22 septembre 2021","22 septembre 2022","22 septembre 2024","22 septembre 2023"]}},{"n":6,"answer":"A","section":{"en":"The regulatory landscape: Québec, Canada, the EU, and beyond","fr":"Le paysage réglementaire : le Québec, le Canada, l’UE et au-delà"},"q":{"en":"An enterprise subject to Québec's private-sector law had worldwide turnover of $800 million in the preceding fiscal year. What is the maximum administrative monetary penalty the CAI could impose?","fr":"Une entreprise assujettie à la loi québécoise sur le secteur privé a réalisé un chiffre d’affaires mondial de 800 millions de dollars au cours de l’exercice précédent. Quelle est la sanction administrative pécuniaire maximale que la CAI pourrait imposer?"},"options":{"en":["$16 million","$10 million","$25 million","$32 million"],"fr":["16 millions de dollars","10 millions de dollars","25 millions de dollars","32 millions de dollars"]}},{"n":7,"answer":"D","section":{"en":"The regulatory landscape: Québec, Canada, the EU, and beyond","fr":"Le paysage réglementaire : le Québec, le Canada, l’UE et au-delà"},"q":{"en":"Under PIPEDA, how long must organizations keep records of all breaches of security safeguards?","fr":"En vertu de la LPRPDE, pendant combien de temps les organisations doivent-elles tenir un registre de toutes les atteintes aux mesures de sécurité?"},"options":{"en":["Five years after becoming aware","Until the OPC closes its review","Twelve months after notification","At least 24 months"],"fr":["Cinq ans après en avoir pris connaissance","Jusqu’à ce que le CPVP ferme son examen","Douze mois après la notification","Au moins 24 mois"]}},{"n":8,"answer":"B","section":{"en":"The regulatory landscape: Québec, Canada, the EU, and beyond","fr":"Le paysage réglementaire : le Québec, le Canada, l’UE et au-delà"},"q":{"en":"As of October 2026, what is the status of Bill C-36 according to the chapter?","fr":"Selon le chapitre, quel est l’état du projet de loi C-36 en octobre 2026?"},"options":{"en":["It is in force and has replaced PIPEDA's private-sector rules","It was introduced in June 2026 but not enacted, so PIPEDA still applies","It died on the Order Paper when Parliament was prorogued in 2025","It applies only to federally regulated banks and telecommunications firms"],"fr":["Il est en vigueur et a remplacé les règles de la LPRPDE pour le secteur privé","Il a été déposé en juin 2026 mais n’est pas adopté; la LPRPDE s’applique donc toujours","Il est mort au Feuilleton lors de la prorogation du Parlement en 2025","Il ne s’applique qu’aux banques et aux entreprises de télécommunications sous réglementation fédérale"]}},{"n":9,"answer":"A","section":{"en":"Data residency and cross-border transfers","fr":"Résidence des données et transferts transfrontaliers"},"q":{"en":"A Montréal company plans to host customer data in a data centre in Ontario. What does Québec's law require before the information is communicated?","fr":"Une entreprise montréalaise prévoit d’héberger les données de sa clientèle dans un centre de données en Ontario. Qu’exige la loi québécoise avant que les renseignements soient communiqués?"},"options":{"en":["A privacy impact assessment, because outside Québec includes the rest of Canada","No assessment, because Ontario is covered by federal privacy law","Only a notice to customers that data will be stored in Canada","Approval from the CAI before any interprovincial transfer"],"fr":["Une évaluation des facteurs relatifs à la vie privée, puisque l’extérieur du Québec inclut le reste du Canada","Aucune évaluation, puisque l’Ontario est couvert par la loi fédérale sur la vie privée","Seulement un avis aux clients indiquant que les données seront stockées au Canada","L’approbation de la CAI avant tout transfert interprovincial"]}},{"n":10,"answer":"C","section":{"en":"The regulatory landscape: Québec, Canada, the EU, and beyond","fr":"Prévention des pertes de données, surveillance et journalisation des renseignements personnels"},"q":{"en":"Under the GDPR, within what timeframe must a breach generally be notified to the supervisory authority?","fr":"En vertu du RGPD, dans quel délai une violation doit-elle généralement être notifiée à l’autorité de contrôle?"},"options":{"en":["Promptly, with no fixed deadline","As soon as feasible after harm is confirmed","Within 72 hours, where feasible","Within 30 days of discovery"],"fr":["Avec diligence, sans délai fixe","Dès que possible après la confirmation d’un préjudice","Dans les 72 heures, si possible","Dans les 30 jours suivant la découverte"]}},{"n":11,"answer":"B","section":{"en":"Retention, archiving, and deletion: ending the \"keep everything forever\" culture","fr":"Conservation, archivage et suppression : en finir avec la culture du « tout garder pour toujours »"},"q":{"en":"A project charter lists the retention period for a new customer database as to be determined. What is the chapter's view?","fr":"La charte d’un projet indique que la durée de conservation d’une nouvelle base de données clients est « à déterminer ». Quelle est la position du chapitre?"},"options":{"en":["It is acceptable until the first annual records review","It is a reliable predictor of indefinite retention and should not be approved","It is acceptable if the database is encrypted at rest","It is a records management issue outside the project's scope"],"fr":["C’est acceptable jusqu’à la première revue annuelle des documents","C’est un indicateur fiable d’une conservation indéfinie et le projet ne devrait pas être approuvé","C’est acceptable si la base de données est chiffrée au repos","C’est une question de gestion documentaire qui dépasse la portée du projet"]}},{"n":12,"answer":"D","section":{"en":"Data minimization and purpose limitation in practice","fr":"Minimisation des données et limitation des finalités en pratique"},"q":{"en":"Developers find that application logs record full request payloads, including customer details. Which minimization practice addresses this?","fr":"Des développeurs constatent que les journaux d’application consignent le contenu complet des requêtes, y compris les renseignements des clients. Quelle pratique de minimisation répond à ce problème?"},"options":{"en":["Segregation of sensitive attributes","Purpose-bound datasets","Lean collection interfaces","Minimal logging of content"],"fr":["La séparation des attributs sensibles","Des jeux de données liés à une finalité","Des interfaces de collecte épurées","Une journalisation minimale du contenu"]}},{"n":13,"answer":"D","section":{"en":"The regulatory landscape: Québec, Canada, the EU, and beyond","fr":"Le paysage réglementaire : le Québec, le Canada, l’UE et au-delà"},"q":{"en":"Under Québec's 2024 anonymization regulation, which step must an enterprise complete before treating information as anonymized?","fr":"En vertu du règlement québécois de 2024 sur l’anonymisation, quelle étape une entreprise doit-elle franchir avant de traiter un renseignement comme anonymisé?"},"options":{"en":["Encrypt the dataset with customer-managed keys","Obtain express consent from every person concerned","Notify the CAI and publish the anonymized dataset","Analyze re-identification risk under qualified supervision and keep a register"],"fr":["Chiffrer le jeu de données avec des clés gérées par le client","Obtenir le consentement exprès de chaque personne concernée","Aviser la CAI et publier le jeu de données anonymisé","Analyser le risque de réidentification sous la supervision d’une personne compétente et tenir un registre"]}},{"n":14,"answer":"B","section":{"en":"Encryption and key management as privacy controls","fr":"Le chiffrement et la gestion des clés comme contrôles de protection de la vie privée"},"q":{"en":"A cloud provider encrypts all customer data at rest by default with keys it manages. Against which threat does this mainly protect?","fr":"Un fournisseur infonuagique chiffre par défaut toutes les données de ses clients au repos avec des clés qu’il gère. Contre quelle menace cette mesure protège-t-elle principalement?"},"options":{"en":["Access by the provider's own administrators","Theft of physical storage media","An authorized user exporting records","An application compromised while data is decrypted"],"fr":["L’accès par les propres administrateurs du fournisseur","Le vol de supports de stockage physiques","L’exportation d’enregistrements par un utilisateur autorisé","Une application compromise pendant que les données sont déchiffrées"]}},{"n":15,"answer":"C","section":{"en":"Data loss prevention, monitoring, and logging for personal information","fr":"Le cycle de vie des données, colonne vertébrale de la gouvernance de la vie privée"},"q":{"en":"In the chapter's layered approach to data loss prevention, what should come first?","fr":"Dans l’approche par couches de la prévention des pertes de données présentée au chapitre, que faut-il mettre en place en premier?"},"options":{"en":["Hard blocks on all external sharing","A cloud access security broker deployment","Classification policies and labels for personal information","Pattern matching on card and social insurance numbers"],"fr":["Des blocages stricts de tout partage externe","Le déploiement d’un courtier de sécurité d’accès au nuage","Des politiques de classification et des étiquettes pour les renseignements personnels","La reconnaissance de motifs pour les numéros de carte et d’assurance sociale"]}},{"n":16,"answer":"A","section":{"en":"Privacy impact assessments: structuring privacy risk analysis","fr":"Le paysage réglementaire : le Québec, le Canada, l’UE et au-delà"},"q":{"en":"In a Québec privacy impact assessment, what does the proportionality analysis examine that a security assessment usually does not?","fr":"Dans une évaluation des facteurs relatifs à la vie privée au Québec, qu’examine l’analyse de proportionnalité qu’une évaluation de sécurité n’examine habituellement pas?"},"options":{"en":["Whether the processing is justified, minimally intrusive, and beneficial overall","Whether encryption and access controls meet the classification scheme","Whether the vendor holds ISO/IEC 27001 and SOC 2 Type II reports","Whether incident notification can be completed within 72 hours"],"fr":["Si le traitement est justifié, le moins intrusif possible et bénéfique dans l’ensemble","Si le chiffrement et les contrôles d’accès respectent le schéma de classification","Si le fournisseur détient une certification ISO/IEC 27001 et des rapports SOC 2 de type II","Si la notification d’incident peut être faite dans les 72 heures"]}},{"n":17,"answer":"A","section":{"en":"Privacy impact assessments: structuring privacy risk analysis","fr":"Évaluations des facteurs relatifs à la vie privée : structurer l’analyse du risque lié à la vie privée"},"q":{"en":"In the Chaudière scenario, why was the vendor's EU–U.S. Data Privacy Framework certification irrelevant to the assessment?","fr":"Dans la mise en situation de Chaudière, pourquoi la certification du fournisseur au Data Privacy Framework UE–États-Unis n’était-elle pas pertinente pour l’évaluation?"},"options":{"en":["Because the transfer was from Québec, so Québec's transfer analysis applied instead","Because the Data Privacy Framework had been invalidated by the courts","Because the vendor stored all primary data in Canada","Because ISO/IEC 27018 certification replaces any transfer mechanism"],"fr":["Parce que le transfert partait du Québec, de sorte que c’est l’analyse québécoise des transferts qui s’appliquait","Parce que le Data Privacy Framework avait été invalidé par les tribunaux","Parce que le fournisseur stockait toutes les données principales au Canada","Parce que la certification ISO/IEC 27018 remplace tout mécanisme de transfert"]}},{"n":18,"answer":"D","section":{"en":"Privacy impact assessments: structuring privacy risk analysis","fr":"Évaluations des facteurs relatifs à la vie privée : structurer l’analyse du risque lié à la vie privée"},"q":{"en":"In the Chaudière scenario, why did the residual risk decision go to the executive committee rather than the project team?","fr":"Dans la mise en situation de Chaudière, pourquoi la décision sur le risque résiduel a-t-elle été soumise au comité de direction plutôt qu’à l’équipe de projet?"},"options":{"en":["Because the CAI must approve all transfers outside Canada","Because the AI call-summary feature was classified as prohibited","Because the vendor refused to negotiate a written agreement","Because the appetite statement requires executive approval for moderate risks over 50,000 people"],"fr":["Parce que la CAI doit approuver tout transfert à l’extérieur du Canada","Parce que la fonction de résumé d’appels par IA était classée comme interdite","Parce que le fournisseur refusait de négocier une entente écrite","Parce que l’énoncé d’appétence exige l’approbation de la direction pour les risques modérés touchant plus de 50 000 personnes"]}},{"n":19,"answer":"C","section":{"en":"Turning privacy obligations into an ISMS and cloud-security reality","fr":"Traduire les obligations de protection de la vie privée dans la réalité du SGSI et de la sécurité infonuagique"},"q":{"en":"What changed with the 2025 edition of ISO/IEC 27701?","fr":"Qu’est-ce qui a changé avec l’édition 2025 de la norme ISO/IEC 27701?"},"options":{"en":["It merged with ISO/IEC 27018 into a single cloud privacy standard","It became mandatory for organizations subject to Law 25","It became a stand-alone standard certifiable without ISO/IEC 27001","It replaced ISO/IEC 29134 as the guide for impact assessments"],"fr":["Elle a fusionné avec l’ISO/IEC 27018 en une seule norme de protection de la vie privée infonuagique","Elle est devenue obligatoire pour les organisations assujetties à la Loi 25","Elle est devenue une norme autonome, certifiable sans l’ISO/IEC 27001","Elle a remplacé l’ISO/IEC 29134 comme guide des évaluations d’impact"]}},{"n":20,"answer":"B","section":{"en":"Operating model: roles, responsibilities, and evidence","fr":"Modèle opérationnel : rôles, responsabilités et éléments probants"},"q":{"en":"A privacy office spends most of its time completing PIAs for project teams and maintaining inventories that owners never consult. What is the main governance problem?","fr":"Un bureau de la protection de la vie privée consacre l’essentiel de son temps à remplir des EFVP pour les équipes de projet et à tenir des inventaires que les responsables ne consultent jamais. Quel est le principal problème de gouvernance?"},"options":{"en":["The privacy office should report to internal audit instead","The privacy office is doing first-line work and lacks capacity to challenge","Project teams should not participate in privacy impact assessments","Inventories should be maintained by the CISO rather than owners"],"fr":["Le bureau devrait plutôt relever de l’audit interne","Le bureau accomplit un travail de première ligne et n’a plus la capacité d’exercer une remise en question","Les équipes de projet ne devraient pas participer aux évaluations des facteurs relatifs à la vie privée","Les inventaires devraient être tenus par le CSI plutôt que par les responsables"]}}]},{"n":17,"title":{"en":"Chapter 17: Cybersecurity Economics and Investment Governance","fr":"Chapitre 17 : Économie de la cybersécurité et gouvernance des investissements"},"questions":[{"n":1,"answer":"C","section":{"en":"What cybersecurity investment is buying","fr":"Ce qu’achète l’investissement en cybersécurité"},"q":{"en":"Which of the following is one of the four outcomes that, according to the chapter, cybersecurity investment buys?","fr":"Lequel des énoncés suivants est l’un des quatre résultats que procure l’investissement en cybersécurité, selon le chapitre?"},"options":{"en":["Revenue growth from new security products","Higher maturity scores in audit reports","Survivability during and after disruption","Lower licence costs through vendor discounts"],"fr":["La croissance des revenus tirés de nouveaux produits de sécurité","Des scores de maturité plus élevés dans les rapports d’audit","La capacité de survie pendant et après une perturbation","Des coûts de licences réduits grâce aux remises des fournisseurs"]}},{"n":2,"answer":"A","section":{"en":"Evaluating managed services: buying outcomes rather than outsourcing responsibility","fr":"Évaluer les services gérés : acheter des résultats plutôt qu’impartir la responsabilité"},"q":{"en":"An organization signs a managed detection and response contract. Which statement best reflects the chapter's guidance on accountability?","fr":"Une organisation signe un contrat de détection et d’intervention gérées. Quel énoncé reflète le mieux les recommandations du chapitre en matière d’imputabilité?"},"options":{"en":["The organization still owns escalation thresholds, incident decision rights, and notification duties","Responsibility for detection and breach notification moves to the provider under contract","Accountability is shared equally between the provider and the organization's board","The provider's certifications make internal oversight of the service unnecessary"],"fr":["L’organisation demeure responsable des seuils de remontée, des droits décisionnels en cas d’incident et des obligations de déclaration","La responsabilité de la détection et de la déclaration des violations passe au fournisseur en vertu du contrat","L’imputabilité est partagée à parts égales entre le fournisseur et le conseil d’administration de l’organisation","Les certifications du fournisseur rendent inutile la surveillance interne du service"]}},{"n":3,"answer":"D","section":{"en":"What cybersecurity investment is buying","fr":"Ce qu’achète l’investissement en cybersécurité"},"q":{"en":"Under NIST CSF 2.0, which function contains the expectation that adequate resources be allocated commensurate with the cybersecurity risk strategy?","fr":"Dans le NIST CSF 2.0, quelle fonction contient l’attente selon laquelle des ressources suffisantes doivent être allouées en fonction de la stratégie de gestion des risques de cybersécurité?"},"options":{"en":["Identify","Protect","Respond","Govern"],"fr":["Identifier","Protéger","Répondre","Gouverner"]}},{"n":4,"answer":"B","section":{"en":"The core financial model: from incident scenarios to expected loss","fr":"Le modèle financier de base : des scénarios d’incident à la perte attendue"},"q":{"en":"A scenario has a single loss expectancy of $400,000 and is expected to occur about once every four years. What is its annualized loss expectancy?","fr":"Un scénario a une espérance de perte unitaire de 400 000 $ et devrait se produire environ une fois tous les quatre ans. Quelle est son espérance de perte annualisée?"},"options":{"en":["$40,000","$100,000","$160,000","$1,600,000"],"fr":["40 000 $","100 000 $","160 000 $","1 600 000 $"]}},{"n":5,"answer":"B","section":{"en":"Evaluating security tooling: total cost, consolidation, and platformization","fr":"Évaluer les outils de sécurité : coût total, consolidation et plateformisation"},"q":{"en":"Which risk does the chapter associate specifically with consolidating security tools onto a single vendor platform?","fr":"Quel risque le chapitre associe-t-il précisément au regroupement des outils de sécurité sur la plateforme d’un seul fournisseur?"},"options":{"en":["Higher integration costs from maintaining many separate consoles","Concentration risk, where one defect or compromise affects many controls","Loss of shared telemetry that would otherwise improve detection","Weaker training because analysts must learn more products"],"fr":["Des coûts d’intégration plus élevés pour maintenir de nombreuses consoles distinctes","Le risque de concentration, une seule défaillance ou compromission touchant de nombreux contrôles","La perte d’une télémétrie commune qui améliorerait autrement la détection","Une formation affaiblie parce que les analystes doivent apprendre plus de produits"]}},{"n":6,"answer":"D","section":{"en":"Beyond point estimates: FAIR, simulation, and loss exceedance curves","fr":"Au-delà des estimations ponctuelles : FAIR, simulation et courbes de dépassement des pertes"},"q":{"en":"What question does a loss exceedance curve answer that a single expected-loss number cannot?","fr":"À quelle question une courbe de dépassement des pertes répond-elle, alors qu’un montant unique de perte attendue ne le peut pas?"},"options":{"en":["What is the average annual loss across all scenarios","Which control has the highest return on security investment","Which threat actor is most likely to target the organization","How bad a bad year could be, and how likely that is"],"fr":["Quelle est la perte annuelle moyenne pour l’ensemble des scénarios","Quel contrôle a le meilleur rendement de l’investissement en sécurité","Quel acteur de menace est le plus susceptible de cibler l’organisation","À quel point une mauvaise année pourrait être mauvaise, et avec quelle probabilité"]}},{"n":7,"answer":"A","section":{"en":"Beyond point estimates: FAIR, simulation, and loss exceedance curves","fr":"Au-delà des estimations ponctuelles : FAIR, simulation et courbes de dépassement des pertes"},"q":{"en":"In the FAIR taxonomy, how is the term vulnerability defined?","fr":"Dans la taxonomie FAIR, comment le terme « vulnérabilité » est-il défini?"},"options":{"en":["The probability that a threat event becomes a loss event","A software flaw scored with the CVSS v4.0 calculator","The frequency with which threat agents contact an asset","The share of an asset's value lost in an incident"],"fr":["La probabilité qu’un événement de menace devienne un événement de perte","Une faille logicielle cotée avec le calculateur CVSS v4.0","La fréquence à laquelle les agents de menace entrent en contact avec un actif","La part de la valeur d’un actif perdue lors d’un incident"]}},{"n":8,"answer":"C","section":{"en":"Beyond point estimates: FAIR, simulation, and loss exceedance curves","fr":"Au-delà des estimations ponctuelles : FAIR, simulation et courbes de dépassement des pertes"},"q":{"en":"Under FAIR-CAM, patching and configuration management that prevent control drift belong to which control domain?","fr":"Selon FAIR-CAM, l’application des correctifs et la gestion de la configuration, qui empêchent la dérive des contrôles, relèvent de quel domaine de contrôle?"},"options":{"en":["Loss event control functions","Decision support control functions","Variance management control functions","Risk transfer control functions"],"fr":["Fonctions de contrôle des événements de perte","Fonctions de contrôle d’aide à la décision","Fonctions de contrôle de gestion des écarts","Fonctions de contrôle de transfert du risque"]}},{"n":9,"answer":"D","section":{"en":"Worked example: from scenarios to an investment decision","fr":"Exemple résolu : des scénarios à une décision d’investissement"},"q":{"en":"Boréal's Option B costs $25,000 per year and reduces S2's ALE from $80,000 to $24,000. What is its ROSI?","fr":"L’option B de Boréal coûte 25 000 $ par année et réduit l’ALE de S2 de 80 000 $ à 24 000 $. Quel est son ROSI?"},"options":{"en":["69%","96%","224%","124%"],"fr":["69 %","96 %","224 %","124 %"]}},{"n":10,"answer":"C","section":{"en":"Communicating cyber risk in financial terms","fr":"Communiquer le cyberrisque en termes financiers"},"q":{"en":"According to the chapter, how should a ransomware scenario be described in a board-level cyber risk narrative?","fr":"Selon le chapitre, comment un scénario de rançongiciel devrait-il être décrit dans un exposé sur le cyberrisque destiné au conseil d’administration?"},"options":{"en":["As a technical event, such as domain controller compromise","As a maturity gap against the NIST CSF 2.0 tiers","In operational terms, such as order management disabled for five days","As an industry average breach cost adjusted for company size"],"fr":["Comme un événement technique, par exemple la compromission d’un contrôleur de domaine","Comme un écart de maturité par rapport aux niveaux du NIST CSF 2.0","En termes opérationnels, par exemple la gestion des commandes paralysée pendant cinq jours","Comme un coût moyen de violation dans le secteur, ajusté à la taille de l’entreprise"]}},{"n":11,"answer":"A","section":{"en":"Worked example: from scenarios to an investment decision","fr":"Exemple résolu : des scénarios à une décision d’investissement"},"q":{"en":"Boréal's S3 cloud-exposure scenario has an expected loss of $150,000. Using the Gordon–Loeb sanity check, roughly what is the maximum investment that would not require special justification?","fr":"Le scénario S3 d’exposition infonuagique de Boréal présente une perte attendue de 150 000 $. Selon la vérification de vraisemblance de Gordon-Loeb, quel est approximativement l’investissement maximal qui n’exigerait pas de justification particulière?"},"options":{"en":["About $55,000","About $37,000","About $75,000","About $150,000"],"fr":["Environ 55 000 $","Environ 37 000 $","Environ 75 000 $","Environ 150 000 $"]}},{"n":12,"answer":"B","section":{"en":"Worked example: from scenarios to an investment decision","fr":"Exemple résolu : des scénarios à une décision d’investissement"},"q":{"en":"For Boréal's S1, Pb(A) = 0.80, Pb(ψ,A) = 0.25, CVSS = 8.7, δe = 0.60, δm = 0.90, μ(E) = 0.90, θ = 0.40, factor 1,000. What is the estimated risk Re?","fr":"Pour le scénario S1 de Boréal, Pb(A) = 0,80, Pb(ψ,A) = 0,25, CVSS = 8,7, δe = 0,60, δm = 0,90, μ(E) = 0,90, θ = 0,40, facteur 1 000. Quel est le risque estimé Re?"},"options":{"en":["About 1,566","About 2,936","About 1,174","About 3,524"],"fr":["Environ 1 566","Environ 2 936","Environ 1 174","Environ 3 524"]}},{"n":13,"answer":"A","section":{"en":"Worked example: from scenarios to an investment decision","fr":"Exemple résolu : des scénarios à une décision d’investissement"},"q":{"en":"S1 has Re = 2,936 and Rt = 1,566. Option A has a probability reduction of 0.40 and an impact reduction of 0.50. What are the residual risk, ratio, and verdict?","fr":"Pour S1, Re = 2 936 et Rt = 1 566. L’option A présente une réduction de la probabilité de 0,40 et une réduction de l’impact de 0,50. Quels sont le risque résiduel, le ratio et le verdict?"},"options":{"en":["2,349; 1.50; above tolerance","881; 0.56; below tolerance","1,468; 0.94; approximately at tolerance","2,055; 1.31; above tolerance"],"fr":["2 349; 1,50; au-dessus de la tolérance","881; 0,56; sous la tolérance","1 468; 0,94; approximativement à la tolérance","2 055; 1,31; au-dessus de la tolérance"]}},{"n":14,"answer":"D","section":{"en":"Worked example: from scenarios to an investment decision","fr":"Exemple résolu : des scénarios à une décision d’investissement"},"q":{"en":"In the CyberRiskGuardian cross-check, Options B and C2 cut expected loss by 70% and 50% but mitigate nothing in the index. Why?","fr":"Dans la vérification croisée avec CyberRiskGuardian, les options B et C2 réduisent la perte attendue de 70 % et de 50 %, mais n’atténuent rien dans l’indice. Pourquoi?"},"options":{"en":["Their CVSS scores were scored by equivalency and therefore excluded","Their ROSI was below the portfolio average of about 104%","Their scenarios were already below tolerance before treatment","Their impact reduction is zero, and the method multiplies the two reductions"],"fr":["Leurs scores CVSS ont été établis par équivalence et ont donc été exclus","Leur ROSI était inférieur à la moyenne du portefeuille, d’environ 104 %","Leurs scénarios étaient déjà sous la tolérance avant le traitement","Leur réduction de l’impact est nulle, et la méthode multiplie les deux réductions"]}},{"n":15,"answer":"C","section":{"en":"Worked example: from scenarios to an investment decision","fr":"Exemple résolu : des scénarios à une décision d’investissement"},"q":{"en":"S1's average damage is 0.75 and Boréal's appetite is 0.40. What minimum product of probability and impact reductions brings S1's residual risk down to the tolerated level?","fr":"Le dommage moyen de S1 est de 0,75 et l’appétence de Boréal est de 0,40. Quel produit minimal des réductions de la probabilité et de l’impact ramène le risque résiduel de S1 au niveau toléré?"},"options":{"en":["About 0.20","About 0.40","About 0.47","About 0.53"],"fr":["Environ 0,20","Environ 0,40","Environ 0,47","Environ 0,53"]}},{"n":16,"answer":"B","section":{"en":"Avoiding compliance theatre and the maturity trap","fr":"Au-delà des estimations ponctuelles : FAIR, simulation et courbes de dépassement des pertes"},"q":{"en":"A risk acceptance for an unpatched server was granted three years ago and never reviewed. Which compliance theatre pattern does this illustrate?","fr":"L’acceptation du risque pour un serveur sans correctif a été accordée il y a trois ans et n’a jamais été revue. Quel schéma de conformité de façade cela illustre-t-il?"},"options":{"en":["Late-stage security reviews","Exceptions without expiry","Metric distortion","Framework accumulation"],"fr":["Les revues de sécurité tardives","Les exceptions sans échéance","La distorsion des mesures","L’accumulation des cadres"]}},{"n":17,"answer":"C","section":{"en":"Avoiding compliance theatre and the maturity trap","fr":"Éviter la conformité de façade et le piège de la maturité"},"q":{"en":"Why does the chapter compare maturity improvement to an S-curve of diminishing returns?","fr":"Pourquoi le chapitre compare-t-il l’amélioration de la maturité à une courbe en S à rendements décroissants?"},"options":{"en":["Because maturity scores rise only after a major incident forces investment","Because each maturity level costs the same but delivers less protection","Because foundational hygiene, such as CIS Controls IG1, yields disproportionate early benefit","Because quantitative management is always required before basic patching"],"fr":["Parce que les scores de maturité n’augmentent qu’après qu’un incident majeur a forcé l’investissement","Parce que chaque niveau de maturité coûte la même chose, mais procure moins de protection","Parce que l’hygiène de base, comme l’IG1 des CIS Controls, procure tôt un avantage disproportionné","Parce que la gestion quantitative est toujours requise avant l’application des correctifs de base"]}},{"n":18,"answer":"B","section":{"en":"Investment prioritization: deciding what to fund first","fr":"Priorisation des investissements : décider ce qu’il faut financer en premier"},"q":{"en":"Under the chapter's classification, an audit finding with a committed remediation date that must be funded regardless of ROSI is which type of investment?","fr":"Selon la classification du chapitre, une constatation d’audit assortie d’une date de correction convenue, qui doit être financée quel que soit le ROSI, est quel type d’investissement?"},"options":{"en":["Foundational","Mandatory","Discretionary","Run"],"fr":["Fondamental","Obligatoire","Discrétionnaire","Exploitation"]}},{"n":19,"answer":"D","section":{"en":"Worked example: from scenarios to an investment decision","fr":"La cyberassurance : un transfert du risque assorti de contraintes"},"q":{"en":"How does the CyberRiskGuardian method record a cyber insurance policy for a scenario that remains above tolerance?","fr":"Comment la méthode CyberRiskGuardian consigne-t-elle une police de cyberassurance pour un scénario qui demeure au-dessus de la tolérance?"},"options":{"en":["As a mitigation measure with an impact reduction equal to the policy limit","As a probability reduction, because insurers condition cover on strong controls","As an increase in organizational resilience θ for the affected scenario","As risk transfer: a costed line and a management decision, with the share of loss covered and the approver"],"fr":["Comme une mesure d’atténuation dont la réduction de l’impact est égale à la limite de la police","Comme une réduction de la probabilité, puisque les assureurs conditionnent la couverture à des contrôles robustes","Comme une hausse de la résilience organisationnelle θ pour le scénario touché","Comme un transfert du risque : une ligne chiffrée et une décision de la direction, avec la part de la perte couverte et l’approbateur"]}},{"n":20,"answer":"A","section":{"en":"Budgeting as governance: from annual cycles to multi-year capability building","fr":"Le budget comme outil de gouvernance : des cycles annuels au renforcement pluriannuel des capacités"},"q":{"en":"An organization has a total IT budget of $10 million and an approved risk appetite of 0.60. Using the chapter's best-practice benchmark with linear interpolation, what is its appetite-consistent cybersecurity budget?","fr":"Une organisation dispose d’un budget total des TI de 10 millions de dollars et d’une appétence pour le risque approuvée de 0,60. En appliquant le repère de pratique exemplaire du chapitre avec interpolation linéaire, quel est son budget de cybersécurité aligné sur l’appétence?"},"options":{"en":["About $590,000","About $780,000","About $400,000","About $990,000"],"fr":["Environ 590 000 $","Environ 780 000 $","Environ 400 000 $","Environ 990 000 $"]}}]},{"n":18,"title":{"en":"Chapter 18: AI for Cybersecurity and the Cybersecurity of AI","fr":"Chapitre 18 : L’IA au service de la cybersécurité et la cybersécurité de l’IA"},"questions":[{"n":1,"answer":"D","section":{"en":"AI for attackers: why the threat landscape accelerates","fr":"L’IA au service des attaquants : pourquoi le paysage des menaces s’accélère"},"q":{"en":"According to the chapter, what is the most important change AI brings to the threat landscape?","fr":"Selon le chapitre, quel est le changement le plus important que l’IA apporte au paysage des menaces?"},"options":{"en":["It creates entirely new classes of attack that existing controls cannot address","It makes attacks easier to detect because AI-generated content is uniform","It mainly benefits nation-states, which already had advanced capabilities","It reduces the cost and skill required for attacks, so their volume and polish rise"],"fr":["Elle crée des catégories d’attaques entièrement nouvelles que les contrôles existants ne peuvent pas traiter","Elle rend les attaques plus faciles à détecter, car le contenu généré par l’IA est uniforme","Elle profite surtout aux États, qui possédaient déjà des capacités avancées","Elle réduit le coût et les compétences requises pour attaquer, ce qui accroît le volume et le raffinement des attaques"]}},{"n":2,"answer":"B","section":{"en":"Incident management for AI: from harmful outputs to model compromise","fr":"La gestion des incidents liés à l’IA : des résultats préjudiciables à la compromission des modèles"},"q":{"en":"An AI assistant connected to company systems starts disclosing confidential data. What is often the fastest way to reduce harm, according to the chapter?","fr":"Un assistant d’IA relié aux systèmes de l’entreprise commence à divulguer des données confidentielles. Selon le chapitre, quelle est souvent la façon la plus rapide de réduire le préjudice?"},"options":{"en":["Retrain the model on corrected data before restoring service","Execute pre-tested actions such as disabling the feature or revoking connector tokens","Ask the provider to patch the prompt injection vulnerability","Add instructions to the system prompt forbidding further disclosure"],"fr":["Réentraîner le modèle sur des données corrigées avant de rétablir le service","Exécuter des actions testées d’avance, comme désactiver la fonction ou révoquer les jetons des connecteurs","Demander au fournisseur de corriger la vulnérabilité d’injection de requête","Ajouter à la requête système des instructions qui interdisent toute autre divulgation"]}},{"n":3,"answer":"A","section":{"en":"AI for cybersecurity: what it can do—and what it cannot do","fr":"L’IA au service de la cybersécurité : ce qu’elle peut faire — et ce qu’elle ne peut pas faire"},"q":{"en":"Analysts in a security operations centre almost never override their AI assistant's recommendations. How does the chapter suggest interpreting this?","fr":"Les analystes d’un centre des opérations de sécurité ne dérogent presque jamais aux recommandations de leur assistant d’IA. Comment le chapitre suggère-t-il d’interpréter cette situation?"},"options":{"en":["It may indicate automation bias rather than perfect AI performance","It proves the AI tool is accurate and needs no further evaluation","It shows that analysts lack the authority to disagree with the tool","It means the tool should be allowed to execute all actions automatically"],"fr":["Elle peut indiquer un biais d’automatisation plutôt qu’une performance parfaite de l’IA","Elle prouve que l’outil d’IA est exact et n’exige aucune autre évaluation","Elle montre que les analystes n’ont pas l’autorité de contredire l’outil","Elle signifie qu’il faudrait permettre à l’outil d’exécuter toutes les actions automatiquement"]}},{"n":4,"answer":"C","section":{"en":"AI for attackers: why the threat landscape accelerates","fr":"L’IA au service des attaquants : pourquoi le paysage des menaces s’accélère"},"q":{"en":"A finance clerk receives a convincing deepfake video call from the CFO requesting an urgent transfer. Which control best reflects the chapter's guidance?","fr":"Un commis aux finances reçoit un appel vidéo convaincant, produit par hypertrucage, du chef de la direction financière qui demande un virement urgent. Quel contrôle reflète le mieux les recommandations du chapitre?"},"options":{"en":["Training staff to spot visual artifacts in synthetic video","Deploying an AI tool that detects deepfakes in real time","Out-of-band verification using contact details already on file","Restricting video calls to internal participants only"],"fr":["Former le personnel à repérer les artefacts visuels dans les vidéos synthétiques","Déployer un outil d’IA qui détecte les hypertrucages en temps réel","Une vérification hors bande à l’aide des coordonnées déjà au dossier","Limiter les appels vidéo aux participants internes"]}},{"n":5,"answer":"A","section":{"en":"Cybersecurity of AI: assets, attack surfaces, and threat categories","fr":"L’IA agentique : quand les modèles peuvent agir"},"q":{"en":"Which situation is an example of indirect prompt injection?","fr":"Quelle situation est un exemple d’injection indirecte de requête?"},"options":{"en":["A calendar invitation contains hidden text instructing an assistant to forward emails","A user types a request asking the chatbot to ignore its rules","An attacker floods a model API with requests to raise costs","A developer downloads a model file that runs code when loaded"],"fr":["Une invitation de calendrier contient un texte caché qui demande à un assistant de transférer des courriels","Un utilisateur tape une demande qui invite l’robot conversationnel à ignorer ses règles","Un attaquant inonde de requêtes l’API d’un modèle pour faire grimper les coûts","Un développeur télécharge un fichier de modèle qui exécute du code au chargement"]}},{"n":6,"answer":"C","section":{"en":"Investment governance: deciding what to build, what to buy, and what to prohibit","fr":"Gouvernance des investissements : décider quoi développer, quoi acheter et quoi interdire"},"q":{"en":"A policy states: no autonomous agents with write access to financial systems until permission-scoped connectors, approval gates, and logging are implemented and tested. What is the main governance value of this wording?","fr":"Une politique prévoit : aucun agent autonome disposant d’un accès en écriture aux systèmes financiers tant que des connecteurs à autorisations restreintes, des points d’approbation et la journalisation n’auront pas été mis en œuvre et testés. Quelle est la principale valeur de gouvernance de cette formulation?"},"options":{"en":["It permanently excludes agents from financial processes","It transfers the decision to the AI governance committee","It turns a prohibition into a roadmap with a clear path to approval","It satisfies the EU AI Act's requirements for high-risk systems"],"fr":["Elle exclut définitivement les agents des processus financiers","Elle transfère la décision au comité de gouvernance de l’IA","Elle transforme une interdiction en feuille de route menant clairement à l’approbation","Elle satisfait aux exigences du règlement européen sur l’IA pour les systèmes à haut risque"]}},{"n":7,"answer":"B","section":{"en":"Cybersecurity of AI: assets, attack surfaces, and threat categories","fr":"Cybersécurité de l’IA : actifs, surfaces d’attaque et catégories de menaces"},"q":{"en":"Which of the following is one of the three kinds of asset that an AI system adds to the familiar ones?","fr":"Lequel des énoncés suivants est l’un des trois types d’actifs qu’un système d’IA ajoute aux actifs habituels?"},"options":{"en":["The user interface through which staff access the system","The capabilities granted: tools it can call, data it can reach, actions it can take","The cloud region in which the application servers are hosted","The service-level agreement signed with the hosting provider"],"fr":["L’interface utilisateur par laquelle le personnel accède au système","Les capacités accordées : outils qu’il peut appeler, données qu’il peut atteindre, actions qu’il peut accomplir","La région infonuagique où sont hébergés les serveurs d’application","L’entente de niveau de service signée avec le fournisseur d’hébergement"]}},{"n":8,"answer":"D","section":{"en":"Cybersecurity of AI: assets, attack surfaces, and threat categories","fr":"Cybersécurité de l’IA : actifs, surfaces d’attaque et catégories de menaces"},"q":{"en":"Which design best illustrates what OWASP calls excessive agency?","fr":"Quelle conception illustre le mieux ce que l’OWASP appelle l’autonomie excessive?"},"options":{"en":["A chatbot whose answers are filtered before display","A coding agent limited to a sandbox with read-only repository access","A support agent that drafts refunds for a person to approve","An email-summarizing assistant that can also send and delete messages"],"fr":["Un robot conversationnel dont les réponses sont filtrées avant l’affichage","Un agent de programmation limité à un bac à sable avec un accès en lecture seule au dépôt","Un agent de soutien qui prépare des remboursements qu’une personne doit approuver","Un assistant de résumé de courriels qui peut aussi envoyer et supprimer des messages"]}},{"n":9,"answer":"C","section":{"en":"Agentic AI: when models can act","fr":"L’IA agentique : quand les modèles peuvent agir"},"q":{"en":"Why does the chapter say that, when indirect prompt injection meets excessive agency, the attacker never needs the agent's credentials?","fr":"Pourquoi le chapitre affirme-t-il que, lorsque l’injection indirecte de requête rencontre l’autonomie excessive, l’attaquant n’a jamais besoin des identifiants de l’agent?"},"options":{"en":["Because agents store their credentials in plain-text system prompts","Because connector protocols disable authentication for internal tools","Because the agent is a confused deputy that acts on the attacker's text","Because model providers share credentials across all customers"],"fr":["Parce que les agents stockent leurs identifiants en clair dans les requêtes système","Parce que les protocoles des connecteurs désactivent l’authentification pour les outils internes","Parce que l’agent est un adjoint confus qui agit selon le texte de l’attaquant","Parce que les fournisseurs de modèles partagent les identifiants entre tous leurs clients"]}},{"n":10,"answer":"A","section":{"en":"Agentic AI: when models can act","fr":"L’IA agentique : quand les modèles peuvent agir"},"q":{"en":"The business owner of a production AI agent leaves the organization. What does the chapter recommend?","fr":"Le responsable métier d’un agent d’IA en production quitte l’organisation. Que recommande le chapitre?"},"options":{"en":["Suspend the agent until a new owner is assigned, as with an orphaned account","Let the agent continue, since its permissions were already approved","Transfer ownership automatically to the CISO for continuity","Delete the agent and its logs to prevent misuse"],"fr":["Suspendre l’agent jusqu’à la désignation d’un nouveau responsable, comme pour un compte orphelin","Laisser l’agent poursuivre, puisque ses autorisations ont déjà été approuvées","Transférer automatiquement la responsabilité au CSI pour assurer la continuité","Supprimer l’agent et ses journaux pour prévenir les abus"]}},{"n":11,"answer":"D","section":{"en":"Agentic AI: when models can act","fr":"L’IA agentique : quand les modèles peuvent agir"},"q":{"en":"How should an organization control third-party connectors, such as Model Context Protocol servers, that agents use to reach tools and data?","fr":"Comment une organisation devrait-elle contrôler les connecteurs tiers, comme les serveurs Model Context Protocol, que les agents utilisent pour atteindre des outils et des données?"},"options":{"en":["Allow any connector listed in a public marketplace","Rely on the model to refuse unsafe instructions in tool descriptions","Grant broad long-lived tokens so integrations do not fail","Treat them as privileged integrations: allow-listed, minimally scoped, short-lived credentials, logged"],"fr":["Autoriser tout connecteur offert dans un catalogue public","Compter sur le modèle pour refuser les instructions dangereuses dans les descriptions d’outils","Accorder des jetons étendus et durables pour que les intégrations n’échouent pas","Les traiter comme des intégrations privilégiées : liste d’autorisation, portée minimale, identifiants à courte durée de vie, journalisation"]}},{"n":12,"answer":"B","section":{"en":"Shadow AI and acceptable use","fr":"L’IA fantôme et l’utilisation acceptable"},"q":{"en":"What does the chapter identify as the primary cause of shadow AI?","fr":"Selon le chapitre, quelle est la principale cause de l’IA fantôme?"},"options":{"en":["Employees deliberately trying to circumvent security controls","Unmet demand, when sanctioned tools are missing, harder to use, or slow to approve","Vendors enabling AI features without informing their customers","Lack of technical controls to block consumer AI websites"],"fr":["Des employés qui cherchent délibérément à contourner les contrôles de sécurité","Une demande non satisfaite, lorsque les outils approuvés manquent, sont plus difficiles à utiliser ou lents à approuver","Des fournisseurs qui activent des fonctions d’IA sans en informer leurs clients","L’absence de contrôles techniques pour bloquer les sites d’IA grand public"]}},{"n":13,"answer":"B","section":{"en":"Governance foundations: inventory, classification, and accountability","fr":"Les fondements de la gouvernance : inventaire, classification et imputabilité"},"q":{"en":"In which human oversight pattern does an AI system act autonomously while a person monitors and can intervene?","fr":"Dans quel modèle de supervision humaine un système d’IA agit-il de façon autonome pendant qu’une personne le surveille et peut intervenir?"},"options":{"en":["Human-in-the-loop","Human-on-the-loop","Human-in-command","Human-after-the-fact"],"fr":["Intervention humaine dans la boucle (human-in-the-loop)","Supervision humaine de la boucle (human-on-the-loop)","Humain aux commandes (human-in-command)","Contrôle humain a posteriori (human-after-the-fact)"]}},{"n":14,"answer":"A","section":{"en":"Control patterns that matter in practice","fr":"Les modèles de contrôle qui comptent en pratique"},"q":{"en":"A RAG assistant's system prompt says do not reveal confidential information, but it can search every repository. What is the chapter's recommended control?","fr":"La requête système d’un assistant RAG indique de ne pas révéler d’informations confidentielles, mais l’assistant peut fouiller tous les dépôts. Quel contrôle le chapitre recommande-t-il?"},"options":{"en":["Permission-aware retrieval enforced at the retrieval layer for each requesting user","A longer system prompt listing every confidential document category","Output filtering that blocks any answer mentioning confidential topics","Training users not to ask questions about confidential matters"],"fr":["Une récupération tenant compte des autorisations, appliquée à la couche de récupération pour chaque utilisateur demandeur","Une requête système plus longue qui énumère chaque catégorie de documents confidentiels","Un filtrage des résultats qui bloque toute réponse mentionnant des sujets confidentiels","Former les utilisateurs à ne pas poser de questions sur des sujets confidentiels"]}},{"n":15,"answer":"D","section":{"en":"The AI supply chain: models, data, and components","fr":"La chaîne d’approvisionnement de l’IA : modèles, données et composants"},"q":{"en":"Why does the chapter say provenance and change control matter more than inspection for AI models?","fr":"Pourquoi le chapitre affirme-t-il que la provenance et le contrôle des changements comptent plus que l’inspection pour les modèles d’IA?"},"options":{"en":["Because open-weight models are always safer than hosted services","Because model cards are legally binding on providers","Because providers are required to disclose all training data","Because weights reveal little and some model files can run code when loaded"],"fr":["Parce que les modèles à poids ouverts sont toujours plus sûrs que les services hébergés","Parce que les fiches de modèle lient juridiquement les fournisseurs","Parce que les fournisseurs sont tenus de divulguer toutes leurs données d’entraînement","Parce que les poids révèlent peu de choses et que certains fichiers de modèle peuvent exécuter du code au chargement"]}},{"n":16,"answer":"C","section":{"en":"Privacy, compliance, and the cross-border reality","fr":"Vie privée, conformité et réalité transfrontalière"},"q":{"en":"Under section 12.1 of Québec's private-sector law, what must an enterprise provide when it renders a decision based exclusively on automated processing?","fr":"En vertu de l’article 12.1 de la loi québécoise sur le secteur privé, que doit fournir une entreprise lorsqu’elle rend une décision fondée exclusivement sur un traitement automatisé?"},"options":{"en":["Prior approval from the CAI before the system is deployed","A guarantee that the model contains no personal information","Notice, on request the principal factors, and a chance to submit observations for review","An annual third-party audit of the algorithm's fairness"],"fr":["L’approbation préalable de la CAI avant le déploiement du système","Une garantie que le modèle ne contient aucun renseignement personnel","Un avis, sur demande les principaux facteurs, et la possibilité de présenter des observations en vue d’une révision","Un audit annuel par un tiers de l’équité de l’algorithme"]}},{"n":17,"answer":"D","section":{"en":"Privacy, compliance, and the cross-border reality","fr":"Vie privée, conformité et réalité transfrontalière"},"q":{"en":"Under the EU AI Act as amended by the 2026 AI Omnibus, when do the main obligations for stand-alone high-risk systems listed in Annex III apply?","fr":"Selon le règlement européen sur l’IA, modifié par l’omnibus sur l’IA de 2026, à partir de quand les principales obligations relatives aux systèmes autonomes à haut risque énumérés à l’annexe III s’appliquent-elles?"},"options":{"en":["February 2, 2025","August 2, 2026","August 2, 2028","December 2, 2027"],"fr":["2 février 2025","2 août 2026","2 août 2028","2 décembre 2027"]}},{"n":18,"answer":"C","section":{"en":"Assurance frameworks: integrating AI risk management into cyber governance","fr":"Cadres d’assurance : intégrer la gestion des risques liés à l’IA à la gouvernance de la cybersécurité"},"q":{"en":"What makes ISO/IEC 42001:2023 easier to adopt for an organization that already operates an ISO/IEC 27001 ISMS?","fr":"Qu’est-ce qui rend l’ISO/IEC 42001:2023 plus facile à adopter pour une organisation qui exploite déjà un SGSI conforme à l’ISO/IEC 27001?"},"options":{"en":["It is a technical testing standard for model accuracy","It replaces ISO/IEC 27001 controls for any system using AI","It follows the same harmonized management-system structure","It is a voluntary profile with no certification option"],"fr":["C’est une norme d’essais techniques sur l’exactitude des modèles","Elle remplace les mesures de l’ISO/IEC 27001 pour tout système utilisant l’IA","Elle suit la même structure harmonisée des systèmes de gestion","C’est un profil volontaire sans possibilité de certification"]}},{"n":19,"answer":"A","section":{"en":"Investment governance: deciding what to build, what to buy, and what to prohibit","fr":"Gouvernance des investissements : décider quoi développer, quoi acheter et quoi interdire"},"q":{"en":"In the university scenario, a pilot showed the assistant surfacing draft budgets and hiring files to any employee. What did the working group decide?","fr":"Dans la mise en situation de l’université, un projet pilote a montré que l’assistant faisait apparaître des ébauches de budgets et des dossiers d’embauche à n’importe quel employé. Qu’a décidé le groupe de travail?"},"options":{"en":["Fund a permissions clean-up before enabling retrieval over collaboration sites","Cancel the enterprise assistant and block all AI services","Accept the exposure, since employees already had technical access","Move the assistant to a recommend-only mode for all users"],"fr":["Financer un nettoyage des autorisations avant d’activer la récupération sur les sites de collaboration","Annuler l’assistant d’entreprise et bloquer tous les services d’IA","Accepter l’exposition, puisque les employés avaient déjà un accès technique","Passer l’assistant en mode « recommandation seulement » pour tous les utilisateurs"]}},{"n":20,"answer":"B","section":{"en":"Assurance frameworks: integrating AI risk management into cyber governance","fr":"Cadres d’assurance : intégrer la gestion des risques liés à l’IA à la gouvernance de la cybersécurité"},"q":{"en":"Which list correctly names the four functions of the NIST AI Risk Management Framework (AI RMF 1.0)?","fr":"Quelle liste nomme correctement les quatre fonctions du NIST AI Risk Management Framework (AI RMF 1.0)?"},"options":{"en":["Identify, Protect, Detect, Respond","Govern, Map, Measure, Manage","Defend, Secure, Thwart, Recover","Plan, Build, Deploy, Retire"],"fr":["Identifier, Protéger, Détecter, Répondre","Gouverner, Cartographier, Mesurer, Gérer (Govern, Map, Measure, Manage)","Défendre, Sécuriser, Contrecarrer, Rétablir","Planifier, Bâtir, Déployer, Retirer"]}}]},{"n":19,"title":{"en":"Chapter 19: Third-Party and Supply-Chain Cybersecurity Governance","fr":"Chapitre 19 : Gouvernance de la cybersécurité des tiers et de la chaîne d’approvisionnement"},"questions":[{"n":1,"answer":"B","section":{"en":"Concepts and scope: what third-party and supply chain mean in practice","fr":"Concepts et portée : ce que signifient concrètement les tiers et la chaîne d’approvisionnement"},"q":{"en":"According to the chapter, what determines whether an external entity belongs inside the third-party cybersecurity governance program?","fr":"Selon le chapitre, qu’est-ce qui détermine si une entité externe doit faire partie du programme de gouvernance de la cybersécurité des tiers?"},"options":{"en":["Whether the entity has a signed outsourcing contract with the organization","Whether its failure or compromise could materially harm critical services or sensitive information","Whether the entity has persistent access to the corporate network","Whether the entity's annual contract value exceeds a defined procurement threshold"],"fr":["Le fait que l’entité ait signé un contrat d’impartition avec l’organisation","Le fait que sa défaillance ou sa compromission puisse nuire de façon importante aux services critiques ou à l’information sensible","Le fait que l’entité dispose d’un accès permanent au réseau de l’entreprise","Le fait que la valeur annuelle du contrat dépasse un seuil d’approvisionnement défini"]}},{"n":2,"answer":"D","section":{"en":"Concepts and scope: what third-party and supply chain mean in practice","fr":"Concepts et portée : ce que signifient concrètement les tiers et la chaîne d’approvisionnement"},"q":{"en":"A SaaS provider used by a retailer runs on a hyperscale cloud and uses an outsourced support desk. From the retailer's perspective, what are the cloud and the support desk?","fr":"Un fournisseur SaaS utilisé par un détaillant fonctionne sur un nuage à très grande échelle et recourt à un centre de soutien imparti. Du point de vue du détaillant, que sont le nuage et le centre de soutien?"},"options":{"en":["Second-line oversight functions","Complementary user entity controls","Critical ICT third-party providers","Fourth parties"],"fr":["Des fonctions de surveillance de deuxième ligne","Des contrôles complémentaires chez l’entité utilisatrice","Des prestataires tiers critiques de services TIC","Des parties de quatrième rang"]}},{"n":3,"answer":"A","section":{"en":"Concepts and scope: what third-party and supply chain mean in practice","fr":"Concepts et portée : ce que signifient concrètement les tiers et la chaîne d’approvisionnement"},"q":{"en":"Which NIST CSF 2.0 category places cybersecurity supply chain risk management within the Govern function?","fr":"Quelle catégorie du NIST CSF 2.0 place la gestion des risques de cybersécurité liés à la chaîne d’approvisionnement dans la fonction Gouverner?"},"options":{"en":["GV.SC, with outcomes from program establishment to post-relationship activities","PR.AA, which addresses identity management and access control","DE.CM, which addresses continuous monitoring of assets","RS.MA, which addresses incident management activities"],"fr":["GV.SC, dont les résultats vont de l’établissement du programme aux activités postérieures à la relation","PR.AA, qui porte sur la gestion des identités et le contrôle d’accès","DE.CM, qui porte sur la surveillance continue des actifs","RS.MA, qui porte sur les activités de gestion des incidents"]}},{"n":4,"answer":"C","section":{"en":"A lifecycle model for third-party cybersecurity governance","fr":"Un modèle de cycle de vie pour la gouvernance de la cybersécurité des tiers"},"q":{"en":"A Tier 1 supplier's controls cannot meet the organization's standard. Who, according to the chapter, should accept the resulting residual risk?","fr":"Les contrôles d’un fournisseur de niveau 1 ne peuvent satisfaire à la norme de l’organisation. Selon le chapitre, qui devrait accepter le risque résiduel qui en découle?"},"options":{"en":["The CISO, who evaluated the supplier's security evidence","The procurement officer who managed the selection process","The business owner of the relationship, as an accountable risk owner","Legal counsel, who negotiated the contract's security schedule"],"fr":["Le CSI, qui a évalué les éléments probants de sécurité du fournisseur","La personne responsable de l’approvisionnement qui a géré le processus de sélection","Le responsable métier de la relation, à titre de responsable du risque imputable","Le conseiller juridique, qui a négocié l’annexe de sécurité du contrat"]}},{"n":5,"answer":"A","section":{"en":"Chapter summary","fr":"Résumé du chapitre"},"q":{"en":"What turns a third-party lifecycle diagram into governance, according to the chapter?","fr":"Selon le chapitre, qu’est-ce qui transforme un diagramme du cycle de vie des tiers en véritable gouvernance?"},"options":{"en":["Gates where a defined person makes a recorded decision based on defined evidence","A single detailed security questionnaire completed during procurement","Automatic renewal clauses that keep relationships stable over time","An annual compilation of all suppliers sent to the audit committee"],"fr":["Des points de contrôle où une personne désignée prend une décision consignée sur la base d’éléments probants définis","Un seul questionnaire de sécurité détaillé rempli pendant l’approvisionnement","Des clauses de renouvellement automatique qui assurent la stabilité des relations","Une compilation annuelle de tous les fournisseurs transmise au comité d’audit"]}},{"n":6,"answer":"C","section":{"en":"Incident coordination: when the breach happens somewhere else","fr":"Coordination des incidents : lorsque la violation survient ailleurs"},"q":{"en":"A small marketing firm with no system access receives weekly extracts of several hundred thousand customers' personal information. Which tiering driver should most clearly raise its tier?","fr":"Une petite firme de marketing sans accès aux systèmes reçoit chaque semaine des extraits contenant les renseignements personnels de plusieurs centaines de milliers de clients. Quel facteur de classement devrait le plus clairement relever son niveau?"},"options":{"en":["Service criticality, because marketing supports revenue","Access and integration, because files are exchanged","Data sensitivity, because of the volume of personal information","Substitutability, because analytics firms are rare"],"fr":["La criticité du service, parce que le marketing soutient les revenus","L’accès et l’intégration, parce que des fichiers sont échangés","La sensibilité des données, en raison du volume de renseignements personnels","La substituabilité, parce que les firmes d’analytique sont rares"]}},{"n":7,"answer":"B","section":{"en":"Risk tiering: turning risk appetite into tiered requirements","fr":"Classement par niveau de risque : traduire l’appétence pour le risque en exigences par niveau"},"q":{"en":"A cloud identity provider presents excellent independent evidence of strong controls. How should this affect its classification?","fr":"Un fournisseur d’identité infonuagique présente d’excellents éléments probants indépendants attestant de contrôles solides. Quel effet cela devrait-il avoir sur son classement?"},"options":{"en":["It should move to Tier 2, because controls reduce inherent risk","It stays Tier 1; the evidence improves the residual risk rating","It should move to Tier 3, with reassessment only at renewal","It should be removed from the register as a trusted provider"],"fr":["Il devrait passer au niveau 2, parce que les contrôles réduisent le risque inhérent","Il reste au niveau 1; les éléments probants améliorent la cote de risque résiduel","Il devrait passer au niveau 3, avec une réévaluation au renouvellement seulement","Il devrait être retiré du registre à titre de fournisseur de confiance"]}},{"n":8,"answer":"D","section":{"en":"Risk tiering: turning risk appetite into tiered requirements","fr":"Classement par niveau de risque : traduire l’appétence pour le risque en exigences par niveau"},"q":{"en":"Which indicator does the chapter suggest tells a board most about the real coverage of a third-party program?","fr":"Selon le chapitre, quel indicateur renseigne le mieux un conseil d’administration sur la couverture réelle d’un programme de gestion des tiers?"},"options":{"en":["The total number of security questionnaires completed this year","The number of suppliers holding an ISO/IEC 27001 certificate","The average security rating score across all active suppliers","The percentage of active suppliers with an assigned tier and owner"],"fr":["Le nombre total de questionnaires de sécurité remplis cette année","Le nombre de fournisseurs titulaires d’un certificat ISO/IEC 27001","La cote de sécurité moyenne de l’ensemble des fournisseurs actifs","Le pourcentage de fournisseurs actifs auxquels un niveau et un responsable ont été attribués"]}},{"n":9,"answer":"C","section":{"en":"Due diligence and assurance: questionnaires versus evidence-based confidence","fr":"Vérification diligente et assurance : questionnaires ou confiance fondée sur des éléments probants"},"q":{"en":"Why is a SOC 2 Type II report generally more informative than a Type I report?","fr":"Pourquoi un rapport SOC 2 de type II est-il généralement plus informatif qu’un rapport de type I?"},"options":{"en":["It is issued under ISAE 3402 rather than AICPA attestation standards","It covers financial reporting controls as well as security controls","It tests whether controls operated effectively over a period of time","It replaces the need to review carved-out subservice organizations"],"fr":["Il est délivré selon la norme ISAE 3402 plutôt que selon les normes d’attestation de l’AICPA","Il couvre les contrôles liés à l’information financière en plus des contrôles de sécurité","Il vérifie si les contrôles ont fonctionné efficacement pendant une période donnée","Il dispense d’examiner les sous-traitants de services exclus (carve-outs)"]}},{"n":10,"answer":"A","section":{"en":"Due diligence and assurance: questionnaires versus evidence-based confidence","fr":"Vérification diligente et assurance : questionnaires ou confiance fondée sur des éléments probants"},"q":{"en":"A supplier's SOC 2 report assumes customers will review their own access logs. The organization does not do so. What follows?","fr":"Le rapport SOC 2 d’un fournisseur présume que les clients examineront leurs propres journaux d’accès. L’organisation ne le fait pas. Qu’en découle-t-il?"},"options":{"en":["The report's assurance does not fully hold for this organization","The supplier's auditor must reissue the report with a qualification","The report's scope automatically excludes the organization's users","The supplier becomes responsible for reviewing the customer's logs"],"fr":["L’assurance fournie par le rapport ne vaut pas entièrement pour cette organisation","L’auditeur du fournisseur doit publier de nouveau le rapport avec une réserve","La portée du rapport exclut automatiquement les utilisateurs de l’organisation","Le fournisseur devient responsable de l’examen des journaux du client"]}},{"n":11,"answer":"D","section":{"en":"Fourth-party risk and the software supply chain: managing transitive exposure","fr":"Risque lié aux parties de quatrième rang et chaîne d’approvisionnement logicielle : gérer l’exposition transitive"},"q":{"en":"Under the EU Cyber Resilience Act reporting obligations applying since September 11, 2026, how quickly must manufacturers issue an early warning of an actively exploited vulnerability?","fr":"En vertu des obligations de déclaration du règlement européen sur la cyberrésilience applicables depuis le 11 septembre 2026, dans quel délai les fabricants doivent-ils transmettre une alerte précoce concernant une vulnérabilité activement exploitée?"},"options":{"en":["Within 72 hours, followed by a final report within thirty days","Without undue delay once the breach has been confirmed","Within seven days of a patch becoming available","Within 24 hours, followed by a fuller notification within 72 hours"],"fr":["Dans les 72 heures, suivie d’un rapport final dans les trente jours","Sans retard injustifié une fois la violation confirmée","Dans les sept jours suivant la disponibilité d’un correctif","Dans les 24 heures, suivie d’une notification plus complète dans les 72 heures"]}},{"n":12,"answer":"B","section":{"en":"Exit and transition planning: preserving the ability to leave","fr":"Planification de la sortie et de la transition : préserver la capacité de partir"},"q":{"en":"What does the chapter identify as the step that distinguishes an exit plan from a hope?","fr":"Selon le chapitre, quelle étape distingue un véritable plan de sortie d’un simple espoir?"},"options":{"en":["Obtaining a bridge letter from the supplier each year","Periodically testing that exported data can be loaded elsewhere","Including a termination-for-convenience clause in the contract","Listing alternative suppliers in the third-party register"],"fr":["Obtenir chaque année une lettre de transition du fournisseur","Vérifier périodiquement que les données exportées peuvent être chargées ailleurs","Inclure dans le contrat une clause de résiliation pour convenance","Inscrire des fournisseurs de rechange dans le registre des tiers"]}},{"n":13,"answer":"A","section":{"en":"Security requirements in RFPs and procurement: building security in rather than negotiating it later","fr":"Classement par niveau de risque : traduire l’appétence pour le risque en exigences par niveau"},"q":{"en":"An organization's appetite does not permit critical suppliers lacking any independent assurance report. How does the chapter recommend expressing this in procurement?","fr":"L’appétence d’une organisation ne permet pas de retenir des fournisseurs critiques dépourvus de tout rapport d’assurance indépendant. Comment le chapitre recommande-t-il d’exprimer cette exigence dans l’approvisionnement?"},"options":{"en":["As a disqualifying criterion stated in the RFP before selection","As a weighted scoring item worth five percent of the evaluation","As a negotiation point raised after the preferred vendor is chosen","As a remediation commitment written into the first renewal"],"fr":["Comme critère éliminatoire énoncé dans la demande de propositions, avant la sélection","Comme élément de pointage pondéré valant cinq pour cent de l’évaluation","Comme point de négociation soulevé après le choix du fournisseur privilégié","Comme engagement de correction inscrit au premier renouvellement"]}},{"n":14,"answer":"D","section":{"en":"Fourth-party risk and the software supply chain: managing transitive exposure","fr":"Risque lié aux parties de quatrième rang et chaîne d’approvisionnement logicielle : gérer l’exposition transitive"},"q":{"en":"What is the main governance value of holding SBOMs for critical software?","fr":"Quelle est la principale valeur, en matière de gouvernance, de détenir des SBOM pour les logiciels critiques?"},"options":{"en":["They prove the software was built without tampering from source","They replace the need for vulnerability exploitability information","They certify that the supplier follows the SSDF practices","They let the organization determine exposure to component vulnerabilities in hours"],"fr":["Elles prouvent que le logiciel a été construit à partir du code source sans altération","Elles dispensent de toute information sur l’exploitabilité des vulnérabilités","Elles certifient que le fournisseur applique les pratiques du SSDF","Elles permettent à l’organisation de déterminer en quelques heures son exposition aux vulnérabilités des composants"]}},{"n":15,"answer":"C","section":{"en":"Contracting and enforceability: where governance becomes legally real","fr":"Contractualisation et caractère exécutoire : là où la gouvernance devient juridiquement réelle"},"q":{"en":"A Canadian organization's supplier contract allows thirty days to report confirmed breaches. Why does the chapter consider such a clause inadequate?","fr":"Le contrat d’un fournisseur d’une organisation canadienne prévoit un délai de trente jours pour déclarer les violations confirmées. Pourquoi le chapitre juge-t-il cette clause insuffisante?"},"options":{"en":["Because contracts should never specify notification timelines","Because only regulators may set supplier notification deadlines","Because the organization cannot meet its own regulatory deadlines and suspected compromises go unreported","Because notification clauses are unenforceable against cloud providers"],"fr":["Parce que les contrats ne devraient jamais préciser de délais d’avis","Parce que seuls les organismes de réglementation peuvent fixer les délais d’avis des fournisseurs","Parce que l’organisation ne peut respecter ses propres échéances réglementaires et que les compromissions soupçonnées ne sont pas signalées","Parce que les clauses d’avis sont inexécutables à l’égard des fournisseurs infonuagiques"]}},{"n":16,"answer":"B","section":{"en":"Contracting and enforceability: where governance becomes legally real","fr":"Contractualisation et caractère exécutoire : là où la gouvernance devient juridiquement réelle"},"q":{"en":"A critical SaaS provider offers only standard, non-negotiable terms that fall short of requirements. What does the chapter recommend?","fr":"Un fournisseur SaaS critique n’offre que des modalités standard non négociables qui ne satisfont pas aux exigences. Que recommande le chapitre?"},"options":{"en":["Refuse the provider, since unnegotiated contracts are never acceptable","Document the gap, apply compensating controls, and obtain executive risk acceptance","Accept the terms silently, because large providers are generally secure","Ask the security team to waive the requirement on the business's behalf"],"fr":["Refuser le fournisseur, puisque les contrats non négociés ne sont jamais acceptables","Documenter l’écart, appliquer des contrôles compensatoires et obtenir l’acceptation du risque par la haute direction","Accepter les modalités sans le dire, parce que les grands fournisseurs sont généralement sûrs","Demander à l’équipe de sécurité de renoncer à l’exigence au nom des activités"]}},{"n":17,"answer":"B","section":{"en":"Contracting and enforceability: where governance becomes legally real","fr":"Contractualisation et caractère exécutoire : là où la gouvernance devient juridiquement réelle"},"q":{"en":"A supplier could expose millions of customer records, yet its contract caps liability at twelve months of fees. How should management view this?","fr":"Un fournisseur pourrait exposer des millions de dossiers de clients, mais son contrat plafonne sa responsabilité à douze mois de frais. Comment la direction devrait-elle considérer cette situation?"},"options":{"en":["As standard practice that requires no executive attention","As potentially inadequate for the risk, requiring executive attention","As acceptable, because service credits will cover breach costs","As irrelevant, because liability caps do not affect security"],"fr":["Comme une pratique courante qui n’exige aucune attention de la haute direction","Comme potentiellement insuffisante au regard du risque, ce qui exige l’attention de la haute direction","Comme acceptable, parce que les crédits de service couvriront les coûts d’une violation","Comme sans importance, parce que les plafonds de responsabilité n’ont aucun effet sur la sécurité"]}},{"n":18,"answer":"A","section":{"en":"Onboarding, continuous monitoring, and ongoing assurance: recognizing that suppliers change","fr":"Accueil, surveillance continue et assurance continue : reconnaître que les fournisseurs changent"},"q":{"en":"What does the chapter identify as the main limitation of security ratings for supplier monitoring?","fr":"Selon le chapitre, quelle est la principale limite des cotes de sécurité pour la surveillance des fournisseurs?"},"options":{"en":["They see only the external surface and say nothing about internal controls","They require on-site audits that suppliers rarely permit","They are only available for suppliers holding SOC 2 reports","They are updated too rarely to detect exposed services"],"fr":["Elles ne voient que la surface externe et ne disent rien des contrôles internes","Elles exigent des audits sur place que les fournisseurs permettent rarement","Elles ne sont offertes que pour les fournisseurs titulaires de rapports SOC 2","Elles sont mises à jour trop rarement pour détecter les services exposés"]}},{"n":19,"answer":"D","section":{"en":"Concentration risk: single-provider dependency as a modern governance problem","fr":"Risque de concentration : la dépendance à un fournisseur unique, un problème de gouvernance moderne"},"q":{"en":"Which governance question does the chapter draw from the July 2024 global IT outage caused by a defective security software update?","fr":"Quelle question de gouvernance le chapitre tire-t-il de la panne informatique mondiale de juillet 2024 causée par une mise à jour défectueuse d’un logiciel de sécurité?"},"options":{"en":["Whether the organization should avoid well-regarded security vendors","Whether endpoint security products are necessary on Windows systems","Whether cyber insurance policies cover outages caused by vendors","Which suppliers can push changes into production without the organization's approval"],"fr":["Si l’organisation devrait éviter les fournisseurs de sécurité réputés","Si les produits de sécurité des terminaux sont nécessaires sur les systèmes Windows","Si les polices de cyberassurance couvrent les pannes causées par les fournisseurs","Quels fournisseurs peuvent pousser des changements en production sans l’approbation de l’organisation"]}},{"n":20,"answer":"C","section":{"en":"Incident coordination: when the breach happens somewhere else","fr":"Coordination des incidents : lorsque la violation survient ailleurs"},"q":{"en":"Why did Nordet's board conclude that its governance, rather than the marketing firm's negligence, was the main problem?","fr":"Pourquoi le conseil d’administration de Nordet a-t-il conclu que le principal problème était sa propre gouvernance plutôt que la négligence de la firme de marketing?"},"options":{"en":["Because the firm had refused to apply the vendor's patch","Because Nordet had no incident response team in place","Because tiering ignored data sensitivity, leaving weak evidence and contract terms","Because the file-transfer product had no known vulnerabilities"],"fr":["Parce que la firme avait refusé d’appliquer le correctif du fournisseur","Parce que Nordet n’avait aucune équipe d’intervention en cas d’incident","Parce que le classement par niveau avait ignoré la sensibilité des données, d’où des éléments probants et des modalités contractuelles faibles","Parce que le produit de transfert de fichiers ne présentait aucune vulnérabilité connue"]}}]},{"n":20,"title":{"en":"Chapter 20: Cryptography and Key Management in Managerial Terms","fr":"Chapitre 20 : La cryptographie et la gestion des clés expliquées aux gestionnaires"},"questions":[{"n":1,"answer":"C","section":{"en":"What encryption does, and what it does not do","fr":"Résumé du chapitre"},"q":{"en":"A software publisher signs each release so customers can verify its origin. Which cryptographic objective does this primarily serve?","fr":"Un éditeur de logiciels signe chaque version afin que ses clients puissent en vérifier l’origine. Quel objectif cryptographique cela sert-il principalement?"},"options":{"en":["Confidentiality, by preventing others from reading the software","Availability, by ensuring the software can always be downloaded","Authenticity, by proving the package came from a specific key holder","Privacy, by limiting what personal data the software collects"],"fr":["La confidentialité, en empêchant d’autres personnes de lire le logiciel","La disponibilité, en garantissant que le logiciel peut toujours être téléchargé","L’authenticité, en prouvant que le progiciel provient d’un détenteur de clé précis","La vie privée, en limitant les données personnelles que recueille le logiciel"]}},{"n":2,"answer":"A","section":{"en":"What encryption does, and what it does not do","fr":"Ce que fait le chiffrement, et ce qu’il ne fait pas"},"q":{"en":"A customer database is fully encrypted at rest. Which incident would this encryption do little to mitigate?","fr":"Une base de données de clients est entièrement chiffrée au repos. Contre quel incident ce chiffrement serait-il peu utile?"},"options":{"en":["An injection flaw in the web application that returns plaintext records","Theft of a decommissioned disk that was improperly disposed of","Loss of a backup tape during transport to an off-site vault","A compromise of the hosting layer exposing raw storage volumes"],"fr":["Une faille d’injection dans l’application Web qui renvoie des dossiers en clair","Le vol d’un disque mis hors service dont on s’est mal débarrassé","La perte d’une bande de sauvegarde pendant son transport vers une voûte hors site","Une compromission de la couche d’hébergement exposant des volumes de stockage bruts"]}},{"n":3,"answer":"D","section":{"en":"Post-quantum cryptography and crypto-agility as a governance program","fr":"La cryptographie post-quantique et l’agilité cryptographique en tant que programme de gouvernance"},"q":{"en":"Health records must stay confidential for 10 years, migration will take 7 years, and a quantum threat is expected in 12 years. What does Mosca's reasoning test conclude?","fr":"Des dossiers de santé doivent rester confidentiels pendant 10 ans, la migration prendra 7 ans et une menace quantique est attendue dans 12 ans. Que conclut le raisonnement de Mosca?"},"options":{"en":["The organization has five years of slack before it must start","The organization can wait until a quantum computer is announced","The test does not apply to health records, only to government data","The organization is already late, because 10 plus 7 exceeds 12"],"fr":["L’organisation dispose d’une marge de cinq ans avant de devoir commencer","L’organisation peut attendre l’annonce d’un ordinateur quantique","Le test ne s’applique pas aux dossiers de santé, seulement aux données gouvernementales","L’organisation est déjà en retard, car 10 plus 7 dépasse 12"]}},{"n":4,"answer":"B","section":{"en":"What should be encrypted? A classification-driven view","fr":"Que faut-il chiffrer? Une approche fondée sur la classification"},"q":{"en":"In the chapter's sample classification table, what cryptographic expectation applies to restricted information such as card data and keys?","fr":"Dans le tableau de classification type du chapitre, quelle attente cryptographique s’applique à l’information restreinte, comme les données de cartes et les clés?"},"options":{"en":["Platform encryption by default with standard transport encryption","Strong encryption everywhere, keys in an HSM or managed KMS, and strict separation of duties","Integrity and authenticity protection for published content only","Encryption in transit only, with plaintext storage permitted internally"],"fr":["Chiffrement de la plateforme par défaut et chiffrement standard du transport","Chiffrement robuste partout, clés dans un HSM ou un KMS géré, et séparation stricte des tâches","Protection de l’intégrité et de l’authenticité pour le contenu publié seulement","Chiffrement en transit seulement, le stockage en clair étant permis à l’interne"]}},{"n":5,"answer":"B","section":{"en":"Post-quantum cryptography and crypto-agility as a governance program","fr":"La cryptographie post-quantique et l’agilité cryptographique en tant que programme de gouvernance"},"q":{"en":"Under the Canadian Centre for Cyber Security roadmap ITSM.40.001, by when should Government of Canada high-priority systems complete migration to post-quantum cryptography?","fr":"Selon la feuille de route ITSM.40.001 du Centre canadien pour la cybersécurité, à quel moment les systèmes hautement prioritaires du gouvernement du Canada devraient-ils avoir terminé leur migration vers la cryptographie post-quantique?"},"options":{"en":["By the end of 2026","By the end of 2031","By the end of 2030","By the end of 2035"],"fr":["D’ici la fin de 2026","D’ici la fin de 2031","D’ici la fin de 2030","D’ici la fin de 2035"]}},{"n":6,"answer":"D","section":{"en":"What should be encrypted? A classification-driven view","fr":"Que faut-il chiffrer? Une approche fondée sur la classification"},"q":{"en":"Which backup arrangement does the chapter describe as a particular trap?","fr":"Quelle disposition de sauvegarde le chapitre présente-t-il comme un piège particulier?"},"options":{"en":["Backups encrypted with keys held under dual control","Backups isolated from the production network","Backups whose recovery keys are tested every year","Backups whose key is stored only in the environment being backed up"],"fr":["Des sauvegardes chiffrées avec des clés détenues sous double contrôle","Des sauvegardes isolées du réseau de production","Des sauvegardes dont les clés de récupération sont testées chaque année","Des sauvegardes dont la clé n’est conservée que dans l’environnement sauvegardé"]}},{"n":7,"answer":"A","section":{"en":"Ownership and accountability: who owns keys?","fr":"Responsabilité et imputabilité : à qui appartiennent les clés?"},"q":{"en":"Which dimension of key ownership answers for whether key management aligns with risk appetite, regulatory obligations, and internal policy?","fr":"Quelle dimension de la responsabilité des clés répond de l’alignement de la gestion des clés sur l’appétence pour le risque, les obligations réglementaires et la politique interne?"},"options":{"en":["Governance accountability, shared among the CISO, data owners, and legal and privacy","Operational control, held by whoever can generate, rotate, or revoke keys","Legal ownership, held by the party with the right to control key use","Technical custody, held by the vendor that configured the platform"],"fr":["L’imputabilité en matière de gouvernance, partagée entre le CSI, les responsables des données, ainsi que les services juridiques et la protection des renseignements personnels","Le contrôle opérationnel, détenu par quiconque peut générer, renouveler ou révoquer les clés","La propriété juridique, détenue par la partie qui a le droit de contrôler l’utilisation des clés","La garde technique, détenue par le fournisseur qui a configuré la plateforme"]}},{"n":8,"answer":"C","section":{"en":"Where encryption matters: in transit, at rest, in use, and in logs","fr":"Là où le chiffrement compte : en transit, au repos, en cours d’utilisation et dans les journaux"},"q":{"en":"What feature defines confidential computing, according to the Confidential Computing Consortium definition cited in the chapter?","fr":"Selon la définition du Confidential Computing Consortium citée dans le chapitre, quelle caractéristique définit l’informatique confidentielle?"},"options":{"en":["Field-level encryption that hides data from database administrators","Tokenization that replaces sensitive values with surrogate tokens","Computation in a hardware-based, attested Trusted Execution Environment","End-to-end encryption with keys held only by individual users"],"fr":["Un chiffrement au niveau des champs qui cache les données aux administrateurs de bases de données","Une tokenisation qui substitue des jetons aux valeurs sensibles","L’exécution des calculs dans un environnement d’exécution de confiance matériel et attesté","Un chiffrement de bout en bout dont les clés ne sont détenues que par chaque utilisateur"]}},{"n":9,"answer":"D","section":{"en":"Key management fundamentals in managerial language","fr":"Les fondements de la gestion des clés en langage managérial"},"q":{"en":"An organization uses envelope encryption with a single master key protecting thousands of data keys. What governance consequence follows?","fr":"Une organisation utilise le chiffrement par enveloppe, une seule clé maîtresse protégeant des milliers de clés de données. Quelle conséquence en découle sur le plan de la gouvernance?"},"options":{"en":["Rotation and revocation become impractical across the hierarchy","Data keys no longer need inventory entries or owners","Separation of duties is no longer needed for administrators","Loss or compromise of the master key has a very large blast radius"],"fr":["Le renouvellement et la révocation deviennent impraticables dans toute la hiérarchie","Les clés de données n’ont plus besoin d’entrées d’inventaire ni de responsables","La séparation des tâches n’est plus nécessaire pour les administrateurs","La perte ou la compromission de la clé maîtresse a un rayon d’impact très étendu"]}},{"n":10,"answer":"B","section":{"en":"Measuring and assuring cryptographic controls","fr":"Mesurer les contrôles cryptographiques et en fournir l’assurance"},"q":{"en":"How does the chapter recommend reporting a certificate-expiry KRI to the board?","fr":"Comment le chapitre recommande-t-il de présenter au conseil d’administration un ICR sur l’expiration des certificats?"},"options":{"en":["As the total number of certificates held, for example 1,200 certificates","In business terms, such as four member-facing services at risk of outage within 30 days","As the percentage of certificates issued by private rather than public authorities","As a technical appendix listing every certificate's expiry date"],"fr":["Sous forme de nombre total de certificats détenus, par exemple 1 200 certificats","En termes d’affaires, par exemple quatre services destinés aux membres exposés à une panne d’ici 30 jours","Sous forme de pourcentage de certificats délivrés par des autorités privées plutôt que publiques","Dans une annexe technique énumérant la date d’expiration de chaque certificat"]}},{"n":11,"answer":"A","section":{"en":"Key management fundamentals in managerial language","fr":"Les fondements de la gestion des clés en langage managérial"},"q":{"en":"Why do mature organizations use dual control and split knowledge for operations such as restoring a master key from backup?","fr":"Pourquoi les organisations matures appliquent-elles le double contrôle et la connaissance fractionnée à des opérations comme la restauration d’une clé maîtresse à partir d’une sauvegarde?"},"options":{"en":["So that no single person can perform the operation or hold the complete secret","So that the operation can be completed faster during an incident","So that the HSM vendor can perform the operation on the customer's behalf","So that key usage logs are no longer required for these operations"],"fr":["Pour qu’aucune personne ne puisse effectuer seule l’opération ni détenir le secret complet","Pour que l’opération puisse être effectuée plus rapidement pendant un incident","Pour que le fournisseur du HSM puisse effectuer l’opération au nom du client","Pour que les journaux d’utilisation des clés ne soient plus nécessaires pour ces opérations"]}},{"n":12,"answer":"C","section":{"en":"Key management fundamentals in managerial language","fr":"Les fondements de la gestion des clés en langage managérial"},"q":{"en":"NIST's transition schedule placed all remaining FIPS 140-2 certificates on the historical list in September 2026. What should managers conclude?","fr":"Le calendrier de transition du NIST a placé tous les certificats FIPS 140-2 restants sur la liste historique en septembre 2026. Que devraient en conclure les gestionnaires?"},"options":{"en":["Modules validated under FIPS 140-2 are now prohibited from operation","Validation status no longer matters for cryptographic procurement","FIPS 140-2 certificates should not be relied upon for new procurements","Only Canadian modules require FIPS 140-3 validation from now on"],"fr":["Les modules validés selon la norme FIPS 140-2 ne peuvent plus être exploités","Le statut de validation n’a plus d’importance pour l’approvisionnement cryptographique","Il ne faut plus se fier aux certificats FIPS 140-2 pour les nouveaux approvisionnements","Seuls les modules canadiens doivent désormais être validés selon la norme FIPS 140-3"]}},{"n":13,"answer":"B","section":{"en":"Customer-managed keys in the cloud: BYOK, HYOK, and HSM services","fr":"Clés gérées par le client dans le nuage : BYOK, HYOK et services HSM"},"q":{"en":"An organization adopts HYOK for several SaaS applications, keeping master keys in its own external key service. What new failure mode does this introduce?","fr":"Une organisation adopte le HYOK pour plusieurs applications SaaS et conserve ses clés maîtresses dans son propre service de clés externe. Quel nouveau mode de défaillance cela introduit-il?"},"options":{"en":["The provider can now decrypt data without the customer's knowledge","An outage of the customer's key service disables every dependent cloud application","Key usage can no longer be logged in the customer's own account","The provider's application layer can no longer process any data"],"fr":["Le fournisseur peut désormais déchiffrer les données à l’insu du client","Une panne du service de clés du client paralyse toutes les applications infonuagiques dépendantes","L’utilisation des clés ne peut plus être journalisée dans le propre compte du client","La couche applicative du fournisseur ne peut plus traiter aucune donnée"]}},{"n":14,"answer":"A","section":{"en":"Key escrow, recovery, and lawful access","fr":"Séquestre de clés, récupération et accès légal"},"q":{"en":"Laptop recovery keys are escrowed in the organization's device management service. How should access to that escrow be governed?","fr":"Les clés de récupération des ordinateurs portatifs sont placées sous séquestre dans le service de gestion des appareils de l’organisation. Comment l’accès à ce séquestre devrait-il être gouverné?"},"options":{"en":["Restricted, logged, and reviewed like any other privileged capability","Open to all help desk staff without logging, to speed support","Delegated to the device vendor, which holds legal ownership of the keys","Disabled entirely, accepting that forgotten passwords mean lost devices"],"fr":["Restreint, journalisé et examiné comme toute autre capacité privilégiée","Ouvert à tout le personnel du centre d’assistance, sans journalisation, pour accélérer le soutien","Délégué au fabricant des appareils, qui détient la propriété juridique des clés","Entièrement désactivé, en acceptant qu’un mot de passe oublié signifie un appareil perdu"]}},{"n":15,"answer":"D","section":{"en":"Customer-managed keys in the cloud: BYOK, HYOK, and HSM services","fr":"Clés gérées par le client dans le nuage : BYOK, HYOK et services HSM"},"q":{"en":"In the Québec manufacturer scenario, the BYOK master key could not be found. What did the post-incident review identify as the root cause?","fr":"Dans la mise en situation du fabricant québécois, la clé maîtresse BYOK était introuvable. Quelle cause profonde la revue post-incident a-t-elle relevée?"},"options":{"en":["A weakness in the SaaS provider's key management algorithm","An attack that deliberately destroyed the on-premises HSM","The defence customer's unrealistic encryption requirements","Managerial failures: no owner, no inventory entry, and no cryptographic dependency check at decommissioning"],"fr":["Une faiblesse de l’algorithme de gestion des clés du fournisseur SaaS","Une attaque qui a délibérément détruit le HSM sur place","Les exigences de chiffrement irréalistes du client du secteur de la défense","Des défaillances de gestion : aucun responsable, aucune entrée d’inventaire et aucune vérification des dépendances cryptographiques à la mise hors service"]}},{"n":16,"answer":"C","section":{"en":"Certificates, PKI, and machine trust","fr":"Certificats, ICP et confiance entre machines"},"q":{"en":"Under SC-081, public TLS certificate validity falls to 47 days by 2029. Roughly how many renewals per certificate per year does this imply, compared with one today?","fr":"En vertu du scrutin SC-081, la durée de validité des certificats TLS publics passera à 47 jours d’ici 2029. Combien de renouvellements par certificat par année cela implique-t-il environ, comparativement à un seul aujourd’hui?"},"options":{"en":["About two renewals per year","About four renewals per year","About eight renewals per year","About twelve renewals per year"],"fr":["Environ deux renouvellements par année","Environ quatre renouvellements par année","Environ huit renouvellements par année","Environ douze renouvellements par année"]}},{"n":17,"answer":"C","section":{"en":"Certificates, PKI, and machine trust","fr":"Certificats, ICP et confiance entre machines"},"q":{"en":"Under CA/Browser Forum ballot SC-081, what is the maximum validity of a publicly trusted TLS certificate issued on or after March 15, 2027?","fr":"En vertu du scrutin SC-081 du CA/Browser Forum, quelle est la durée de validité maximale d’un certificat TLS de confiance publique délivré le 15 mars 2027 ou après?"},"options":{"en":["200 days","47 days","100 days","398 days"],"fr":["200 jours","47 jours","100 jours","398 jours"]}},{"n":18,"answer":"B","section":{"en":"Post-quantum cryptography and crypto-agility as a governance program","fr":"La cryptographie post-quantique et l’agilité cryptographique en tant que programme de gouvernance"},"q":{"en":"Why does harvest-now-decrypt-later make post-quantum migration a present-day concern?","fr":"Pourquoi le risque « récolter maintenant, déchiffrer plus tard » fait-il de la migration post-quantique une préoccupation actuelle?"},"options":{"en":["Because current symmetric encryption is already broken by quantum computers","Because exposure for long-lived data begins when it is intercepted, not when a quantum computer appears","Because NIST has already disallowed RSA and elliptic curve algorithms","Because quantum computers can alter digital signatures retroactively"],"fr":["Parce que le chiffrement symétrique actuel est déjà cassé par les ordinateurs quantiques","Parce que l’exposition des données à longue durée de vie commence au moment de leur interception, et non à l’apparition d’un ordinateur quantique","Parce que le NIST a déjà interdit les algorithmes RSA et à courbes elliptiques","Parce que les ordinateurs quantiques peuvent modifier rétroactivement les signatures numériques"]}},{"n":19,"answer":"A","section":{"en":"Post-quantum cryptography and crypto-agility as a governance program","fr":"La cryptographie post-quantique et l’agilité cryptographique en tant que programme de gouvernance"},"q":{"en":"Which NIST standard specifies the algorithm intended as the primary mechanism for establishing shared keys in the post-quantum transition?","fr":"Quelle norme du NIST précise l’algorithme destiné à être le principal mécanisme d’établissement de clés partagées dans la transition post-quantique?"},"options":{"en":["FIPS 203, specifying ML-KEM","FIPS 204, specifying ML-DSA","FIPS 205, specifying SLH-DSA","FIPS 206, specifying FN-DSA"],"fr":["FIPS 203, qui précise ML-KEM","FIPS 204, qui précise ML-DSA","FIPS 205, qui précise SLH-DSA","FIPS 206, qui précise FN-DSA"]}},{"n":20,"answer":"D","section":{"en":"Integration with privacy, data protection, and cross-border obligations","fr":"Intégration avec les obligations en matière de vie privée, de protection des données et de transferts transfrontaliers"},"q":{"en":"After encrypted customer data is stolen, what most determines whether encryption counts as a mitigating factor in a Law 25, PIPEDA, or GDPR breach assessment?","fr":"Après le vol de données de clients chiffrées, qu’est-ce qui détermine le plus si le chiffrement compte comme facteur atténuant dans l’évaluation d’une violation au sens de la Loi 25, de la LPRPDE ou du RGPD?"},"options":{"en":["Whether the encryption algorithm was selected by the vendor","Whether the data was stored in a Canadian data centre","Whether the organization holds an ISO/IEC 27001 certificate","Whether the organization can prove the keys were not compromised"],"fr":["Le fait que l’algorithme de chiffrement ait été choisi par le fournisseur","Le fait que les données aient été stockées dans un centre de données canadien","Le fait que l’organisation soit titulaire d’un certificat ISO/IEC 27001","Le fait que l’organisation puisse prouver que les clés n’ont pas été compromises"]}}]},{"n":21,"title":{"en":"Chapter 21: People, Organizational Design, and Accountability Mechanisms","fr":"Chapitre 21 : Personnes, conception organisationnelle et mécanismes de reddition de comptes"},"questions":[{"n":1,"answer":"A","section":{"en":"Cybersecurity as an operating model: the managerial lens","fr":"La cybersécurité comme modèle opérationnel : le point de vue du gestionnaire"},"q":{"en":"A security architect approves exceptions to her own designs, and the SOC sets its own risk thresholds. What problem does this illustrate?","fr":"Une architecte de sécurité approuve les exceptions à ses propres conceptions, et le COS fixe ses propres seuils de risque. Quel problème cela illustre-t-il?"},"options":{"en":["Blurred decision rights between governance, enablement, and operations work","An overly centralized model that lacks business-aligned security roles","A missing third line of independent internal audit assurance","A shortage of technical skills within the security operations team"],"fr":["Des droits décisionnels flous entre le travail de gouvernance, d’habilitation et d’opérations","Un modèle trop centralisé, dépourvu de rôles de sécurité alignés sur les activités","L’absence d’une troisième ligne d’assurance indépendante par l’audit interne","Une pénurie de compétences techniques au sein de l’équipe des opérations de sécurité"]}},{"n":2,"answer":"C","section":{"en":"Workforce planning, skills frameworks, and the talent problem","fr":"Planification de la main-d’œuvre, cadres de compétences et problème du talent"},"q":{"en":"In 2026, the NICE Framework Components version 2.2.0 added a new work role. Which one?","fr":"En 2026, la version 2.2.0 des NICE Framework Components a ajouté un nouveau rôle de travail. Lequel?"},"options":{"en":["Business information security officer","AI security engineer","Cybersecurity supply chain risk management","Security awareness program manager"],"fr":["Responsable de la sécurité de l’information d’unité d’affaires","Ingénieur en sécurité de l’IA","Gestion des risques de cybersécurité liés à la chaîne d’approvisionnement","Gestionnaire de programme de sensibilisation à la sécurité"]}},{"n":3,"answer":"B","section":{"en":"Cybersecurity as an operating model: the managerial lens","fr":"La cybersécurité comme modèle opérationnel : le point de vue du gestionnaire"},"q":{"en":"A CISO directly runs the security operations centre. Where does this place the CISO in the Three Lines Model?","fr":"Un CSI dirige lui-même le centre des opérations de sécurité. Où cela le place-t-il dans le modèle des trois lignes?"},"options":{"en":["In the third line, providing independent assurance","In the first line, operating controls","In the governing body, overseeing management","Outside the model, as an external provider"],"fr":["Dans la troisième ligne, qui fournit une assurance indépendante","Dans la première ligne, qui exploite les contrôles","Dans l’organe de gouvernance, qui surveille la direction","En dehors du modèle, comme fournisseur externe"]}},{"n":4,"answer":"D","section":{"en":"Board oversight and director competence","fr":"Surveillance par le conseil d’administration et compétence des administrateurs"},"q":{"en":"According to the chapter, which of the following should a board leave to management rather than do itself?","fr":"Selon le chapitre, lequel des éléments suivants un conseil d’administration devrait-il laisser à la direction plutôt que de s’en charger lui-même?"},"options":{"en":["Approving the risk appetite statement for cyber and technology risk","Understanding the most material cyber risk scenarios and impacts","Ensuring investment is commensurate with risk","Selecting security products and reviewing vulnerability scan results"],"fr":["Approuver l’énoncé d’appétence pour le risque en matière de cyberrisque et de risque technologique","Comprendre les scénarios de cyberrisque les plus importants et leurs impacts","Veiller à ce que l’investissement soit proportionné au risque","Choisir les produits de sécurité et examiner les résultats des analyses de vulnérabilités"]}},{"n":5,"answer":"D","section":{"en":"Board oversight and director competence","fr":"Surveillance par le conseil d’administration et compétence des administrateurs"},"q":{"en":"Under DORA Article 5, what is expected of members of a financial entity's management body regarding ICT risk?","fr":"En vertu de l’article 5 de DORA, qu’attend-on des membres de l’organe de direction d’une entité financière en ce qui concerne le risque lié aux TIC?"},"options":{"en":["They must delegate all ICT risk decisions to the CISO","They must hold a recognized cybersecurity certification","They must appoint a dedicated board cyber committee","They must actively keep up to date with sufficient knowledge and skills to assess ICT risk"],"fr":["Qu’ils délèguent au CSI toutes les décisions relatives au risque lié aux TIC","Qu’ils détiennent une certification reconnue en cybersécurité","Qu’ils créent un comité du conseil consacré à la cybersécurité","Qu’ils maintiennent activement à jour des connaissances et des compétences suffisantes pour évaluer le risque lié aux TIC"]}},{"n":6,"answer":"B","section":{"en":"Board oversight and director competence","fr":"Surveillance par le conseil d’administration et compétence des administrateurs"},"q":{"en":"What do the SEC's 2023 cybersecurity disclosure rules require public companies to describe annually under Item 106 of Regulation S-K?","fr":"Que les règles de 2023 de la SEC sur la communication d’information en matière de cybersécurité exigent-elles des sociétés ouvertes qu’elles décrivent chaque année en vertu de l’Item 106 du Regulation S-K?"},"options":{"en":["Whether each director has formal cybersecurity expertise","The board's oversight of cyber risk and management's role and expertise","The number of attacks blocked and patches deployed each quarter","The name and compensation of the chief information security officer"],"fr":["Si chaque administrateur possède une expertise officielle en cybersécurité","La surveillance du cyberrisque par le conseil ainsi que le rôle et l’expertise de la direction","Le nombre d’attaques bloquées et de correctifs déployés chaque trimestre","Le nom et la rémunération du chef de la sécurité de l’information"]}},{"n":7,"answer":"C","section":{"en":"Incentives and performance: aligning behaviour with risk reality","fr":"Incitatifs et performance : harmoniser les comportements avec la réalité des risques"},"q":{"en":"Delivery teams are rewarded only for speed and features, and executives only for short-term financial results. What does the chapter call the resulting dynamic?","fr":"Les équipes de livraison ne sont récompensées que pour la rapidité et les fonctionnalités, et les dirigeants, que pour les résultats financiers à court terme. Comment le chapitre appelle-t-il la dynamique qui en résulte?"},"options":{"en":["Compliance theatre replacing control effectiveness","Diffusion of responsibility across delivery teams","The silent externalization of risk","Concentration of decision rights at the top"],"fr":["La conformité de façade qui remplace l’efficacité des contrôles","La dilution de la responsabilité entre les équipes de livraison","L’externalisation silencieuse du risque","La concentration des droits décisionnels au sommet"]}},{"n":8,"answer":"A","section":{"en":"Decision rights: who decides what, and at what level","fr":"Droits décisionnels : qui décide quoi, et à quel niveau"},"q":{"en":"A product owner wants to launch with a weakness the CISO considers unacceptable. What is the CISO's essential decision right?","fr":"Un responsable de produit veut lancer un produit qui comporte une faiblesse que le CSI juge inacceptable. Quel est le droit décisionnel essentiel du CSI?"},"options":{"en":["To escalate to a level owning both outcomes and have dissent recorded","To veto the launch until the weakness has been fully remediated","To accept the risk on the business's behalf with compensating controls","To defer the decision to internal audit for an independent opinion"],"fr":["Soumettre la question à un niveau responsable des deux résultats et faire consigner son désaccord","Opposer son veto au lancement jusqu’à la correction complète de la faiblesse","Accepter le risque au nom des activités, avec des contrôles compensatoires","Confier la décision à l’audit interne pour obtenir une opinion indépendante"]}},{"n":9,"answer":"B","section":{"en":"Accountability mechanisms: how organizations make security enforceable","fr":"Mécanismes de reddition de comptes : comment les organisations rendent la sécurité exécutoire"},"q":{"en":"An organization's exception register grows every quarter and is rarely reduced. What does the chapter say this most likely indicates?","fr":"Le registre des exceptions d’une organisation augmente chaque trimestre et diminue rarement. Selon le chapitre, qu’est-ce que cela indique le plus probablement?"},"options":{"en":["That the security team is approving exceptions too slowly","That requirements are unrealistic, teams are unfunded, or nobody enforces expiry","That internal audit is sampling too many exceptions","That business owners are refusing to request exceptions"],"fr":["Que l’équipe de sécurité approuve les exceptions trop lentement","Que les exigences sont irréalistes, que les équipes ne sont pas financées ou que personne ne fait respecter les échéances","Que l’audit interne échantillonne trop d’exceptions","Que les responsables métier refusent de demander des exceptions"]}},{"n":10,"answer":"D","section":{"en":"RACI and role clarity: preventing gaps, overlaps, and diffusion of responsibility","fr":"RACI et clarté des rôles : prévenir les lacunes, les chevauchements et la dilution de la responsabilité"},"q":{"en":"Which rule does the chapter set for a sound RACI?","fr":"Quelle règle le chapitre fixe-t-il pour une matrice RACI solide?"},"options":{"en":["Every activity should have at least two Accountable roles for resilience","The CISO should be Accountable for every security-related activity","Accountable and Responsible roles should always be the same person","Each activity has exactly one Accountable role with authority and resources"],"fr":["Chaque activité devrait avoir au moins deux approbateurs, par souci de résilience","Le CSI devrait être l’approbateur de toutes les activités liées à la sécurité","Les rôles d’approbateur et de responsable de l’exécution devraient toujours être confiés à la même personne","Chaque activité a exactement un approbateur, doté du pouvoir et des ressources nécessaires"]}},{"n":11,"answer":"C","section":{"en":"Incentives and performance: aligning behaviour with risk reality","fr":"Incitatifs et performance : harmoniser les comportements avec la réalité des risques"},"q":{"en":"What gives a balanced cybersecurity scorecard its governance value, according to the chapter?","fr":"Selon le chapitre, qu’est-ce qui donne sa valeur de gouvernance à un tableau de bord équilibré de la cybersécurité?"},"options":{"en":["Its mix of exactly half leading and half lagging indicators","Its comparison of the organization against industry benchmarks","Its owner and escalation threshold for each indicator","Its alignment with the number of controls in CIS Controls v8.1"],"fr":["Sa répartition exacte entre indicateurs avancés et indicateurs retardés, moitié-moitié","La comparaison de l’organisation avec des références sectorielles","Le responsable et le seuil de remontée de chaque indicateur","Son alignement sur le nombre de contrôles des CIS Controls v8.1"]}},{"n":12,"answer":"A","section":{"en":"RACI and role clarity: preventing gaps, overlaps, and diffusion of responsibility","fr":"Droits décisionnels : qui décide quoi, et à quel niveau"},"q":{"en":"In the chapter's sample RACI, who is Accountable for approving a security exception?","fr":"Dans la matrice RACI type du chapitre, qui est l’approbateur d’une exception de sécurité?"},"options":{"en":["The business risk owner","The CISO","The requesting team","The chief audit executive"],"fr":["Le responsable métier du risque","Le CSI","L’équipe qui fait la demande","Le chef de l’audit interne"]}},{"n":13,"answer":"C","section":{"en":"A practical blueprint: implementing accountable governance in stages","fr":"Un plan directeur pratique : mettre en œuvre une gouvernance imputable par étapes"},"q":{"en":"Which activities belong to the first stage of the chapter's staged blueprint for accountable governance?","fr":"Quelles activités appartiennent à la première étape du plan par étapes du chapitre pour une gouvernance imputable?"},"options":{"en":["Launching security champions and embedding review triggers","Expanding control testing and aligning internal audit with risk scenarios","Defining risk owners, control owners, the CISO mandate, and decision-rights tiers","Embedding governance into performance systems and board reporting"],"fr":["Lancer les ambassadeurs de la sécurité et intégrer des déclencheurs d’examen","Élargir les tests de contrôles et aligner l’audit interne sur les scénarios de risque","Définir les responsables du risque, les responsables des contrôles, le mandat du CSI et les niveaux de droits décisionnels","Intégrer la gouvernance aux systèmes de gestion de la performance et à la reddition de comptes au conseil"]}},{"n":14,"answer":"B","section":{"en":"Roles in a mature operating model: what executives should expect to exist","fr":"Les rôles dans un modèle opérationnel mature : ce que la direction devrait s’attendre à trouver"},"q":{"en":"A BISO reports only to the business unit leader and has become the unit's risk owner. How would the chapter assess this arrangement?","fr":"Un BISO ne relève que du dirigeant de l’unité d’affaires et est devenu le responsable du risque de l’unité. Comment le chapitre évaluerait-il cette situation?"},"options":{"en":["As ideal, because it brings security fully inside the business","As flawed: the BISO risks capture and should make business ownership effective, not replace it","As acceptable, provided the BISO also chairs the risk committee","As appropriate only in centralized security models"],"fr":["Comme idéale, parce qu’elle intègre entièrement la sécurité aux activités","Comme déficiente : le BISO risque d’être capté et devrait rendre effective la responsabilité des activités, non la remplacer","Comme acceptable, pourvu que le BISO préside aussi le comité des risques","Comme appropriée seulement dans les modèles de sécurité centralisés"]}},{"n":15,"answer":"A","section":{"en":"The CISO's accountability and the personal liability debate","fr":"L’imputabilité du CSI et le débat sur la responsabilité personnelle"},"q":{"en":"What did the conviction of Uber's former chief security officer specifically concern?","fr":"Sur quoi portait précisément la condamnation de l’ancien chef de la sécurité d’Uber?"},"options":{"en":["Concealment of a 2016 breach during an FTC investigation","Failure to prevent the 2016 breach of customer data","Misleading statements to investors about security practices","Failure to implement an information security program"],"fr":["La dissimulation d’une violation de 2016 pendant une enquête de la FTC","Le fait de ne pas avoir empêché la violation des données de clients de 2016","Des déclarations trompeuses aux investisseurs sur les pratiques de sécurité","Le fait de ne pas avoir mis en œuvre de programme de sécurité de l’information"]}},{"n":16,"answer":"D","section":{"en":"Workforce planning, skills frameworks, and the talent problem","fr":"Planification de la main-d’œuvre, cadres de compétences et problème du talent"},"q":{"en":"ISC2's 2025 study found 59% of respondents reporting critical or significant skills shortages, up from 44% a year earlier. What does the chapter conclude from this?","fr":"L’étude 2025 de l’ISC2 a révélé que 59 % des répondants signalaient des pénuries de compétences critiques ou importantes, contre 44 % un an plus tôt. Qu’en conclut le chapitre?"},"options":{"en":["That the headcount gap has been closed by automation","That external hiring alone will resolve the shortage within a year","That AI has reduced the need for cybersecurity skills","That the problem is shifting from headcount to skills, favouring mapping and development"],"fr":["Que l’écart d’effectif a été comblé par l’automatisation","Que le recrutement externe à lui seul réglera la pénurie en un an","Que l’IA a réduit le besoin de compétences en cybersécurité","Que le problème passe de l’effectif aux compétences, ce qui favorise la cartographie et le perfectionnement"]}},{"n":17,"answer":"A","section":{"en":"The security champions model: scaling security through the organization","fr":"Le modèle des ambassadeurs de la sécurité : étendre la sécurité à l’ensemble de l’organisation"},"q":{"en":"A champions program launched with enthusiasm is fading after a year. Which missing design condition does the chapter identify as producing nothing when absent?","fr":"Un programme d’ambassadeurs lancé avec enthousiasme s’essouffle après un an. Quelle condition de conception le chapitre présente-t-il comme ne produisant rien lorsqu’elle est absente?"},"options":{"en":["Protected time agreed with the champions' managers","A larger central security team to review champions' work","Mandatory annual awareness modules for all staff","Public rankings of each team's vulnerability counts"],"fr":["Du temps protégé convenu avec les gestionnaires des ambassadeurs","Une équipe centrale de sécurité plus grande pour examiner le travail des ambassadeurs","Des modules annuels obligatoires de sensibilisation pour tout le personnel","Des classements publics du nombre de vulnérabilités de chaque équipe"]}},{"n":18,"answer":"C","section":{"en":"Human risk management beyond awareness","fr":"La gestion du risque humain au-delà de la sensibilisation"},"q":{"en":"Under a just culture, how should the organization respond to an employee who honestly clicks a convincing phishing link and reports it at once?","fr":"Dans une culture juste, comment l’organisation devrait-elle réagir lorsqu’un employé clique de bonne foi sur un lien d’hameçonnage convaincant et le signale aussitôt?"},"options":{"en":["Apply disciplinary consequences to deter future errors","Publicly share the employee's name in awareness training","Treat it as a learning opportunity and improve systems","Exclude the employee from simulations to avoid skewing data"],"fr":["Appliquer des conséquences disciplinaires pour dissuader les erreurs futures","Divulguer publiquement le nom de l’employé dans la formation de sensibilisation","Traiter la situation comme une occasion d’apprentissage et améliorer les systèmes","Exclure l’employé des simulations pour éviter de fausser les données"]}},{"n":19,"answer":"D","section":{"en":"Human risk management beyond awareness","fr":"La gestion du risque humain au-delà de la sensibilisation"},"q":{"en":"The 2026 Verizon DBIR found the human element involved in 62% of analyzed breaches. What broader conclusion does the chapter draw?","fr":"Le Verizon DBIR 2026 a établi que le facteur humain était en cause dans 62 % des violations analysées. Quelle conclusion plus large le chapitre en tire-t-il?"},"options":{"en":["That technical controls matter less than awareness training","That most breaches are caused by malicious insiders","That annual awareness training should become monthly","That behaviour is shaped by roles, processes, tools, incentives, and culture and must be governed"],"fr":["Que les contrôles techniques comptent moins que la formation de sensibilisation","Que la plupart des violations sont causées par des initiés malveillants","Que la formation de sensibilisation annuelle devrait devenir mensuelle","Que le comportement est façonné par les rôles, les processus, les outils, les incitatifs et la culture, et doit être gouverné"]}},{"n":20,"answer":"B","section":{"en":"A practical blueprint: implementing accountable governance in stages","fr":"Un plan directeur pratique : mettre en œuvre une gouvernance imputable par étapes"},"q":{"en":"In the Laurentians credit union scenario, what did the no-blame review identify as the underlying cause of the help desk fraud?","fr":"Dans la mise en situation de la coopérative de crédit des Laurentides, quelle cause sous-jacente de la fraude au centre d’assistance la revue sans recherche de coupables a-t-elle relevée?"},"options":{"en":["A help desk agent who ignored the written procedure","An unowned verification process and an exception never revisited","A technical flaw in the core banking provider's platform","A board that had refused to fund multifactor authentication"],"fr":["Un agent du centre d’assistance qui a ignoré la procédure écrite","Un processus de vérification sans responsable et une exception jamais revue","Une faille technique dans la plateforme du fournisseur du système bancaire central","Un conseil d’administration qui avait refusé de financer l’authentification multifacteur"]}}]}]};
